/* محتوى مادة histology: ترويسة المادة + التبويبات + الأقسام (يُحقن داخل الصفحة عند فتح المادة). مولَّد من work/gen_histo.py */
(function(M){(M.pkg=M.pkg||{})["histology"]={"headA": "<div class=\"brand\"><span class=\"kvlogo\" role=\"img\" aria-label=\"KA-200 VAULT — Batch Kasr Al Ainy, Batch of 200\"><i class=\"kv-l\"></i><i class=\"kv-d\"></i></span><\/div>\n <div class=\"eyebrow\">Histology 101 · Dr. Zahra MCQs<\/div>\n \n <div class=\"sig\" dir=\"ltr\"><span class=\"sig-by\">Made By<\/span> <span class=\"sig-name\">Dr.Saif Youssry<\/span><\/div>", "headB": "<p class=\"lede\">أسئلة الاختيار من متعدد من ملزمة الدكتورة زهرة بمفاتيحها المطبوعة، مرتّبة بالفصول والأقسام كما في الملزمة، ومعها اختبار مخصّص وألعاب وتتبّع تقدّم. بقية التبويبات (الدراسة والبطاقات واختبارات الكتاب) أماكنها جاهزة وتُملأ عند إضافة الكتاب.<\/p>\n <div class=\"stats\"><div><b>4<\/b><span>فصول<\/span><\/div><div><b>54<\/b><span>قسمًا<\/span><\/div><div><b>1119<\/b><span>سؤال بمفتاح<\/span><\/div><\/div>", "body": "<nav class=\"tabs\" role=\"tablist\">\n <button role=\"tab\" data-tab=\"study\" aria-selected=\"true\">الدراسة<\/button>\n <button role=\"tab\" data-tab=\"cards\" aria-selected=\"false\">بطاقات الاسترجاع<\/button>\n <button role=\"tab\" data-tab=\"tests\" aria-selected=\"false\">اختبارات الكتاب<\/button>\n <button role=\"tab\" data-tab=\"galal\" aria-selected=\"false\"><bdi dir=\"ltr\">Dr.Zahra MCQs<\/bdi><\/button>\n <button role=\"tab\" data-tab=\"exam\" aria-selected=\"false\">اختبار مخصّص ومستواي<\/button>\n <button role=\"tab\" data-tab=\"games\" aria-selected=\"false\">🎮 ألعاب<\/button>\n <button role=\"tab\" data-tab=\"map\" aria-selected=\"false\">الروابط والأرقام<\/button>\n <button role=\"tab\" data-tab=\"prog\" aria-selected=\"false\">تقدّمي<\/button>\n <button role=\"tab\" data-tab=\"guide\" aria-selected=\"false\">دليل الاستخدام<\/button>\n<\/nav>\n\n<main>\n<section id=\"tab-study\" class=\"tabpane\" role=\"tabpanel\"><div class=\"hs-soon\" dir=\"rtl\" lang=\"ar\"><span class=\"hs-ic\" aria-hidden=\"true\">📖<\/span><h2>الدراسة — نص الكتاب<\/h2><p>هنا سيظهر نص كتاب الهستولوجي بنفس طريقة التشريح: النص كما هو بالحرف، وأدوات الحفظ في إطار منفصل، ووضع الاسترجاع الذي يُخفي النص لتختبر نفسك. لم نضف نص الكتاب بعد، والمتاح الآن أسئلة الدكتورة زهرة فقط.<\/p><button type=\"button\" class=\"btn\" data-goto=\"galal\">افتح أسئلة د. زهرة<\/button><\/div><\/section>\n<section id=\"tab-cards\" class=\"tabpane\" role=\"tabpanel\" hidden><div class=\"hs-soon\" dir=\"rtl\" lang=\"ar\"><span class=\"hs-ic\" aria-hidden=\"true\">🗂️<\/span><h2>بطاقات الاسترجاع<\/h2><p>بطاقات سؤال وجواب من نص الكتاب (اضغط لتكشف الإجابة ثم علّم «عرفتها» أو «لم أعرفها»). تُضاف مع نص الكتاب، وتفتح معها لعبة «مطابقة الأزواج» و«املأ الفراغ».<\/p><button type=\"button\" class=\"btn\" data-goto=\"galal\">افتح أسئلة د. زهرة<\/button><\/div><\/section>\n<section id=\"tab-tests\" class=\"tabpane\" role=\"tabpanel\" hidden><div class=\"hs-soon\" dir=\"rtl\" lang=\"ar\"><span class=\"hs-ic\" aria-hidden=\"true\">📝<\/span><h2>اختبارات الكتاب<\/h2><p>أسئلة الكتاب نفسها بمفتاحها المطبوع. ستظهر هنا عند إضافة الكتاب. أسئلة الدكتورة زهرة في تبويبها الخاص.<\/p><button type=\"button\" class=\"btn\" data-goto=\"galal\">افتح أسئلة د. زهرة<\/button><\/div><\/section>\n<section id=\"tab-galal\" class=\"tabpane\" role=\"tabpanel\" hidden><div class=\"card-bar\"><p class=\"note\">أسئلة اختيار من متعدد من ملزمة الدكتورة زهرة (<bdi dir=\"ltr\">Histology 101 — MCQs<\/bdi>) مرتّبة بالفصول ثم بأقسام المحاضرات، مع قسمَي «أسئلة القسم» و«أسئلة الامتحانات» لكل فصل. المفتاح كما هو مطبوع في الملزمة. اختر إجابة لترى المفتاح. الوسم الصغير بجانب السؤال يبيّن مصدره: <bdi dir=\"ltr\">DEP BOOK<\/bdi> لأسئلة القسم، ورقم الدفعة (مثل <bdi dir=\"ltr\">195<\/bdi> و<bdi dir=\"ltr\">196<\/bdi> و<bdi dir=\"ltr\">198<\/bdi>) لأسئلة الامتحانات السابقة. أسئلة الموضوعات بلا وسم لأن الملزمة لا تضع عليها وسمًا. الوسم الأصفر «مفتاح الملزمة مشكوك فيه» يعني أن المفتاح المطبوع يخالف المحتوى العلمي (يُشرح عند الإجابة).<\/p><span class=\"score\" id=\"gScore\"><\/span><button id=\"gClear\" class=\"btn clear\" type=\"button\">Clear<\/button><\/div><div class=\"gnav\"><label for=\"gSel\">القسم:<\/label><select id=\"gSel\"><option value=\"\">كل الأقسام (1119 سؤال)<\/option><optgroup label=\"Chapter 1 — Cytology\" data-src=\"zahra\" data-srclabel=\"Dr. Zahra MCQs\"><option value=\"h1_t01\">Cell membrane (41)<\/option><option value=\"h1_t02\">Mitochondria (17)<\/option><option value=\"h1_t03\">Endoplasmic reticulum (27)<\/option><option value=\"h1_t04\">Golgi apparatus (24)<\/option><option value=\"h1_t05\">Lysosomes (19)<\/option><option value=\"h1_t06\">Peroxisomes (9)<\/option><option value=\"h1_t07\">Ribosomes (20)<\/option><option value=\"h1_t08\">Microtubules &amp; Microfilaments (60)<\/option><option value=\"h1_t09\">Proteasomes (6)<\/option><option value=\"h1_t10\">Inclusions (23)<\/option><option value=\"h1_t11\">Nucleus &amp; Chromatin &amp; Nucleolus (29)<\/option><option value=\"h1_d12\">Department MCQs (63)<\/option><option value=\"h1_e13\">Exam MCQs (47)<\/option><\/optgroup><optgroup label=\"Chapter 2 — Blood\" data-src=\"zahra\" data-srclabel=\"Dr. Zahra MCQs\"><option value=\"h2_t01\">RBCs (31)<\/option><option value=\"h2_t02\">Neutrophils (18)<\/option><option value=\"h2_t03\">Eosinophils (12)<\/option><option value=\"h2_t04\">Basophils (15)<\/option><option value=\"h2_t05\">Lymphocytes (20)<\/option><option value=\"h2_t06\">Monocytes (5)<\/option><option value=\"h2_t07\">Platelets (18)<\/option><option value=\"h2_t08\">Bone marrow (8)<\/option><option value=\"h2_t09\">Reticulocytes (4)<\/option><option value=\"h2_t10\">Hemopoiesis (19)<\/option><option value=\"h2_d11\">Department MCQs (36)<\/option><option value=\"h2_e12\">Exam MCQs (37)<\/option><\/optgroup><optgroup label=\"Chapter 3 — Connective Tissue\" data-src=\"zahra\" data-srclabel=\"Dr. Zahra MCQs\"><option value=\"h3_t01\">Connective tissue characters (9)<\/option><option value=\"h3_t02\">UMCs &amp; Pericytes (8)<\/option><option value=\"h3_t03\">Fibroblasts (15)<\/option><option value=\"h3_t04\">Adipose cells (18)<\/option><option value=\"h3_t05\">Macrophages (21)<\/option><option value=\"h3_t06\">Reticular cells (4)<\/option><option value=\"h3_t07\">Mast cells (18)<\/option><option value=\"h3_t08\">Plasma cells (20)<\/option><option value=\"h3_t09\">Collagen fibers (25)<\/option><option value=\"h3_t10\">Elastic fibers (10)<\/option><option value=\"h3_t11\">Reticular fibers (6)<\/option><option value=\"h3_t12\">Loose areolar CT (9)<\/option><option value=\"h3_t13\">Reticular CT (5)<\/option><option value=\"h3_t14\">Adipose CT (8)<\/option><option value=\"h3_t15\">Mucoid CT (9)<\/option><option value=\"h3_t16\">Dense collagenous CT (3)<\/option><option value=\"h3_t17\">Elastic CT (6)<\/option><option value=\"h3_t18\">White fibrous CT (7)<\/option><option value=\"h3_d19\">Department MCQs (50)<\/option><option value=\"h3_e20\">Exam MCQs (23)<\/option><\/optgroup><optgroup label=\"Chapter 4 — Epithelium\" data-src=\"zahra\" data-srclabel=\"Dr. Zahra MCQs\"><option value=\"h4_t01\">Surface epithelium (87)<\/option><option value=\"h4_t02\">Glandular epithelium (16)<\/option><option value=\"h4_t03\">Neuroepithelium (3)<\/option><option value=\"h4_t04\">Myoepithelium (5)<\/option><option value=\"h4_t05\">Apical specialization (10)<\/option><option value=\"h4_t06\">Lateral specialization (28)<\/option><option value=\"h4_t07\">Basal specialization (16)<\/option><option value=\"h4_d08\">Department MCQs (49)<\/option><option value=\"h4_e09\">Exam MCQs (23)<\/option><\/optgroup><\/select><\/div><div class=\"gpart\" data-part=\"1\" data-ch=\"c1\"><h2 dir=\"ltr\">Chapter 1 · Cytology <small>— علم الخلية · 385 سؤال · <bdi dir=\"ltr\">Dr. Zahra MCQs<\/bdi><\/small><\/h2><section class=\"tsec gsec\" data-g=\"h1_t01\"><h3>Cell membrane <small>— 41 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t01\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-001\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">1- Cell membrane can be demonstrated by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III<\/li><li data-o=\"d\" tabindex=\"0\">d- Orcein<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-002\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">2- Pinocytosis is the process by which the cell can engulf:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fluid droplets<\/li><li data-o=\"b\" tabindex=\"0\">b- Solid particles<\/li><li data-o=\"c\" tabindex=\"0\">c- Hormones<\/li><li data-o=\"d\" tabindex=\"0\">d- Foreign bodies<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- Phagocytosis is the process by which the cell can engulf:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fluid droplets<\/li><li data-o=\"b\" tabindex=\"0\">b- Solid particles<\/li><li data-o=\"c\" tabindex=\"0\">c- Hormones<\/li><li data-o=\"d\" tabindex=\"0\">d- Foreign bodies<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-004\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">4- Receptor mediated endocytosis is the process by which the cell can engulf:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fluid droplets<\/li><li data-o=\"b\" tabindex=\"0\">b- Solid particles<\/li><li data-o=\"c\" tabindex=\"0\">c- Hormones<\/li><li data-o=\"d\" tabindex=\"0\">d- Foreign bodies<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- The cytoplasmic side of coated vesicles is associated with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Clathrin<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Actin<\/li><li data-o=\"d\" tabindex=\"0\">d- Spectrin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-006\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">6- Cell membrane can be stained by<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- sudan III<\/li><li data-o=\"b\" tabindex=\"0\">b- Trypan<\/li><li data-o=\"c\" tabindex=\"0\">c- Brilliant cresyl blue<\/li><li data-o=\"d\" tabindex=\"0\">d- Periodic acid Schiff reaction (PAS)<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-007\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">7- Protein on cytoplasmic side is in involved in receptor mediated endocytosis:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tubulin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Clathrin<\/li><li data-o=\"c\" tabindex=\"0\">c- Lamins<\/li><li data-o=\"d\" tabindex=\"0\">d- Spectrin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- The carbohydrate coat that is found on the outer surface of the cell membrane is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- plasmalemma.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycocalyx.<\/li><li data-o=\"c\" tabindex=\"0\">c- cristae.<\/li><li data-o=\"d\" tabindex=\"0\">d- cisternae<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-009\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">9- The process which is called cell drinking is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- endocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- exocytosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- pinocytosis<\/li><li data-o=\"d\" tabindex=\"0\">d- phagocytosis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-010\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">10- Cells extrude materials by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- endocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- exocytosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- pinocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-011\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">11- The cell limiting membrane is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- plasmalemma.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycocalyx.<\/li><li data-o=\"c\" tabindex=\"0\">c- cristae.<\/li><li data-o=\"d\" tabindex=\"0\">d- cisternae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-012\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">12- The process by which the cell membrane engulfs a solid particle is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- microcytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- exocytosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- pinocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-013\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">13- By EM, the cell membrane appears as:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lipid bilayer.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trilaminar.<\/li><li data-o=\"c\" tabindex=\"0\">c- unilaminar.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pentalaminar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-014\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">14- The function of cholesterol in the cell membrane is to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- act as channels.<\/li><li data-o=\"b\" tabindex=\"0\">b- stabilize the cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- act as receptors.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-015\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">15- Glycocalyx can be detected by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E.<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ag.<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-016\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">16- The carbohydrate content on the outer side of the plasma membrane is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycolipid.<\/li><li data-o=\"b\" tabindex=\"0\">b- glycocalyx.<\/li><li data-o=\"c\" tabindex=\"0\">c- glycoprotein.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-017\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">17- The endocytosis process include all the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple diffusion.<\/li><li data-o=\"b\" tabindex=\"0\">b- receptor mediated transport.<\/li><li data-o=\"c\" tabindex=\"0\">c- phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- pinocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Type of transport in which clathrin protein is involved is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- phagocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- pinocytosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- receptor mediated endocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- simple diffusion.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-019\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">19- Cell recognition and adhesion is a function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cholesterol.<\/li><li data-o=\"b\" tabindex=\"0\">b- intrinsic proteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cell coat.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- Concerning Dwarfism:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Growth hormone level is increased.<\/li><li data-o=\"b\" tabindex=\"0\">b- Growth hormone level may be normal, but defective receptors.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-021\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">21- Coated vesicles are surrounded by a coat of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- clathrin.<\/li><li data-o=\"b\" tabindex=\"0\">b- ubiquitin<\/li><li data-o=\"c\" tabindex=\"0\">c- desmin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-022\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">22- Glycocalyx is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- the protein component of the cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- the carbohydrate component of the cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- the hydrophilic end of lipid.<\/li><li data-o=\"d\" tabindex=\"0\">d- the hydrophobic end of lipid.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-023\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">23- Which molecule of the cell membrane has a stabilizing effect?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cholesterol.<\/li><li data-o=\"b\" tabindex=\"0\">b- cell coat.<\/li><li data-o=\"c\" tabindex=\"0\">c- Phospholipids.<\/li><li data-o=\"d\" tabindex=\"0\">d- Intrinsic proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-024\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">24- Cell membrane is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lipids.<\/li><li data-o=\"b\" tabindex=\"0\">b- Carbohydrates.<\/li><li data-o=\"c\" tabindex=\"0\">c- Proteins.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-025\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">25- The thickness of the cell membrane is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 7.5 - 10 mm.<\/li><li data-o=\"b\" tabindex=\"0\">b- 7.5 - 10 µm.<\/li><li data-o=\"c\" tabindex=\"0\">c- 7.5 - 10 nm.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-026\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">26- Cell membrane appears as trilaminar structure because:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is formed of phospholipids, carbohydrate and proteins.<\/li><li data-o=\"b\" tabindex=\"0\">b- Phospholipids molecules have hydrophilic head and hydrophobic tail.<\/li><li data-o=\"c\" tabindex=\"0\">c- The proteins are integral, embedded and transmembrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glycocalyx is present outside the cell membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-027\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">27- Cell membrane appears as trilaminar structure because:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Phospholipids molecules have hydrophilic head and hydrophobic tail.<\/li><li data-o=\"b\" tabindex=\"0\">b- Of the arrangement of phospholipids molecules bilayer.<\/li><li data-o=\"c\" tabindex=\"0\">c- Of deposition of heavy metals (osmium) in the hydrophilic heads of phospholipids.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-028\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">28- Phospholipids molecules in the cell membrane have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hydrophilic heads directed outwards.<\/li><li data-o=\"b\" tabindex=\"0\">b- Hydrophobic heads directed inwards.<\/li><li data-o=\"c\" tabindex=\"0\">c- Hydrophilic tails directed outwards.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-029\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">29- All the statements concerned to the cell membrane are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is known as plasma lemma.<\/li><li data-o=\"b\" tabindex=\"0\">b- All membranes of the cell have the same appearance.<\/li><li data-o=\"c\" tabindex=\"0\">c- By E/M it is formed of bilayer.<\/li><li data-o=\"d\" tabindex=\"0\">d- Invisible by light microscope.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-030\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">30- All the statements concerned to the trilaminar appearance of cell membrane are true EXCEPT<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is easy to see by light microscope.<\/li><li data-o=\"b\" tabindex=\"0\">b- Heavy metals deposits in the heads of the phospholipids bilayer.<\/li><li data-o=\"c\" tabindex=\"0\">c- Middle layer represents unstained hydrophobic tails.<\/li><li data-o=\"d\" tabindex=\"0\">d- Two outer electron-dense and middle electron-lucent layer.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-031\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">31- One of the followings is not a function of the cell membrane:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Active transport.<\/li><li data-o=\"b\" tabindex=\"0\">b- Passive diffusion.<\/li><li data-o=\"c\" tabindex=\"0\">c- Phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- RNA synthesis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-032\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">32- Cell membrane modifications mean:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell membrane modify to form microvilli.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cell membrane modify to form cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cell membrane modify to form flagella.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-033\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">33- Coated vesicles:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are vesicles which derived from the cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Coated by clathrin from the outside.<\/li><li data-o=\"c\" tabindex=\"0\">c- Contain ingested macromolecules as hormones.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-034\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">34- Clathrin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Is a protein coats the cytoplasmic surface of the cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is a protein coats the outer surface of the cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Is a specific receptor for ligand.<\/li><li data-o=\"d\" tabindex=\"0\">d- A specific enzyme presents inside the endosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-035\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">35- The following organelles are non-membranous organelles EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Coated vesicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Centrosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-036\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">36- About function of cell coat, which of the followings is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- important for cell recognition.<\/li><li data-o=\"b\" tabindex=\"0\">b- important for cell adhesion.<\/li><li data-o=\"c\" tabindex=\"0\">c- site of receptors.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-037\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">37- By EM cell membrane:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- appear formed of 3 layers.<\/li><li data-o=\"b\" tabindex=\"0\">b- have outer &amp; inner electron dense.<\/li><li data-o=\"c\" tabindex=\"0\">c- have middle electron lucent.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-038\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">38- The cell membrane’s thickness ranges from:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 4-6 nm thick.<\/li><li data-o=\"b\" tabindex=\"0\">b- 6-7.5 nm thick.<\/li><li data-o=\"c\" tabindex=\"0\">c- 7.5-10 nm thick.<\/li><li data-o=\"d\" tabindex=\"0\">d- 10-30 nm thick.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-039\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">39- Cell membrane can be stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- AG.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trypan blue<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron haematoxylin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-040\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">40- Regarding the cell membrane, the following is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Non-membranous organelle.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its function is cell respiration<\/li><li data-o=\"c\" tabindex=\"0\">c- Stained by H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Appear by EM as 3 layers<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-041\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">41- The cytoplasmic side of the coated vesicle is surrounded by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Clathrin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubulin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Actin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Spectrin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t02\"><h3>Mitochondria <small>— 17 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t02\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-042\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">42- Which of the following can be stained by iron hematoxylin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centrioles<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a&amp;b<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-043\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">43- The cytoplasmic organelle which contains DNA &amp; RNA is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria<\/li><li data-o=\"b\" tabindex=\"0\">b- Ribosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- rER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-044\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">44- Kreb’s cycle occurs in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondrial matrix<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondrial inner membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Peroxisomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-045\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">45- Energy production is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus<\/li><li data-o=\"b\" tabindex=\"0\">b- Rough endoplasmic reticulum<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria<\/li><li data-o=\"d\" tabindex=\"0\">d- Smooth endoplasmic reticulum<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-046\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">46- The true statement about mitochondria is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Self-replicating organelle<\/li><li data-o=\"b\" tabindex=\"0\">b- Outer membrane forms cristae<\/li><li data-o=\"c\" tabindex=\"0\">c- Non membranous organelle<\/li><li data-o=\"d\" tabindex=\"0\">d- inner membrane is smooth<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-047\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">47- The power house of the cell is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-048\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">48- The inner folds of mitochondrial membrane are called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- plasmalemma.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycocalyx.<\/li><li data-o=\"c\" tabindex=\"0\">c- cristae.<\/li><li data-o=\"d\" tabindex=\"0\">d- cisternae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-049\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">49- Mitochondria are numerous in cells that are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Dead.<\/li><li data-o=\"b\" tabindex=\"0\">b- Metabolically active.<\/li><li data-o=\"c\" tabindex=\"0\">c- Metabolically inactive.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-050\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">50- Which of the following organelles best demonstrated by iron hematoxylin stain:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centrioles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Both a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-051\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">51- The mitochondrial matrix contains all the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Enzymes for kreb’s cycle.<\/li><li data-o=\"b\" tabindex=\"0\">b- DNA &amp; RNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- phosphorus granules.<\/li><li data-o=\"d\" tabindex=\"0\">d- calcium granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-052\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">52- Which of the following characterized by self-duplication:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centrioles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi complex.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-053\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">53- Mitochondria:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- can move and divide.<\/li><li data-o=\"b\" tabindex=\"0\">b- cristae are carrying ATP synthetase to produce ATP.<\/li><li data-o=\"c\" tabindex=\"0\">c- can generate heat.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-054\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">54- Enzymes for oxidative phosphorylation are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- outer mitochondrial membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- inner mitochondrial membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- mitochondrial matrix.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-055\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">55- Enzymes for Krebs cycle are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Studded on the inner surface of the outer membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Found in the matrix space.<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in the globular structure on the outer surface.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in the intermembranous space.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-056\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">56- The ADP to ATP phosphorylating system is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Found in the matrix space.<\/li><li data-o=\"b\" tabindex=\"0\">b- Studded on the inner surface of the outer membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in the globular structure on the inner surface.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-057\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">57- Mitochondria plays a role in regulation of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Sodium metabolism.<\/li><li data-o=\"b\" tabindex=\"0\">b- Sulfur metabolism.<\/li><li data-o=\"c\" tabindex=\"0\">c- Calcium metabolism.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-058\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">58- Cell organelle surrounded by 2 membranes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a&amp;b<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t03\"><h3>Endoplasmic reticulum <small>— 27 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t03\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-059\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">59- Detoxification of drugs is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER<\/li><li data-o=\"b\" tabindex=\"0\">b- rER<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-060\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">60- Rough endoplasmic reticulum is involved in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Steroid synthesis<\/li><li data-o=\"b\" tabindex=\"0\">b- Cell recognition<\/li><li data-o=\"c\" tabindex=\"0\">c- Protein synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Energy production<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-061\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">61- The smooth endoplasmic reticulum is concerned with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Calcium pumping in muscle contraction<\/li><li data-o=\"b\" tabindex=\"0\">b- Energy production<\/li><li data-o=\"c\" tabindex=\"0\">c- Protein synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Packaging of proteins<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-062\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">62- Smooth endoplasmic reticulum is involved in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Protein synthesis<\/li><li data-o=\"b\" tabindex=\"0\">b- Energy production<\/li><li data-o=\"c\" tabindex=\"0\">c- Steroid synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Cell recognition<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-063\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">63- Detoxification of drug needs mainly numerous:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER<\/li><li data-o=\"b\" tabindex=\"0\">b- ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- rER<\/li><li data-o=\"d\" tabindex=\"0\">d- both b&amp;c<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-064\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">64- One is a LM feature of rough endoplasmic reticulum (rER):<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes attach to the surface<\/li><li data-o=\"b\" tabindex=\"0\">b- Have ribophorin receptors<\/li><li data-o=\"c\" tabindex=\"0\">c- Extend from nuclear to cell membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Appear basophilic<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-065\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">65- The E.M. feature of smooth endoplasmic reticulum (SER) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosome attach to its surface<\/li><li data-o=\"b\" tabindex=\"0\">b- Anastomosing tubular cisternae of various shape<\/li><li data-o=\"c\" tabindex=\"0\">c- Have ribophorin receptors<\/li><li data-o=\"d\" tabindex=\"0\">d- either apical or perinuclear<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-066\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">66- Electron microscopic feature of cells responsible for steroid hormone secretion is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Numerous proteasomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Numerous ribosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed sER<\/li><li data-o=\"d\" tabindex=\"0\">d- Well-developed rER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-067\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">67- Electron microscopic feature of protein forming cells is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Numerous lysosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Numerous peroxisomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed sER<\/li><li data-o=\"d\" tabindex=\"0\">d- Well-developed rER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-068\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">68- The organelle which contains ribosomes attached to its surface:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-069\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">69- The organelle involved in the lipid metabolism is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-070\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">70- SER has the following functions EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of protein.<\/li><li data-o=\"b\" tabindex=\"0\">b- Detoxification of drugs.<\/li><li data-o=\"c\" tabindex=\"0\">c- Synthesis of lipids<\/li><li data-o=\"d\" tabindex=\"0\">d- Storage of Ca++<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-071\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">71- Transfer vesicles are formed by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- sER.<\/li><li data-o=\"d\" tabindex=\"0\">d- mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-072\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">72- By EM, rER appears as:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- double membrane large organoid.<\/li><li data-o=\"b\" tabindex=\"0\">b- small membranous vesicles.<\/li><li data-o=\"c\" tabindex=\"0\">c- irregular branching and anastomosing tubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- regular flattened membranous cisternae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-073\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">73- By EM, sER appears as:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- double membrane large organoid.<\/li><li data-o=\"b\" tabindex=\"0\">b- small membranous vesicles.<\/li><li data-o=\"c\" tabindex=\"0\">c- irregular branching and anastomosing tubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- regular flattened membranous cisternae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-074\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">74- Concerning the rER, one statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of two membranes, the inner is studded by ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of two membranes, the outer is studded by ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of one membrane, the outer surface is studded by ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Formed of one membranes, the inner surface is studded by ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-075\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">75- Function of RER is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of fatty acids and lipids.<\/li><li data-o=\"b\" tabindex=\"0\">b- Synthesis cytoplasmic matrix proteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Synthesis of secreted proteins.<\/li><li data-o=\"d\" tabindex=\"0\">d- Segregation of proteins synthesized by bound ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-076\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">76- Segregated proteins in RER are delivered in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretory vesicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Transfer vesicles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Polysomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Endosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-077\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">77- Transfer vesicles:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Carry the segregated proteins to the Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Transfer proteins to the cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Transfer tRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-078\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">78- Concerning the RER, one statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Proteins are synthesized inside its lumen.<\/li><li data-o=\"b\" tabindex=\"0\">b- Synthesized proteins are segregated inside its lumen.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its tubules sometimes continuous with cell membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- It is prominent in lipid storing cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-079\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">79- All the statements concerning SER are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Found in lipid synthesizing cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Responsible for detoxification of toxins and drugs.<\/li><li data-o=\"c\" tabindex=\"0\">c- It is double membrane organelle.<\/li><li data-o=\"d\" tabindex=\"0\">d- In the muscle, it is called sarcoplasmic reticulum.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-080\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">80- SER has the following function:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of steroid hormones.<\/li><li data-o=\"b\" tabindex=\"0\">b- Protein synthesis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Storage of phosphate.<\/li><li data-o=\"d\" tabindex=\"0\">d- Formation of transfer vesicles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-081\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">81- SER has the following functions EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of fatty acids and lipids.<\/li><li data-o=\"b\" tabindex=\"0\">b- Synthesis and breakdown of glycogen.<\/li><li data-o=\"c\" tabindex=\"0\">c- Synthesis of steroid hormones.<\/li><li data-o=\"d\" tabindex=\"0\">d- Synthesis of integral proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-082\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">82- In the striated muscle, SER is concerned with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ca ion distribution.<\/li><li data-o=\"b\" tabindex=\"0\">b- Na ion distribution.<\/li><li data-o=\"c\" tabindex=\"0\">c- K ion distribution.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-083\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">83- All are true about rER EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- formed of intercommunicating cisternae.<\/li><li data-o=\"b\" tabindex=\"0\">b- continuous with outer nuclear surface.<\/li><li data-o=\"c\" tabindex=\"0\">c- responsible for drug detoxication in liver.<\/li><li data-o=\"d\" tabindex=\"0\">d- is studded with ribosomes on their outer surface.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-084\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">84- Cytoplasmic basophilia reflects the abundance of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- sER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-085\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">85- Which statement is correct about sER?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is involved in protein formation.<\/li><li data-o=\"b\" tabindex=\"0\">b- It has a role in calcium pump.<\/li><li data-o=\"c\" tabindex=\"0\">c- It has a role in digestion.<\/li><li data-o=\"d\" tabindex=\"0\">d- It has a role in sodium pump.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t04\"><h3>Golgi apparatus <small>— 24 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t04\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-086\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">86- The cytoplasmic organelle responsible for renewal and maintenance of cell membrane is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- sER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-087\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">87- Which of the followings don&#x27;t originate from Golgi apparatus<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretory vesicles<\/li><li data-o=\"b\" tabindex=\"0\">b- Transfer vesicles<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-088\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">88- Silver staining is used to demonstrate:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus &amp; cell membrane<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria &amp; sER<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria &amp; cell membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes &amp; Golgi apparatus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-089\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">89- Maintenance of the cell membrane is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria<\/li><li data-o=\"b\" tabindex=\"0\">b- Smooth endoplasmic reticulum<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Rough endoplasmic reticulum<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-090\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">90- In secretory cells, the Golgi body is located:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Apical<\/li><li data-o=\"b\" tabindex=\"0\">b- Basal<\/li><li data-o=\"c\" tabindex=\"0\">c- Perinuclear<\/li><li data-o=\"d\" tabindex=\"0\">d- Eccentric<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-091\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">91- Negative Golgi image is evident when stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver (Ag)<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron Haematoxylin<\/li><li data-o=\"d\" tabindex=\"0\">d- H&amp;E<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-092\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">92- As regards Golgi apparatus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Detected by sudan III stain<\/li><li data-o=\"b\" tabindex=\"0\">b- Apical in the secretory cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of actin filaments<\/li><li data-o=\"d\" tabindex=\"0\">d- Detoxifies drugs and alcohol<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-093\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">93- The organelle that packages proteins within the cell is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-094\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">94- Golgi complex could be stained as brown granules &amp; Fibrils by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E.<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- silver.<\/li><li data-o=\"d\" tabindex=\"0\">d- Integral membrane proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-095\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">95- Golgi complex is composed of all of the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- saccules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Transfer vesicles.<\/li><li data-o=\"c\" tabindex=\"0\">c- pinocytotic vesicles.<\/li><li data-o=\"d\" tabindex=\"0\">d- secretory vesicles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-096\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">96- All of the following are products of Golgi Apparatus EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- secretory vesicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- transfer vesicles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Integral membrane proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-097\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">97- Perinuclear golgi apparatus is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Enteroendocrine cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Epididymis.<\/li><li data-o=\"c\" tabindex=\"0\">c- secretory cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- nerve cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-098\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">98- Which of the following share in maintenance and renewal of cell membrane?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi.<\/li><li data-o=\"b\" tabindex=\"0\">b- lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- coated vesicles.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-099\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">99- Golgi apparatus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Appears as negative Golgi image when cells stained with silver.<\/li><li data-o=\"b\" tabindex=\"0\">b- Appears as granular network when the cells stained with H/E.<\/li><li data-o=\"c\" tabindex=\"0\">c- Variable in size, shape and position.<\/li><li data-o=\"d\" tabindex=\"0\">d- Easy to see in routine histological sections.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-100\" data-k=\"d\" data-fx=\"المفتاح المطبوع d (الـGolgi موجود وبكثرة في الخلايا المُصنِّعة للبروتين) هو الخطأ الأوضح. والخيار b أيضًا غير دقيق، لأن الـGolgi في صبغة الـH&E لا يظهر كصورة موجبة بل كمنطقة فاتحة سالبة (negative Golgi image).\"><p class=\"qt\" dir=\"ltr\">100- Concerning the Golgi complex, all the statements are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stained with silver.<\/li><li data-o=\"b\" tabindex=\"0\">b- Appears as Golgi image in H/E sections.<\/li><li data-o=\"c\" tabindex=\"0\">c- Variable in size, shape and position.<\/li><li data-o=\"d\" tabindex=\"0\">d- Not present in protein synthesizing cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-101\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">101- Golgi have the following functions EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of polypeptide chains.<\/li><li data-o=\"b\" tabindex=\"0\">b- Packing of proteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Condensation of proteins.<\/li><li data-o=\"d\" tabindex=\"0\">d- Modification of proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-102\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">102- To demonstrate the Golgi Apparatus distinctly they need:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Green Janus B.<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron hematoxylin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-103\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">103- Negative Golgi image appears:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- in plasma cells &amp; osteoblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- when stained by H&amp;E.<\/li><li data-o=\"c\" tabindex=\"0\">c- when Golgi is small.<\/li><li data-o=\"d\" tabindex=\"0\">d- botha &amp; b.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-104\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">104- Storage, packaging and chemical modification of proteins occur in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Attached ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoskeleton.<\/li><li data-o=\"c\" tabindex=\"0\">c- Free ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-105\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">105- Smooth endoplasmic reticulum is involved in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Detoxification of drugs<\/li><li data-o=\"b\" tabindex=\"0\">b- protein synthesis<\/li><li data-o=\"c\" tabindex=\"0\">c- Energy production.<\/li><li data-o=\"d\" tabindex=\"0\">d- Cell recognition<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-106\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">106- Regarding Golgi apparatus, which statement is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of parallel flattened cisternae.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have Cis and Trans faces<\/li><li data-o=\"c\" tabindex=\"0\">c- Involved in glycogen breakdown.<\/li><li data-o=\"d\" tabindex=\"0\">d- Involved in cell respiration<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-107\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">107- The secretory vesicles in a cell arise from:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tubules of sER<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubules of rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-108\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">108- Two organelles share in the formation of lysosomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER &amp; sER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER &amp; Golgi apparatus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus &amp; cell membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- rER &amp; Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-109\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">109- As regards Golgi apparatus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present around nucleus in nerve cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Always apical in all the cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of parallel cisternae.<\/li><li data-o=\"d\" tabindex=\"0\">d- Detoxifies drugs and alcohol.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t05\"><h3>Lysosomes <small>— 19 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t05\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-110\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">110- Lysosomes are stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Metachromatic stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histochemical stain for catalase.<\/li><li data-o=\"c\" tabindex=\"0\">c- Histochemical stain as acid phosphatase.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histochemical stain as alkaline phosphatase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-111\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">111- Thyroid hormones can be activated by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi apparatus<\/li><li data-o=\"c\" tabindex=\"0\">c- lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- peroxisomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-112\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">112- Multivesicular bodies are formed when:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 1ry lysosomes fuse with phagosome<\/li><li data-o=\"b\" tabindex=\"0\">b- 1ry lysosomes fuse with pinocytic vesicles<\/li><li data-o=\"c\" tabindex=\"0\">c- 1ry lysosomes fuse with old organelles<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-113\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">113- Autolysosomes are formed when a 1ry lysosome fuses with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- An old organelle<\/li><li data-o=\"b\" tabindex=\"0\">b- A phagosome<\/li><li data-o=\"c\" tabindex=\"0\">c- A pinocytotic vesicle<\/li><li data-o=\"d\" tabindex=\"0\">d- A residual body<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-114\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">114- Lysosomes are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed by rER &amp; Golgi apparatus<\/li><li data-o=\"b\" tabindex=\"0\">b- non membranous organelle<\/li><li data-o=\"c\" tabindex=\"0\">c- Demonstrated by H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are few in phagocytic cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-115\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">115- Multivesicular bodies:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are formed by fusion of primary lysosomes with old organelle<\/li><li data-o=\"b\" tabindex=\"0\">b- Are a type of primary lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Appear homogenous by EM<\/li><li data-o=\"d\" tabindex=\"0\">d- Are formed by fusion of primary lysosomes with pinocytic vesicles<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-116\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">116- Regarding multivesicular body, they are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type of primary lysosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Also known as residual body<\/li><li data-o=\"c\" tabindex=\"0\">c- secondary lysosome with fluid content<\/li><li data-o=\"d\" tabindex=\"0\">d- Only found in cardiac and nerve cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-117\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">117- Hydrolytic enzymes are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- sER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-118\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">118- All of the following are types of secondary lysosomes EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Multivesicular body.<\/li><li data-o=\"b\" tabindex=\"0\">b- Residual body.<\/li><li data-o=\"c\" tabindex=\"0\">c- Heterolysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Barr body.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-119\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">119- Lysosomes are stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E.<\/li><li data-o=\"b\" tabindex=\"0\">b- Metachromatic stain.<\/li><li data-o=\"c\" tabindex=\"0\">c- Histochemical stain detecting acid phosphatase.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histochemical stain detecting alkaline phosphatase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-120\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">120- Homogenous electron dense membrane limited granules are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- primary lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- secondary lysosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Free ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- attached ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-121\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">121- One statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Primary lysosome fuses with phagosome to form secondary lysosome.<\/li><li data-o=\"b\" tabindex=\"0\">b- Primary lysosome fuses with secondary lysosome to form phagosome<\/li><li data-o=\"c\" tabindex=\"0\">c- Secondary lysosome fuses with primary lysosome to form phagosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-122\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">122- Residual bodies:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are the digested material in the secondary lysosome.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are the undigested material in the secondary lysosome.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are the undigested material in multivesicular bodies.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-123\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">123- Thyroid hormones can be activated by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- peroxisomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-124\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">124- Lysosomes under the LM:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Can be seen in their normal histology.<\/li><li data-o=\"b\" tabindex=\"0\">b- Need H&amp;E to be seen.<\/li><li data-o=\"c\" tabindex=\"0\">c- Need acid phosphatase to be seen.<\/li><li data-o=\"d\" tabindex=\"0\">d- Need best’s carmine to be seen.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-125\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">125- Polysomes are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A bead like structures formed of the link of a group of ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- A bead like structures formed of the link of a group of lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- A bead like structures formed of the link of a group of peroxisomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- A bead like structures formed of the link of a group of secretory vesicles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-126\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">126- One of the following is a membranous cytoplasmic organelle:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Centrioles<\/li><li data-o=\"c\" tabindex=\"0\">c- Cilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Ribosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-127\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">127- Heterolysosomes are formed of primary lysosomes plus vesicles containing:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Old organelles<\/li><li data-o=\"b\" tabindex=\"0\">b- Fluid droplets<\/li><li data-o=\"c\" tabindex=\"0\">c- Bacteria.<\/li><li data-o=\"d\" tabindex=\"0\">d- Undigested materials.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-128\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">128- Autolysosome is formed of primary lysosome ..................<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Another primary lysosome?<\/li><li data-o=\"b\" tabindex=\"0\">b- Destroyed organelle<\/li><li data-o=\"c\" tabindex=\"0\">c- pinocytic vesicle<\/li><li data-o=\"d\" tabindex=\"0\">d- Residual body<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t06\"><h3>Peroxisomes <small>— 9 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t06\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-129\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">129- Hydrolytic enzymes are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- peroxisomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- sER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-130\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">130- Oxidative enzymes are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- peroxisomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- sER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-131\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">131- Peroxisomes are Stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Metachromatic stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histochemical stain for catalase.<\/li><li data-o=\"c\" tabindex=\"0\">c- Histochemical stain as acid phosphatase.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histochemical stain as alkaline phosphatase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-132\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">132- Beta oxidation occurs in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondrial matrix<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondrial inner membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Peroxisomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-133\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">133- Formation and degradation of hydrogen peroxide into water is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Peroxisomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Proteasomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-134\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">134- Enzymes of peroxisomes arise from:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Free ribosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- rER<\/li><li data-o=\"d\" tabindex=\"0\">d- Both b&amp;c<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-135\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">135- All the statements concerning peroxisomes are true EXCEPT they:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contain hydrolytic enzymes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are spherical membrane bounded organelles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Contain enzymes involved in formation of H2O2.<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain enzymes involved in breakdown of excess H2O2.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-136\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">136- Enzymes of peroxisomes are synthesized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Free ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Attached ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- rER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-137\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">137- Peroxisomal enzymes are synthesized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- sER<\/li><li data-o=\"b\" tabindex=\"0\">b- rER<\/li><li data-o=\"c\" tabindex=\"0\">c- free polysomes<\/li><li data-o=\"d\" tabindex=\"0\">d- nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t07\"><h3>Ribosomes <small>— 20 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t07\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-138\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">138- Synthesis of proteins for extracellular use is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Free ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Attached ribosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-139\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">139- Synthesis of proteins for intracellular use is the function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Free ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Attached ribosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-140\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">140- The rough endoplasmic reticulum’s wall is rough because it’s studded with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Centrioles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-141\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">141- The ribosome is concerned with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Calcium pumping in muscle contraction<\/li><li data-o=\"b\" tabindex=\"0\">b- Energy production<\/li><li data-o=\"c\" tabindex=\"0\">c- Protein synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Cellular digestion<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-142\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">142- Ribophorins are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Inactive chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Receptors for ribosomal attachment<\/li><li data-o=\"c\" tabindex=\"0\">c- Polyribosomes linked by mRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Active chromatin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-143\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">143- The organelle considered with protein synthesis:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- centrioles.<\/li><li data-o=\"d\" tabindex=\"0\">d- lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-144\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">144- Ribosomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are attached to outer surface of Golgi saccules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Consist of DNA conjugated with protein.<\/li><li data-o=\"c\" tabindex=\"0\">c- appear with EM as small &amp; large subunits.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in all cells synthesizing carbohydrate.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-145\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">145- Abundance of free ribosomes in the cytoplasm is indicative of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- protein synthesis for export.<\/li><li data-o=\"b\" tabindex=\"0\">b- protein synthesis for intracellular use.<\/li><li data-o=\"c\" tabindex=\"0\">c- Excessive phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-146\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">146- Abundance of attached ribosomes in the cytoplasm is indicative of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- protein synthesis for export.<\/li><li data-o=\"b\" tabindex=\"0\">b- protein synthesis for intracellular use.<\/li><li data-o=\"c\" tabindex=\"0\">c- Excessive phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-147\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">147- Ribosomes are composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rRNA &amp; proteins.<\/li><li data-o=\"b\" tabindex=\"0\">b- DNA &amp; proteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- mRNA &amp; proteins.<\/li><li data-o=\"d\" tabindex=\"0\">d- tRNA &amp; proteins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-148\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">148- Which of the following organelles are responsible for basophilia of the cytoplasm?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi complex<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-149\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">149- Ribosomes are synthesized in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- proteasomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- The nucleolus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Peroxisomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-150\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">150- Polysomes are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Many ribosomes linked together by long mRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- The end product of ribosome.<\/li><li data-o=\"c\" tabindex=\"0\">c- An acidophilic structure.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-151\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">151- Ribosomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are intensely basophilic.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are free or attached to RER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are the site for amino acid assembling in protein synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-152\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">152- Ribosomes are intensely basophilic granules. This basophilia is due to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Presence of basophilic protein.<\/li><li data-o=\"b\" tabindex=\"0\">b- Presence of amino acids for assembly.<\/li><li data-o=\"c\" tabindex=\"0\">c- Presence of RNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its attachment to RER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-153\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">153- Which of the following is false about ribosomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are formed of a large subunit and a small subunit.<\/li><li data-o=\"b\" tabindex=\"0\">b- Under the EM, they appear as electron dense granules (20-30 nm in diameter).<\/li><li data-o=\"c\" tabindex=\"0\">c- They are considered to be membranous organelles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-154\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">154- The following organelles are membranous organelles EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ribosome.<\/li><li data-o=\"c\" tabindex=\"0\">c- RER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-155\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">155- Cells active in protein formation have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi complex.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-156\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">156- Concerning of ribosomes which is wrong?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- free in cytoplasm<\/li><li data-o=\"b\" tabindex=\"0\">b- attached to surface of rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- attached to sER.<\/li><li data-o=\"d\" tabindex=\"0\">d- botha&amp;c.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-157\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">157- The two ribosomal subunits join each other in the:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cytoplasm during cell division<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoplasm during protein synthesis<\/li><li data-o=\"c\" tabindex=\"0\">c- Nucleus during cell division.<\/li><li data-o=\"d\" tabindex=\"0\">d- Nucleus during protein synthesis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t08\"><h3>Microtubules &amp; Microfilaments <small>— 60 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t08\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-158\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">158- Centriole consists of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-159\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">159- Axoneme of cilia consists of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-160\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">160- Basal body of cilia consists of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-161\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">161- Which of the following are seen by LM as Hair like Striations:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cilia<\/li><li data-o=\"b\" tabindex=\"0\">b- microvilli<\/li><li data-o=\"c\" tabindex=\"0\">c- microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- microfilaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-162\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">162- Microtubules share in the formation of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitotic spindle<\/li><li data-o=\"b\" tabindex=\"0\">b- Microvilli<\/li><li data-o=\"c\" tabindex=\"0\">c- Cilia<\/li><li data-o=\"d\" tabindex=\"0\">d- Flagella<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-163\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">163- Vimentin intermediate filaments are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hair<\/li><li data-o=\"b\" tabindex=\"0\">b- Connective tissue &amp; muscle<\/li><li data-o=\"c\" tabindex=\"0\">c- Neurons<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial tissue<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-164\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">164- Microtubules are formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Alpha tubulin<\/li><li data-o=\"b\" tabindex=\"0\">b- Beta tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Gamma tubulin<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a&amp;b<\/li><li data-o=\"e\" tabindex=\"0\">e- Both a&amp;c<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-165\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">165- Microtubules, microfilaments, and intermediate filaments are components of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Nucleus<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoskeleton<\/li><li data-o=\"c\" tabindex=\"0\">c- cell membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-166\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">166- The axoneme of the cilia is composed of<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- 27 microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- 20 microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-167\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">167- The basal body of the cilia is composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- 20 microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- 9 microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- 18 microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-168\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">168- Intermediate filaments:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Form lamins.<\/li><li data-o=\"b\" tabindex=\"0\">b- Form core of microvilli<\/li><li data-o=\"c\" tabindex=\"0\">c- Form mitotic spindle during cell division<\/li><li data-o=\"d\" tabindex=\"0\">d- are formed of actin filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-169\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">169- Actin filaments share in the formation of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Flagella.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stereocilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrioles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-170\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">170- The shaft of cilium contains ... microtubules<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27<\/li><li data-o=\"b\" tabindex=\"0\">b- 20<\/li><li data-o=\"c\" tabindex=\"0\">c- 18<\/li><li data-o=\"d\" tabindex=\"0\">d- 9<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-171\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">171- The centrioles can be stained with<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver (Ag)<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS<\/li><li data-o=\"c\" tabindex=\"0\">c- iron hematoxylin<\/li><li data-o=\"d\" tabindex=\"0\">d- Indian ink<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-172\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">172- A male is diagnosed with prostatic cancer and needs chemotherapy, the organelle on which this drug act is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- rER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-173\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">173- As regards the histological structure of the centrioles:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubule B is formed of 13 protofilaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Surrounded by matrix of tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Stained by Janus green as 2 dark bodies<\/li><li data-o=\"d\" tabindex=\"0\">d- Formed of 9 bundles of microfilaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-174\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">174- The intermediate filament protein most characteristic of epithelial cells is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Desmin<\/li><li data-o=\"b\" tabindex=\"0\">b- Glial fibrillary acidic protein<\/li><li data-o=\"c\" tabindex=\"0\">c- Cytokeratin<\/li><li data-o=\"d\" tabindex=\"0\">d- Vimentin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-175\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">175- Iron hematoxylin stain is used to demonstrate:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria &amp;cell membrane<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria &amp; centrioles<\/li><li data-o=\"c\" tabindex=\"0\">c- proteasomes &amp; peroxisomes<\/li><li data-o=\"d\" tabindex=\"0\">d- proteasomes &amp; Lysosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-176\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">176- Microfilaments form the following structures:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- core of cilia<\/li><li data-o=\"b\" tabindex=\"0\">b- core of flagella<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitotic spindle in cell division<\/li><li data-o=\"d\" tabindex=\"0\">d- core of microvilli<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-177\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">177- A tumor is decided to be of epithelial origin when it contains mainly:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lamin<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Cytokeratin<\/li><li data-o=\"d\" tabindex=\"0\">d- desmin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-178\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">178- Concerning Cilia which statement is false:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present in the apical surface.<\/li><li data-o=\"b\" tabindex=\"0\">b- shaft is formed of 27 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- It’s motile structure.<\/li><li data-o=\"d\" tabindex=\"0\">d- formed of three parts.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-179\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">179- The wall of centrioles is composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 27 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 72 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 18 microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-180\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">180- Centrioles share in the formation of the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitotic spindles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Microvilli.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Flagella.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-181\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">181- All of the following share in the formation of cytoskeleton except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- microfilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- centrioles.<\/li><li data-o=\"d\" tabindex=\"0\">d- mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-182\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">182- Which of the following filaments can be found in epithelial cell cytoskeleton:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- desmin filaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- glial filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- vimentin filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- keratin filaments (tonofilament).<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-183\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">183- Cilia are present in all of the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- trachea.<\/li><li data-o=\"b\" tabindex=\"0\">b- bronchi.<\/li><li data-o=\"c\" tabindex=\"0\">c- fallopian tube.<\/li><li data-o=\"d\" tabindex=\"0\">d- sperm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-184\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">184- Flagella are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- trachea.<\/li><li data-o=\"b\" tabindex=\"0\">b- bronchi.<\/li><li data-o=\"c\" tabindex=\"0\">c- fallopian tube.<\/li><li data-o=\"d\" tabindex=\"0\">d- sperm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-185\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">185- Concerning basal body, it is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 Microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 Microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 Microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 Microtubules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-186\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">186- Concerning Shaft, it is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 Microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 Microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 Microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-187\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">187- Concerning rootlets, it is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 Microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 18 Microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 Microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 27 Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-188\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">188- Concerning centrioles, it is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9 triplets of microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 9 triplets of microtubules with 2 central singlets.<\/li><li data-o=\"c\" tabindex=\"0\">c- 27 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-189\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">189- Which of the following can be stained by iron hematoxylin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi.<\/li><li data-o=\"c\" tabindex=\"0\">c- centrioles.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-190\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">190- Microtubules are formed from:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- ubiquitin.<\/li><li data-o=\"b\" tabindex=\"0\">b- tubulin.<\/li><li data-o=\"c\" tabindex=\"0\">c- actin<\/li><li data-o=\"d\" tabindex=\"0\">d- globulin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-191\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">191- The centrioles are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Membranous organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Similar in structure to shaft of cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Demonstrated by H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Self-replicating organelles.<\/li><li data-o=\"e\" tabindex=\"0\">e- Disappeared during cell division.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-192\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">192- The microtubules are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Membranous organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- 10-15 nm in diameter.<\/li><li data-o=\"c\" tabindex=\"0\">c- Forming core of microvilli.<\/li><li data-o=\"d\" tabindex=\"0\">d- Having plus &amp; minus end<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-193\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">193- One of the following cilium parts has an identical structure to the centriole:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basal body.<\/li><li data-o=\"b\" tabindex=\"0\">b- Rootlets.<\/li><li data-o=\"c\" tabindex=\"0\">c- Shaft.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-194\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">194- A flagellum compared to a cilium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Multiple and shorter.<\/li><li data-o=\"b\" tabindex=\"0\">b- Single and shorter.<\/li><li data-o=\"c\" tabindex=\"0\">c- Multiple and longer.<\/li><li data-o=\"d\" tabindex=\"0\">d- Single and longer.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-195\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">195- Centrioles need special stains to be viewed under the LM like:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Green Janus B.<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron hematoxylin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-196\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">196- Cytoskeleton is a network of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Thin filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Intermediate filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-197\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">197- Microtubules are tubular structure:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its wall made of nine set of triplet of protofilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- 25 nm in outer diameter.<\/li><li data-o=\"c\" tabindex=\"0\">c- It can be elongate by “minus end”.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-198\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">198- The axoneme is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of nine pairs of microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of nine pairs of microtubules and two central singlets.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of nine triplets of.microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-199\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">199- Concerning the microtubules, one statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Subunit A Is formed of 13 protofilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Subunit A is formed of 10 protofilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Subunit B is formed of 13 protofilaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- All the previous statements are true.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-200\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">200- Concerning the microtubules, one statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Subunit β is formed of 13 protofilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Subunit α and subunit β tubulin form the protofilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-201\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">201- Basal body has a structure similar to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centriole.<\/li><li data-o=\"b\" tabindex=\"0\">b- Centrosome.<\/li><li data-o=\"c\" tabindex=\"0\">c- Axoneme.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-202\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">202- Microfilaments have the following functions EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubule organizing center.<\/li><li data-o=\"b\" tabindex=\"0\">b- Movement of cytoplasmic components.<\/li><li data-o=\"c\" tabindex=\"0\">c- Determine the shape of the cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Developing cleavage furrow.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-203\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">203- Keratin filaments are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-204\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">204- Desmin filaments are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Thick filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-205\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">205- Vimentin filaments are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Thick filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-206\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">206- Neurofilaments are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Thick filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-207\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">207- Glial filaments are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Thick filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-208\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">208- All the statements concerning intermediate filaments are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Their diameter about 10 nm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Present in the skin (keratin).<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in the smooth muscle (neurofilaments).<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in the glial cells (glial filaments).<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-209\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">209- Cytoskeleton is formed of complex system of interconnected:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes and filaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Microtubules and centrioles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Microtubules and filament.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-210\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">210- ....... Form the cytoskeleton of the cells.<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- microfilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- intermediate filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-211\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">211- Concerning microtubules, one is wrong:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- an element of cytoskeleton.<\/li><li data-o=\"b\" tabindex=\"0\">b- responsible for intracellular transport.<\/li><li data-o=\"c\" tabindex=\"0\">c- present in cilia &amp; flagella.<\/li><li data-o=\"d\" tabindex=\"0\">d- each has fixed length.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-212\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">212- All of the followings are membranous organelles except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Coated vesicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Peroxisomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-213\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">213- Chronic respiratory tract infection may be caused by abnormality in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cilia<\/li><li data-o=\"b\" tabindex=\"0\">b- microvilli<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-214\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">214- Cytokeratin, neurofilaments and lamins are types of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- Microfilaments<\/li><li data-o=\"c\" tabindex=\"0\">c- Protofilaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Intermediate filaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-215\" data-k=\"a\" data-bk=\"d\" data-fx=\"الجسم القاعدي للأهداب (basal body) له نفس تركيب الـcentriole، أي 9 ثلاثيات من الأنيبيبات الدقيقة، أما الريبوسوم فليس له هذا التركيب.\"><p class=\"qt\" dir=\"ltr\">215- The basal body of cilia is similar to:<span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centriole<\/li><li data-o=\"b\" tabindex=\"0\">b- Centrosome<\/li><li data-o=\"c\" tabindex=\"0\">c- Centromere<\/li><li data-o=\"d\" tabindex=\"0\">d- Ribosome<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-216\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">216- The axoneme of a cilium is composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules covered by cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- 27 microtubules not covered by cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 microtubules not covered by cell membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- 20 microtubules covered by cell membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-217\" data-k=\"d\" data-bk=\"a\" data-fx=\"الأنيبيبات الدقيقة والخيوط الدقيقة والخيوط المتوسطة هي مكوّنات الهيكل الخلوي (cytoskeleton).\"><p class=\"qt\" dir=\"ltr\">217- Microtubules, microfilaments &amp; intermediate filaments are components of:<span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell membrane<\/li><li data-o=\"b\" tabindex=\"0\">b- Nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Cytoskeleton<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t09\"><h3>Proteasomes <small>— 6 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t09\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-218\" data-k=\"b\" data-bk=\"c\" data-fx=\"البروتينات التالفة قصيرة العمر تتكسّر داخل الخلية بواسطة الـproteasome، أما الـperoxisomes فوظيفتها مختلفة.\"><p class=\"qt\" dir=\"ltr\">218- Abnormal short lived proteins are degraded inside the cell by...<span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- proteasome<\/li><li data-o=\"c\" tabindex=\"0\">c- peroxisomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- endosome<\/li><li data-o=\"e\" tabindex=\"0\">e- Phagosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-219\" data-k=\"c\" data-bk=\"a\" data-fx=\"خلل الـproteasomes يؤدي لتراكم البروتينات التالفة وهو مرتبط بمرض الزهايمر، والـperoxisomes لا علاقة لها بتكسير البروتينات.\"><p class=\"qt\" dir=\"ltr\">219- Defective.......are related to the development of Alzheimer disease:<span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- peroxisomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- proteosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- sER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-220\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">220- Which of the following proteins is usually associated with proteasomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Clathrin<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Ubiquitin<\/li><li data-o=\"d\" tabindex=\"0\">d- Actin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-221\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">221- The Protein rings in the core particle are arranged:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- In a single layer<\/li><li data-o=\"b\" tabindex=\"0\">b- In four layers stacked on each other<\/li><li data-o=\"c\" tabindex=\"0\">c- Randomly:<\/li><li data-o=\"d\" tabindex=\"0\">d- Around the Nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-222\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">222- Which Statement about ubiquitin is correct?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It Tags Protein for destruction<\/li><li data-o=\"b\" tabindex=\"0\">b- It produces ATP<\/li><li data-o=\"c\" tabindex=\"0\">c- It forms the core particle<\/li><li data-o=\"d\" tabindex=\"0\">d- It destroys protein directly<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-223\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">223- Which of the following is NOT a function of proteasomes:-<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Removing unnecessary proteins<\/li><li data-o=\"b\" tabindex=\"0\">b- Removing incorrectly folded proteins<\/li><li data-o=\"c\" tabindex=\"0\">c- Destroying Viral Proteins<\/li><li data-o=\"d\" tabindex=\"0\">d- Synthesizing new proteins<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t10\"><h3>Inclusions <small>— 23 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t10\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-224\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">224- Fat cells are stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Best’s carmine<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a&amp;b<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-225\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">225- Glycogen granules are stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Best’s carmine<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a&amp;b<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-226\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">226- Mitochondria can be stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Best’s carmine<\/li><li data-o=\"b\" tabindex=\"0\">b- Janus green<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III<\/li><li data-o=\"d\" tabindex=\"0\">d- Leishman stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-227\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">227- Best’s Carmine is used to demonstrate:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi complex.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat.<\/li><li data-o=\"d\" tabindex=\"0\">d- glycogen<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-228\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">228- Which of the following is true regarding the cell inclusions?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat appears vacuolated when stained with sudan III<\/li><li data-o=\"b\" tabindex=\"0\">b- Fats present in liver cells as small droplets<\/li><li data-o=\"c\" tabindex=\"0\">c- Lipofuscin are exogenous pigments that accumulate in nerve cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Glycogen appears as magenta red granules when stained by H&amp;E<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-229\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">229- Glycogen granules are stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver stain<\/li><li data-o=\"b\" tabindex=\"0\">b- Sudan III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Best’s carmine<\/li><li data-o=\"d\" tabindex=\"0\">d- Janus green<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-230\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">230- By Best&#x27;s carmine stains, Glycogen granules appears:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- purple.<\/li><li data-o=\"b\" tabindex=\"0\">b- red.<\/li><li data-o=\"c\" tabindex=\"0\">c- Orange.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-231\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">231- By Sudan III, Fat appears:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- purple.<\/li><li data-o=\"b\" tabindex=\"0\">b- red.<\/li><li data-o=\"c\" tabindex=\"0\">c- orange.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-232\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">232- Glycogen can be stained by the following:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E.<\/li><li data-o=\"b\" tabindex=\"0\">b- Best’s carmine.<\/li><li data-o=\"c\" tabindex=\"0\">c- PAS.<\/li><li data-o=\"d\" tabindex=\"0\">d- b&amp;c.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-233\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">233- Which of the following increases with age:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- lipofuscin.<\/li><li data-o=\"b\" tabindex=\"0\">b- carotene.<\/li><li data-o=\"c\" tabindex=\"0\">c- hemoglobin.<\/li><li data-o=\"d\" tabindex=\"0\">d- hemosiderin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-234\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">234- Which of the following pigment is found in long lived cells?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Melanin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lipofuscin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Myoglobin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Carotene.<\/li><li data-o=\"e\" tabindex=\"0\">e- Hemosiderin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-235\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">235- Carbohydrates are stained red with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Green Janus B.<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron hematoxylin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Best’s carmine.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-236\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">236- Lipofuscin pigments:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are the digested material in the secondary lysosome in long lived cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are the undigested material in the secondary lysosome in long lived cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are the undigested material in multivesicular bodies in long lived cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-237\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">237- Glycogen granules are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-238\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">238- Lipids are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-239\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">239- Hemoglobin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Crystals<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-240\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">240- Carotene is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Crystals.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-241\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">241- Carbon particles are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Crystals.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-242\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">242- Melanin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-243\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">243- Lipofuscin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored food.<\/li><li data-o=\"b\" tabindex=\"0\">b- Exogenous pigments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endogenous pigments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-244\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">244- Lipids:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stored mainly in the muscle cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Can be stained with PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mainly stored in the liver cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-245\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">245- PAS is used to demonstrate:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycogen granules &amp; cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cell membrane &amp; Golgi apparatus<\/li><li data-o=\"c\" tabindex=\"0\">c- Glycogen granules &amp; Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrioles &amp; mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-246\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">246- The following inclusion can be stained with Best’s carmine:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hemoglobin (Hb)<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycogen<\/li><li data-o=\"c\" tabindex=\"0\">c- Fats<\/li><li data-o=\"d\" tabindex=\"0\">d- carotene pigments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_t11\"><h3>Nucleus &amp; Chromatin &amp; Nucleolus <small>— 29 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_t11\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1z-247\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">247- Pars amorpha of the nucleus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents newly synthesized rRNA<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents mature rRNA<\/li><li data-o=\"c\" tabindex=\"0\">c- Represents DNA encoding for rRNA<\/li><li data-o=\"d\" tabindex=\"0\">d- Represents the light areas of nuclear sap<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-248\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">248- Pars fibrosa of the nucleus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents newly synthesized rRNA<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents mature rRNA<\/li><li data-o=\"c\" tabindex=\"0\">c- Represents DNA encoding for rRNA<\/li><li data-o=\"d\" tabindex=\"0\">d- Represents the light areas of nuclear sap<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-249\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">249- Concerning heterochromatin, all of the followings are true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The inactive form of chromatin<\/li><li data-o=\"b\" tabindex=\"0\">b- Present in the form of coiled filaments<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in the form of extended filaments<\/li><li data-o=\"d\" tabindex=\"0\">d- By EM it appears as electron dense granules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-250\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">250- The outer nuclear membrane is usually associated with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Peripheral chromatin<\/li><li data-o=\"b\" tabindex=\"0\">b- Chromatin islands<\/li><li data-o=\"c\" tabindex=\"0\">c- Polyribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-251\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">251- Peripheral chromatin<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Is attached to inner nuclear membrane<\/li><li data-o=\"b\" tabindex=\"0\">b- Is scattered in the nuclear sap<\/li><li data-o=\"c\" tabindex=\"0\">c- Is a part of euchromatin<\/li><li data-o=\"d\" tabindex=\"0\">d- Surrounds the nucleolus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-252\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">252- In nerve cells, the Golgi body is located:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Perinuclear<\/li><li data-o=\"b\" tabindex=\"0\">b- Eccentric<\/li><li data-o=\"c\" tabindex=\"0\">c- Apical<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-253\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">253- Chromatin islands:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A part of euchromatin<\/li><li data-o=\"b\" tabindex=\"0\">b- Surrounds the nucleolus<\/li><li data-o=\"c\" tabindex=\"0\">c- Attached to Inner nuclear membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Scattered in the nuclear sap<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-254\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">254- Pars fibrosa is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Attached to outer nuclear membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mature rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Attached to inner nuclear membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Is newly formed rRNA.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-255\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">255- Euchromatin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Inactive chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Deeply acidophilic<\/li><li data-o=\"c\" tabindex=\"0\">c- Electron lucent by EM<\/li><li data-o=\"d\" tabindex=\"0\">d- Predominant in nuclei of small lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-256\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">256- Aggregated clumps of chromatin scattered in nuclear sap is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Chromatin islands<\/li><li data-o=\"b\" tabindex=\"0\">b- Nucleolus<\/li><li data-o=\"c\" tabindex=\"0\">c- Euchromatin<\/li><li data-o=\"d\" tabindex=\"0\">d- peripheral chromatin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-257\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">257- Large clear nucleolus is seen in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Protein forming cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Lipid forming cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Histamine secreting cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Phagocytic cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-258\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">258- Choose the correct statement concerning the nucleolus:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pars amorpha contains mature rRNA<\/li><li data-o=\"b\" tabindex=\"0\">b- Pars amorpha contains immature rRNA<\/li><li data-o=\"c\" tabindex=\"0\">c- Pars granulosa contains mature rRNA<\/li><li data-o=\"d\" tabindex=\"0\">d- Pars granulosa contains immature rRNA<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-259\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">259- Heterochromatin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- highly coiled.<\/li><li data-o=\"b\" tabindex=\"0\">b- electron dense.<\/li><li data-o=\"c\" tabindex=\"0\">c- directing protein synthesis.<\/li><li data-o=\"d\" tabindex=\"0\">d- a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-260\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">260- Pars fibrosa contains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- DNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Newly synthesized rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mature rRNA.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-261\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">261- Components of the nucleolus are all of the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- pars granulosa.<\/li><li data-o=\"b\" tabindex=\"0\">b- pars amorpha.<\/li><li data-o=\"c\" tabindex=\"0\">c- pars fibrosa.<\/li><li data-o=\"d\" tabindex=\"0\">d- peroxisomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-262\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">262- All of the following about nuclear envelope are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- acidophilic.<\/li><li data-o=\"b\" tabindex=\"0\">b- interrupted at intervals by nuclear pores.<\/li><li data-o=\"c\" tabindex=\"0\">c- double walled membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- separated by a perinuclear space.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-263\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">263- The outer nuclear envelope is continuous with the following:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- sER.<\/li><li data-o=\"d\" tabindex=\"0\">d- lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-264\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">264- Euchromatin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Highly coiled chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of RNA and protein.<\/li><li data-o=\"c\" tabindex=\"0\">c- Directing protein synthesis.<\/li><li data-o=\"d\" tabindex=\"0\">d- Associated with nucleolus.<\/li><li data-o=\"e\" tabindex=\"0\">e- Attached to inner nuclear membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-265\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">265- Following statements concerning nuclear envelope are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of two membranes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Perforated at various interval by nuclear pores.<\/li><li data-o=\"c\" tabindex=\"0\">c- Not resolved by EM.<\/li><li data-o=\"d\" tabindex=\"0\">d- Has perinuclear cisterna (space).<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-266\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">266- Nuclear pores:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The sites of nuclear envelope perforation.<\/li><li data-o=\"b\" tabindex=\"0\">b- Sites at which the inner and the outer membranes are continuous.<\/li><li data-o=\"c\" tabindex=\"0\">c- Regulate the exchange of substances between nucleus and cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-267\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">267- Nuclear pore complex refers to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The nuclear pores.<\/li><li data-o=\"b\" tabindex=\"0\">b- Non membranous cylindrical structure fits the pores.<\/li><li data-o=\"c\" tabindex=\"0\">c- Rim of the nuclear pores.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-268\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">268- Euchromatin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Not visible with LM.<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents the inactive form of chromatin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Is a nucleolar associated chromatin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-269\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">269- Nucleolus associated heterochromatin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Is a membrane surrounds the nucleolus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is a heterochromatin attached to the nucleolus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Nucleolar organizer regions.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-270\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">270- Nucleolus formed of three regions:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pars granulosa, pars fibrosa and nucleolar organizer regions.<\/li><li data-o=\"b\" tabindex=\"0\">b- Peripheral, nucleolar associated chromatin and chromatin islands.<\/li><li data-o=\"c\" tabindex=\"0\">c- rRNA, ribosomal proteins and DNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Heterochromatin, euchromatin and nucleolar matrix.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-271\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">271- Regarding peripheral chromatin, it is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A part of euchromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of the nucleoproteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Scattered in the nuclear sap<\/li><li data-o=\"d\" tabindex=\"0\">d- Surrounding the nucleolus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-272\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">272- Nuclear Lamins are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mature rRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Attached to outer nuclear membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Newly formed rRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Attached to inner nuclear membrane<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-273\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">273- In the nucleolus, the newly formed rRNA is found in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pars amorpha.<\/li><li data-o=\"b\" tabindex=\"0\">b- Nucleolar organiser.<\/li><li data-o=\"c\" tabindex=\"0\">c- Pars fibrosa.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pars granulosa<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-274\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">274- The statement best matches the euchromatin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is coiled chromatin<\/li><li data-o=\"b\" tabindex=\"0\">b- It contains active genes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Dark basophilic nucleus by L.M.<\/li><li data-o=\"d\" tabindex=\"0\">d- It forms chromatin Islands.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1z-275\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">275- A protein forming cell has ONE of these characters:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Acidophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Great number of lysosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Many sER<\/li><li data-o=\"d\" tabindex=\"0\">d- More Euchromatin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_d12\"><h3>Department MCQs <small>— أسئلة القسم · 63 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_d12\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1d-001\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">1- The cell membrane can be demonstrated by ......... stain:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E.<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Orcein.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-002\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">2- Integral proteins are represented by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Non continuous layer.<\/li><li data-o=\"b\" tabindex=\"0\">b- Loosely attached to both surfaces of cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Small molecules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Trans-membrane protein.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-003\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">3- The cytoplasmic side of the coated vesicle is surrounded by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Clathrin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tubulin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Actin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Spectrin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-004\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">4- A type of dwarfism associated with normal growth hormone level, might be due to defect in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Passive diffusion of growth hormone.<\/li><li data-o=\"b\" tabindex=\"0\">b- Active transport of growth hormone.<\/li><li data-o=\"c\" tabindex=\"0\">c- Growth hormone receptors.<\/li><li data-o=\"d\" tabindex=\"0\">d- Facilitated diffusion of growth hormone.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-005\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">5- Two organelles share in the formation of lysosomes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER &amp; sER.<\/li><li data-o=\"b\" tabindex=\"0\">b- SER &amp; Golgi apparatus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus &amp; cell membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- rER &amp; Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-006\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">6- In H&amp;E-stained sections of plasma cell, Golgi apparatus appears:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Perinuclear.<\/li><li data-o=\"b\" tabindex=\"0\">b- Apical.<\/li><li data-o=\"c\" tabindex=\"0\">c- Unstained.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-007\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">7- The cytoplasmic organelle which contains DNA &amp; RNA is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- lysosome.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- One item is a feature of defective mitochondria:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondrial RNA mutation.<\/li><li data-o=\"b\" tabindex=\"0\">b- Muscle weakness.<\/li><li data-o=\"c\" tabindex=\"0\">c- Failure of breakdown of bilirubin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lack of sulfatases.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-009\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">9- Organelle responsible for renewal &amp; maintenance of cell membrane is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria<\/li><li data-o=\"d\" tabindex=\"0\">d- sER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- A protein forming cell has ONE of these characters:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Acidophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Great number of lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Abundant rER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Condensed nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-011\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">11- One of the following is a non membranous organelles:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- rER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- Localized cytoplasmic basophilia Indicates the presence of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- DNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- rER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-013\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">13- Pinocytosis is the process by which the cell membrane can engulf:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fluid droplets.<\/li><li data-o=\"b\" tabindex=\"0\">b- Solid particles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Bacteria.<\/li><li data-o=\"d\" tabindex=\"0\">d- foreign bodies.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-014\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">14- The cell organelle that can divide Is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.:<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-015\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">15- Autolysosomes are formed when a 1ry lysosome fuses with:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- An old organelle.<\/li><li data-o=\"b\" tabindex=\"0\">b- A phagosome.<\/li><li data-o=\"c\" tabindex=\"0\">c- A pinocytic vesicle.<\/li><li data-o=\"d\" tabindex=\"0\">d- A residual body.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-016\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">16- Elementary particles are located at the:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Outer membrane of rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Inner membrane of rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Outer mitochondrial membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Inner mitochondrial membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-017\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">17- Enzymes associated with drug detoxification are associated with:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.:<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-018\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">18- As regards Golgi apparatus:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It can be stained with silver.<\/li><li data-o=\"b\" tabindex=\"0\">b- It is always apical in all cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- It is formed of parallel cisternae.<\/li><li data-o=\"d\" tabindex=\"0\">d- detoxifies drugs and alcohol.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-019\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">19- Organelle is prominent in cells that synthesize steroid hormones:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- rER<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosome<\/li><li data-o=\"d\" tabindex=\"0\">d- Peroxisome<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-020\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">20- Cytoplasmic basophilia observed in LM is due to:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus<\/li><li data-o=\"b\" tabindex=\"0\">b- Euchromatin<\/li><li data-o=\"c\" tabindex=\"0\">c- Ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Heterochromatin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-021\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">21- Which statement is correct about sER?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Involved in protein formation.<\/li><li data-o=\"b\" tabindex=\"0\">b- More in steroid secreting cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- It has a role in digestion.<\/li><li data-o=\"d\" tabindex=\"0\">d- It has a role in sodium pump.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-022\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">22- A brown fibrillar network in the cytoplasm represents:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Primary lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secondary lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-023\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">23- Concerning rER:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its sites cause localized or diffuse acidophilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Shares in drug detoxification.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its limiting membranes have lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Responsible for protein segregation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-024\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">24- As regards the glycocalyx:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present on both surfaces of cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Embedded in lipid bilayer.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of proteins &amp; lipids.<\/li><li data-o=\"d\" tabindex=\"0\">d- Plays a role in cell adhesion &amp; recognition.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-025\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">25- Concerning sER:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It has ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- When abundant appears basophilic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Well developed in protein forming cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Plays important role in muscle contraction.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-026\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">26- Among features of medical conditions related to defective lysosomes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lack of catalase.<\/li><li data-o=\"b\" tabindex=\"0\">b- Accumulated hydrogen peroxide compounds.<\/li><li data-o=\"c\" tabindex=\"0\">c- Interference with nerve cell function.<\/li><li data-o=\"d\" tabindex=\"0\">d- Defective oxidoreductases.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-027\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">27- Peroxisomes are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Vesicles bud off Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its enzymes are synthesized by sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its enzymes are synthesized by attached polysomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its enzymes become internalized.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-028\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">28- Patients having deficient peroxisomal enzymes will suffer from:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Corneal opacity.<\/li><li data-o=\"b\" tabindex=\"0\">b- Heart lesion.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lung lesion.<\/li><li data-o=\"d\" tabindex=\"0\">d- Liver lesion.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-029\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">29- The diameter of microtubules is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 15 nm.<\/li><li data-o=\"b\" tabindex=\"0\">b- 6 nm.<\/li><li data-o=\"c\" tabindex=\"0\">c- 8-10 nm.<\/li><li data-o=\"d\" tabindex=\"0\">d- 24 nm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-030\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">30- Microtubules are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Having fixed length.<\/li><li data-o=\"b\" tabindex=\"0\">b- Being formed of alpha and beta tubulin<\/li><li data-o=\"c\" tabindex=\"0\">c- Being arranged into 10 protofilaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Diameter varies according to tubulin polymerization.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-031\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">31- One of the following structures is basophilic in staining:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- sER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-032\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">32- The organelle responsible for synthesis of secreted proteins is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Attached ribosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Smooth endoplasmic reticulum.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-033\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">33- The axoneme of the cilia has:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 2 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 18 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 20 microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-034\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">34- The basal body of the cilia has:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 20 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 18 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 9 microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-035\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">35- The rootlets of the cilia have:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 20 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 18 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 9 microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-036\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">36- The wall of the centriole is formed of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- 20 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- 18 microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- 9 microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-037\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">37- Vimentin intermediate filaments are present in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hair.<\/li><li data-o=\"b\" tabindex=\"0\">b- C.T. &amp; muscle<\/li><li data-o=\"c\" tabindex=\"0\">c- Neurons.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-038\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">38- Keratin filaments are present In:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Epidermis and hair.<\/li><li data-o=\"b\" tabindex=\"0\">b- C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neurons.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-039\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">39- Neurofilaments are present in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Epidermis &amp; hair.<\/li><li data-o=\"b\" tabindex=\"0\">b- C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neurons.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-040\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">40- Desmin intermediate filaments are present:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- In hair.<\/li><li data-o=\"b\" tabindex=\"0\">b- In muscle to Join the myofibrils.<\/li><li data-o=\"c\" tabindex=\"0\">c- In neurons.<\/li><li data-o=\"d\" tabindex=\"0\">d- In glial tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-041\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">41- One is an endogenous pigment:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Carbon.<\/li><li data-o=\"b\" tabindex=\"0\">b- Melanin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Carotene.<\/li><li data-o=\"d\" tabindex=\"0\">d- Tattoo marks.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-042\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">42- One is regarded as endogenous pigment:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hemoglobin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Carbon.<\/li><li data-o=\"c\" tabindex=\"0\">c- Carotene.<\/li><li data-o=\"d\" tabindex=\"0\">d- Tattoo marks.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-043\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">43- Actin filaments share in formation of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Flagella.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitotic spindle.<\/li><li data-o=\"d\" tabindex=\"0\">d- Microvilli.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-044\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">44- Which of the following share in cell division:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Centrioles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Keratin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Vimentin filaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-045\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">45- Fat cells are stained with:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Iron haematoxylin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Silver stain.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Janus green.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-046\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">46- Glycogen granules are stained with:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Osmic acid.<\/li><li data-o=\"b\" tabindex=\"0\">b- Silver stain.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Best’s carmine.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-047\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">47- The outer layer of the nuclear envelope:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Smooth.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is granular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Shows cristae.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibrillar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-048\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">48- Concerning the nuclear pores:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Triangular openings at intervals.:<\/li><li data-o=\"b\" tabindex=\"0\">b- Inner &amp; outer nuclear membranes do not fuse at the pore.<\/li><li data-o=\"c\" tabindex=\"0\">c- Concerned with import of RNA to nucleus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its proteins form octagonal ring.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-049\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">49- Chromatin islands are:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Attached to the inner surface of nuclear envelope.<\/li><li data-o=\"b\" tabindex=\"0\">b- Arranged in clumps scattered in the nuclear sap.<\/li><li data-o=\"c\" tabindex=\"0\">c- Condensed around nucleolus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fine granules scattered in cytoplasm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-050\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">50- Concerning euchromatin:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents coiled parts of chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Appears as condensed masses in nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Contains Inactive genes that direct protein synthesis.<\/li><li data-o=\"d\" tabindex=\"0\">d- Makes the nucleus vesicular<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-051\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">51- Pars amorpha of the nucleolus:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents newly formed strands of rRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents granules of mature rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Represents parts of chromosomes encoding for rRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Represents the light areas of nuclear sap.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-052\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">52- Pars fibrosa of the nucleolus:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents newly synthesized rRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents mature rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Represents DNA encoding for rRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Represents light areas of nuclear sap.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-053\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">53- Pars granulosa of the nucleolus:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Represents newly formed rRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Represents mature rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Represents chromosomes encoding for rRNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Represents light areas of nucleolar sap.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-054\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">54- Microtubules are formed of a protein called:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Actin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Myosin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Tubulin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Clathrin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-055\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">55- As regards ribosomes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Their subunits are formed in the nucleolus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are formed of DNA associated with proteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cause cytoplasmic acidophilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are formed of two subunits of equal size.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-056\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">56- A 45 female patient suffering from breast cancer the doctor gave her a chemotherapy to block the activity of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microfilaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments<\/li><li data-o=\"c\" tabindex=\"0\">c- Microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- Proteasome<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-057\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">57- A 2 years old infant presenting with repeated bone fractures, genetic diagnosis pointed to:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- sER malfunction<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi dysfunction<\/li><li data-o=\"c\" tabindex=\"0\">c- Lysosomal error<\/li><li data-o=\"d\" tabindex=\"0\">d- rER protein control malfunction<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-058\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">58- A newborn presenting with yellow coloration of skin and eyes by examination is expected’ to have:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Defective ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Underdeveloped sER in liver<\/li><li data-o=\"c\" tabindex=\"0\">c- Underdeveloped sER in skin<\/li><li data-o=\"d\" tabindex=\"0\">d- Malfunction of rER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-059\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">59- A 40 years male patient presented with an abdominal tumor the origin of which was ......... due to the presence of .....<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- connective tissue &amp; desmin.<\/li><li data-o=\"b\" tabindex=\"0\">b- glial &amp; neurofilaments<\/li><li data-o=\"c\" tabindex=\"0\">c- epithelial &amp; lamin.<\/li><li data-o=\"d\" tabindex=\"0\">d- muscular &amp; desmin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-060\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">60- A child suffering from local skeletal muscle weakness in the lower limb, Investigations showed:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi body abnormality<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondrial damage<\/li><li data-o=\"c\" tabindex=\"0\">c- Membrane receptors defect<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomal enzyme deficiency<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-061\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">61- A patient presenting with urine troubles and fatty liver. kidney and liver examination showed:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondrial abnormalities<\/li><li data-o=\"b\" tabindex=\"0\">b- Lysosomal enzyme deficiency<\/li><li data-o=\"c\" tabindex=\"0\">c- Peroxisomal enzyme deficiency<\/li><li data-o=\"d\" tabindex=\"0\">d- Defective fat metabolism<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-062\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">62- A child complaining of nervous manifestations was proved to be free of tumors or infections, at a cellular level showed:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Defective lysosomal sulfatases<\/li><li data-o=\"b\" tabindex=\"0\">b- Decreased lysosomal nucleases.<\/li><li data-o=\"c\" tabindex=\"0\">c- Defective peroxisomal oxidases.<\/li><li data-o=\"d\" tabindex=\"0\">d- Defective peroxisomal catalase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1d-063\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">63- A male patient complains of repeated upper respiratory tract infections and not responding well to usual medications, the case to be due to:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- repeated viral infections<\/li><li data-o=\"b\" tabindex=\"0\">b- repeated bacterial infections<\/li><li data-o=\"c\" tabindex=\"0\">c- immotile cilia<\/li><li data-o=\"d\" tabindex=\"0\">d- defective stereocilia<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h1_e13\"><h3>Exam MCQs <small>— أسئلة الامتحانات · 47 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h1_e13\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c1e-001\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">1- Storage, packaging and chemical modification of proteins occur in:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Free ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Attached ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Cytoskeleton.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-002\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">2- Smooth endoplasmic reticulum is involved in:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Detoxification of drugs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Protein synthesis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Energy production.<\/li><li data-o=\"d\" tabindex=\"0\">d- Cell recognition.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- The two ribosomal subunits join each other in the:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cytoplasm during cell division.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoplasm during protein synthesis<\/li><li data-o=\"c\" tabindex=\"0\">c- Nucleus during cell division.<\/li><li data-o=\"d\" tabindex=\"0\">d- Nucleus during protein synthesis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-004\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">4- Cell membrane can be stained by:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- AG.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trypan blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron haematoxylin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- One of the following is a membranous cytoplasmic organelle:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Centrioles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-006\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">6- Cytokeratin, neurofilaments and lamins are types of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Microfilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Protofilaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Intermediate filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-007\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">7- Cytoplasmic basophilia reflects the abundance of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- SER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Golgi apparatus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-008\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">8- PAS is used to demonstrate:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycogen granules &amp; cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cell membrane &amp; Golgi apparatus<\/li><li data-o=\"c\" tabindex=\"0\">c- Glycogen granules &amp; Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrioles &amp; mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-009\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">9- Regarding Golgi apparatus, which statement is correct:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of parallel flattened cisternae.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have Cis and Trans faces.<\/li><li data-o=\"c\" tabindex=\"0\">c- Involved in glycogen breakdown.<\/li><li data-o=\"d\" tabindex=\"0\">d- Involved in cell respiration.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- Peroxisomal enzymes are synthesized by:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Free polysomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-011\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">11- Heterolysosomes are formed of primary lysosomes plus vesicles containing:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Old organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Bacteria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fluid droplets.<\/li><li data-o=\"d\" tabindex=\"0\">d- Undigested materials.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- The axoneme of a cilium is composed of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27 microtubules covered by cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- 27 microtubules not covered by cell membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- 20 microtubules not covered by cell membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- 20 microtubules covered by cell membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-013\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">13- Regarding peripheral chromatin, it is:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A part of euchromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of the nucleoproteins.<\/li><li data-o=\"c\" tabindex=\"0\">c- Surrounding the nucleolus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Scattered in the nuclear sap.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-014\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">14- Nuclear Lamins are:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mature rRNA.<\/li><li data-o=\"b\" tabindex=\"0\">b- Newly formed rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Attached to outer nuclear membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Attached to inner nuclear membrane<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-015\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">15- In the nucleolus, the newly formed rRNA is found in:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pars amorpha.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pars fibrosa.<\/li><li data-o=\"c\" tabindex=\"0\">c- Nucleolar organiser.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pars granulosa.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-016\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">16- The statement best matches euchromatin is<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is coiled chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Dark basophilic nucleus by L.M.<\/li><li data-o=\"c\" tabindex=\"0\">c- It contains active genes.<\/li><li data-o=\"d\" tabindex=\"0\">d- It forms chromatin islands.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-017\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">17- Cell membrane can be.stained by the following histochemical stain::<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Sudan III.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trypan blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Brilliant cresyl blue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Periodic acid Schiff reaction (PAS).<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Ribophorins are:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Inactive chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Active chromatin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Receptors for ribosomal attachment on rER<\/li><li data-o=\"d\" tabindex=\"0\">d- Polyribosomes linked bY mRNA<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-019\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">19- Fat cells can be stained with:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Orcein.<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Iron hematoxylin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- Protein on cytoplasmic side is involved in receptor mediated endocytosis:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tubulin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Clathrin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lamin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Spectrin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-021\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">21- The true statement about mitochondria is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Self-replicating organelle.<\/li><li data-o=\"b\" tabindex=\"0\">b- Outer membrane forms cristae.<\/li><li data-o=\"c\" tabindex=\"0\">c- Non membranous organelle.<\/li><li data-o=\"d\" tabindex=\"0\">d- Inner membrane is smooth.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-022\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">22- Enzymes of peroxisomes arise from:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Free ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- rER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both b&amp;c<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-023\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">23- Intermediate filaments:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Form lamins.<\/li><li data-o=\"b\" tabindex=\"0\">b- Form core of Microvilli.<\/li><li data-o=\"c\" tabindex=\"0\">c- Form mitotic spindle during cell division.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are formed of actin filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-024\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">24- Pars fibrosa is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Attached to outer nuclear membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mature rRNA.<\/li><li data-o=\"c\" tabindex=\"0\">c- Attached to inner nuclear membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Is newly formed rRNA.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-025\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">25- Actin filaments share in the formation of:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Flagella.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stereocilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrioles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-026\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">26- Lysosomes are:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed by rER &amp; Golgi apparatus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Non-membranous organelles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Demonstrated by H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are few in phagocytic cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-027\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">27- Detoxification of drug needs mainly numerous:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- sER.<\/li><li data-o=\"b\" tabindex=\"0\">b- ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- rER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both b&amp;c.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-028\" data-k=\"b\" data-bk=\"c\" data-fx=\"الـeuchromatin هو الكروماتين الفاتح النشط ويظهر electron lucent بالمجهر الإلكتروني، وليس شديد الصبغة الحمضية.\"><p class=\"qt\" dir=\"ltr\">28- Euchromatin is:<span class=\"gtag\" dir=\"ltr\">196<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Inactive chromatin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Electron lucent by EM.<\/li><li data-o=\"c\" tabindex=\"0\">c- Deeply acidophilic.<\/li><li data-o=\"d\" tabindex=\"0\">d- Predominant in nuclei of small lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-029\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">29- Best’s Carmine is used to demonstrate:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Golgi complex<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat<\/li><li data-o=\"d\" tabindex=\"0\">d- Glycogen<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-030\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">30- Multivesicular bodies:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are formed by fusion of primary lysosome with old organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are a type of primary lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Appear homogenous by EM<\/li><li data-o=\"d\" tabindex=\"0\">d- Are formed by fusion of primary lysosome with pinocytic vesicle.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-031\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">31- The shaft of cilium contains ..... microtubules:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 27<\/li><li data-o=\"b\" tabindex=\"0\">b- 20<\/li><li data-o=\"c\" tabindex=\"0\">c- 18<\/li><li data-o=\"d\" tabindex=\"0\">d- 9<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-032\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">32- The centrioles can be stained with:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver (Ag).<\/li><li data-o=\"b\" tabindex=\"0\">b- PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron hematoxylin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Indian ink.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-033\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">33- Which is a non-membranous organelle:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell membrane<\/li><li data-o=\"b\" tabindex=\"0\">b- Mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Ribosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-034\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">34- Regarding the peroxisomes (microbodies):<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bud from smooth endoplasmic reticulum (SER)<\/li><li data-o=\"b\" tabindex=\"0\">b- Divide by simple division<\/li><li data-o=\"c\" tabindex=\"0\">c- Numerous in cardiac muscle<\/li><li data-o=\"d\" tabindex=\"0\">d- produce energy stored as ATP<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-035\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">35- Heterolysosome is formed of primary lysosome and .................<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pinocytic vesicle<\/li><li data-o=\"b\" tabindex=\"0\">b- Destroyed organelle<\/li><li data-o=\"c\" tabindex=\"0\">c- Residual body<\/li><li data-o=\"d\" tabindex=\"0\">d- Phagosome<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-036\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">36- The nucleus of active protein forming cell appears:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Condensed<\/li><li data-o=\"b\" tabindex=\"0\">b- Vesicular<\/li><li data-o=\"c\" tabindex=\"0\">c- heterochromatic<\/li><li data-o=\"d\" tabindex=\"0\">d- Electron dense by E.M<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-037\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">37- The cytoplasmic organelle concerned with detoxification of drugs is:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- sER<\/li><li data-o=\"b\" tabindex=\"0\">b- rER<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosomes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-038\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">38- The intermediate filament found in cells of connective tissue is:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Desmin<\/li><li data-o=\"b\" tabindex=\"0\">b- Vimentin<\/li><li data-o=\"c\" tabindex=\"0\">c- Cytokeratin<\/li><li data-o=\"d\" tabindex=\"0\">d- Glial fibrillar acidic protein<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-039\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">39- The shaft of cilia is composed of .........microtubules:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 9<\/li><li data-o=\"b\" tabindex=\"0\">b- 27<\/li><li data-o=\"c\" tabindex=\"0\">c- 18<\/li><li data-o=\"d\" tabindex=\"0\">d- 20<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-040\" data-k=\"b\" data-bk=\"c\" data-fx=\"الخيوط الدقيقة (microfilaments) هي خيوط الأكتين وتكوّن قلب الزغيبات (microvilli)، أما قطر 8-10 نانومتر فهو للخيوط المتوسطة.\"><p class=\"qt\" dir=\"ltr\">40- Regarding the microfilaments:<span class=\"gtag\" dir=\"ltr\">198<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of tubulin<\/li><li data-o=\"b\" tabindex=\"0\">b- Form microvilli<\/li><li data-o=\"c\" tabindex=\"0\">c- Diameter 8-10nm<\/li><li data-o=\"d\" tabindex=\"0\">d- Include lamins.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-041\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">41- Which statement applies to the ribosomes:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Arise from Golgi apparatus<\/li><li data-o=\"b\" tabindex=\"0\">b- Cause cytoplasmic acidophilia<\/li><li data-o=\"c\" tabindex=\"0\">c- Bind to rER at ribophorins<\/li><li data-o=\"d\" tabindex=\"0\">d- Form the steroid hormones<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-042\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">42- The secretory vesicles in a cell arise from:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- SER<\/li><li data-o=\"b\" tabindex=\"0\">b- rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-043\" data-k=\"b\" data-bk=\"a\" data-fx=\"الغشاء الداخلي للميتوكوندريا يكوّن الأعراف (cristae)، أما هضم الخلية فوظيفة الـlysosomes.\"><p class=\"qt\" dir=\"ltr\">43- Which statement is correct about the mitochondria?<span class=\"gtag\" dir=\"ltr\">198<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Responsible for cell digestion<\/li><li data-o=\"b\" tabindex=\"0\">b- Inner membrane form cristae<\/li><li data-o=\"c\" tabindex=\"0\">c- Form intracellular pathway<\/li><li data-o=\"d\" tabindex=\"0\">d- Stain orange with silver<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-044\" data-k=\"c\" data-bk=\"a\" data-fx=\"الـpars amorpha هي المنطقة الفاتحة من النوية وتتكوّن من خيوط الـDNA (strands of DNA)، والمفتاح المعتمد بعد مراجعة د. زهرة هو c.\"><p class=\"qt\" dir=\"ltr\">44- Pars amorpha of nucleolus is<span class=\"gtag\" dir=\"ltr\">198<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Light area<\/li><li data-o=\"b\" tabindex=\"0\">b- Filaments of rRNA<\/li><li data-o=\"c\" tabindex=\"0\">c- Strands of DNA<\/li><li data-o=\"d\" tabindex=\"0\">d- Granules of rRNA<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-045\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">45- Regarding the Golgi apparatus, it is:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of saccules covered by ribosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- The power house of the cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Stained by silver<\/li><li data-o=\"d\" tabindex=\"0\">d- A non-membranous organelle<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-046\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">46- Glycogen in the.liver can be stained by.<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- PAS<\/li><li data-o=\"b\" tabindex=\"0\">b- Silver<\/li><li data-o=\"c\" tabindex=\"0\">c- Iron hematoxylin<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c1e-047\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">47- Formation of mitotic spindle in mitosis is related to:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Actin<\/li><li data-o=\"b\" tabindex=\"0\">b- Microvilli<\/li><li data-o=\"c\" tabindex=\"0\">c- Centriole<\/li><li data-o=\"d\" tabindex=\"0\">d- Lysosome<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><\/div><div class=\"gpart\" data-part=\"2\" data-ch=\"c2\"><h2 dir=\"ltr\">Chapter 2 · Blood <small>— الدم · 223 سؤال · <bdi dir=\"ltr\">Dr. Zahra MCQs<\/bdi><\/small><\/h2><section class=\"tsec gsec\" data-g=\"h2_t01\"><h3>RBCs <small>— 31 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t01\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-001\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">1- Blood is ........................ in origin:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ectodermal<\/li><li data-o=\"b\" tabindex=\"0\">b- Mesodermal<\/li><li data-o=\"c\" tabindex=\"0\">c- Endodermal<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-002\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">2- Blood elements constitute about ......... of blood:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 35%<\/li><li data-o=\"b\" tabindex=\"0\">b- 45%<\/li><li data-o=\"c\" tabindex=\"0\">c- 55%<\/li><li data-o=\"d\" tabindex=\"0\">d- 65%<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-003\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">3- Blood elements are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- erythrocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- leukocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- thrombocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-004\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">4- Normal RBCs are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- oval in shape<\/li><li data-o=\"b\" tabindex=\"0\">b- nucleated biconcave discs<\/li><li data-o=\"c\" tabindex=\"0\">c- non nucleated biconcave discs<\/li><li data-o=\"d\" tabindex=\"0\">d- non nucleated biconvex discs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-005\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">5- Staining of blood film is done by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- orcein stain<\/li><li data-o=\"b\" tabindex=\"0\">b- silver stain<\/li><li data-o=\"c\" tabindex=\"0\">c- H&amp;E stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Leishman’s stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- The outer surface of cell membrane of RBCs is responsible for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- blood grouping<\/li><li data-o=\"b\" tabindex=\"0\">b- maintenance of its shape<\/li><li data-o=\"c\" tabindex=\"0\">c- maintenance of its color<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-007\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">7- Function of RBCs is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- transfer gases<\/li><li data-o=\"b\" tabindex=\"0\">b- acid base buffer<\/li><li data-o=\"c\" tabindex=\"0\">c- phagocytosis<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-008\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">8- Rouleaux appearance is characteristic for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- WBCs<\/li><li data-o=\"c\" tabindex=\"0\">c- monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- none of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-009\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">9- The followings concerning RBC adaptation to its function EXCEPT<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Biconcave shape provides a large surface area<\/li><li data-o=\"b\" tabindex=\"0\">b- Cell membrane is highly selective for gas exchange<\/li><li data-o=\"c\" tabindex=\"0\">c- Cell membrane is elastic to pass through the small capillaries<\/li><li data-o=\"d\" tabindex=\"0\">d- The small nucleus provides a wide space for hemoglobin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-010\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">10- Spectrin cytoskeletal network protein:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- support RBC cell membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Present in specific granules of neutrophils.<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in specific granules of eosinophils.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in specific granules of basophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-011\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">11- Responsible for blood Grouping:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell coat on outer surface of RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoskeleton on the inner surface of RBCs plasma membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Cholesterol<\/li><li data-o=\"d\" tabindex=\"0\">d- Phospholipids<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-012\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">12- Responsible for RBCs Elasticity &amp; flexibility:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell coat on outer surface of RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- Cytoskeleton on the inner surface of RBCs plasma membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Cholesterol<\/li><li data-o=\"d\" tabindex=\"0\">d- Phospholipids<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-013\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">13- Regarding RBCs:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Aged RBCs are destroyed in bone marrow by megakaryocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Decreased number is called polycythemia<\/li><li data-o=\"c\" tabindex=\"0\">c- Their biconvex shape is maintained by cytoskeleton<\/li><li data-o=\"d\" tabindex=\"0\">d- They tend to form rouleaux appearance in slow circulation<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-014\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">14- Polycythemia is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- decreased Hb in RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- decreased number of RBCs<\/li><li data-o=\"c\" tabindex=\"0\">c- increased number of RBCs<\/li><li data-o=\"d\" tabindex=\"0\">d- increase size of RBCs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-015\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">15- Mature erythrocyte<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lacking nuclei<\/li><li data-o=\"b\" tabindex=\"0\">b- Rich with mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Rich with ribosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Have a diameter less than 6 pm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-016\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">16- The life span of erythrocyte in the circulation is approximately<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 20 days<\/li><li data-o=\"b\" tabindex=\"0\">b- 1 year<\/li><li data-o=\"c\" tabindex=\"0\">c- 5 weeks<\/li><li data-o=\"d\" tabindex=\"0\">d- 4 months<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-017\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">17- Which of the following gives more space for Hb?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Biconcave shape of RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- absence of nuclei<\/li><li data-o=\"c\" tabindex=\"0\">c- absence of organelles<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-018\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">18- Concerning the rouleaux appearance, which is false?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- RBCs adhere to each other<\/li><li data-o=\"b\" tabindex=\"0\">b- Occurs in slow circulation<\/li><li data-o=\"c\" tabindex=\"0\">c- its cause is high surface tension<\/li><li data-o=\"d\" tabindex=\"0\">d- its cause is low surface tension<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-019\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">19- Concerning highly selective lipoproteins of plasmalemma, which is false?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- allows gas exchange<\/li><li data-o=\"b\" tabindex=\"0\">b- allows escape of Hb<\/li><li data-o=\"c\" tabindex=\"0\">c- prevents of escape of Hb<\/li><li data-o=\"d\" tabindex=\"0\">d- none of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- The spectrin &amp; actin at inner surface of cell membrane of RBCs is responsible for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- blood grouping<\/li><li data-o=\"b\" tabindex=\"0\">b- maintenance of its shape<\/li><li data-o=\"c\" tabindex=\"0\">c- maintenance of its color<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-021\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">21- Regarding Red blood cells all are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- have a biconcave shape which maximizes the surface/volume ratio for gas transfer in capillary vessels<\/li><li data-o=\"b\" tabindex=\"0\">b- have no mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- have a membrane-associated cytoskeleton which maintains their shape<\/li><li data-o=\"d\" tabindex=\"0\">d- have a life span in peripheral blood of about 20 days<\/li><li data-o=\"e\" tabindex=\"0\">e- are removed, when aged, by cells in the spleen<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-022\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">22- The following statements concerning erythrocytes are true EXCEPT<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Rounded biconcave non nucleated cells<\/li><li data-o=\"b\" tabindex=\"0\">b- 6-9 um in diameter<\/li><li data-o=\"c\" tabindex=\"0\">c- It is red because of its hemoglobin content<\/li><li data-o=\"d\" tabindex=\"0\">d- It is very active cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-023\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">23- The following are characters of RBCs except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- average diameter is 7.5 um<\/li><li data-o=\"b\" tabindex=\"0\">b- have a role in immunity<\/li><li data-o=\"c\" tabindex=\"0\">c- have biconcave shape<\/li><li data-o=\"d\" tabindex=\"0\">d- can form rouleaux appearance<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-024\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">24- The average size of RBCs<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 7.0 µm<\/li><li data-o=\"b\" tabindex=\"0\">b- 7.0 nm<\/li><li data-o=\"c\" tabindex=\"0\">c- 7.0 mm<\/li><li data-o=\"d\" tabindex=\"0\">d- 0.7 cm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-025\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">25- By E.M. RBCs are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Nucleated biconcave discs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Having many mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Electron-dense homogenous hemoglobin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-026\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">26- The normal shape of RBCs is kept by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycocalyx.<\/li><li data-o=\"b\" tabindex=\"0\">b- Actin and spectrin<\/li><li data-o=\"c\" tabindex=\"0\">c- Lipoproteins of plasmalemma.<\/li><li data-o=\"d\" tabindex=\"0\">d- Haemoglobin S.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-027\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">27- Regarding RBCs adaptation to perform their function, they are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Containing carbonic anhydrase enzyme<\/li><li data-o=\"b\" tabindex=\"0\">b- Rich in mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Having a central granular part<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in Ca++ and serotonin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-028\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">28- Formation of an abnormal rigid type of Hb (HBS) results in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Sickle cell anemia<\/li><li data-o=\"b\" tabindex=\"0\">b- Favism.<\/li><li data-o=\"c\" tabindex=\"0\">c- Aplastic anemia<\/li><li data-o=\"d\" tabindex=\"0\">d- Spherocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-029\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">29- The following is character of the erythrocytes<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- its average diameter is 7.5 µm<\/li><li data-o=\"b\" tabindex=\"0\">b- Its life span is about 20 days<\/li><li data-o=\"c\" tabindex=\"0\">c- its count ranges from 4000 - 11000/mm³<\/li><li data-o=\"d\" tabindex=\"0\">d- Decreased its number below 4 million/mm³ is called polycythemia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-030\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">30- Plasmalemma or RBCs is adapted for gas exchange due to high:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Myoglobin content.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cholesterol content<\/li><li data-o=\"c\" tabindex=\"0\">c- Carbohydrate content<\/li><li data-o=\"d\" tabindex=\"0\">d- Lipoprotein content<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-031\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">31- One is true about RBCs:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contain azurophilic granules<\/li><li data-o=\"b\" tabindex=\"0\">b- The center is thicker than the periphery<\/li><li data-o=\"c\" tabindex=\"0\">c- About 10-12 um in diameter<\/li><li data-o=\"d\" tabindex=\"0\">d- Increase in chronic lung disease<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t02\"><h3>Neutrophils <small>— 18 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t02\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-032\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">32- Non granular WBCs are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-033\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">33- Nucleus of neutrophils is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- multilobed segmented<\/li><li data-o=\"b\" tabindex=\"0\">b- bilobed horse show<\/li><li data-o=\"c\" tabindex=\"0\">c- S shaped<\/li><li data-o=\"d\" tabindex=\"0\">d- large kidney shaped<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-034\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">34- The cells which have the largest percentage of WBCs are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- basophils<\/li><li data-o=\"d\" tabindex=\"0\">d- lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-035\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">35- Neutrophils increase in number in case of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bacterial infection<\/li><li data-o=\"b\" tabindex=\"0\">b- Parasitic infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Allergy<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-036\" data-k=\"e\"><p class=\"qt\" dir=\"ltr\">36- Neutrophils<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- possess specific granules that are smaller than azurophilic granules<\/li><li data-o=\"b\" tabindex=\"0\">b- Have multilobed segmented nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- termed polymorphonuclear<\/li><li data-o=\"d\" tabindex=\"0\">d- have phagocytic function<\/li><li data-o=\"e\" tabindex=\"0\">e- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-037\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">37- About neutrophil, all true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Has segmented nucleus 3-5 segments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Differential count 60-70%<\/li><li data-o=\"c\" tabindex=\"0\">c- The largest leucocyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- Phagocytic in function.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-038\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">38- Neutrophil function include the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 1st line of defense against infection<\/li><li data-o=\"b\" tabindex=\"0\">b- Highly Phagocytic in function.<\/li><li data-o=\"c\" tabindex=\"0\">c- Increase in acute bacterial infection<\/li><li data-o=\"d\" tabindex=\"0\">d- Secrete antibodies.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-039\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">39- Specific granules of neutrophils, all true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contain lactoferrin<\/li><li data-o=\"b\" tabindex=\"0\">b- Contain collagenase enzyme<\/li><li data-o=\"c\" tabindex=\"0\">c- Contain lysozyme<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain basic proteins to kill parasites<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-040\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">40- Neutrophils characterized by the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Segmented nucleus with 3-5 lobes<\/li><li data-o=\"b\" tabindex=\"0\">b- Bilobed nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophilic specific granules<\/li><li data-o=\"d\" tabindex=\"0\">d- Neutrophilia in acute bacterial infections<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-041\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">41- Specific granules of neutrophils contain all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- phagocytin<\/li><li data-o=\"b\" tabindex=\"0\">b- lactoferrin<\/li><li data-o=\"c\" tabindex=\"0\">c- collagenase<\/li><li data-o=\"d\" tabindex=\"0\">d- sulfatase<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-042\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">42- Granular WBCs are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-043\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">43- More heterochromatin is prominent in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- basophils<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-044\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">44- Neutrophils:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Increase in parasitic disease<\/li><li data-o=\"b\" tabindex=\"0\">b- Terminate allergy<\/li><li data-o=\"c\" tabindex=\"0\">c- Increase in acute pyogenic infection<\/li><li data-o=\"d\" tabindex=\"0\">d- Result in the humoral immunity<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-045\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">45- Neutrophils:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Increase in parasitic disease<\/li><li data-o=\"b\" tabindex=\"0\">b- Terminate allergy<\/li><li data-o=\"c\" tabindex=\"0\">c- Decrease in typhoid fever<\/li><li data-o=\"d\" tabindex=\"0\">d- Result in the humoral immunity<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-046\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">46- Neutrophils are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secrete bactericidal phagocytin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have non segmented nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Decrease in number during treatment with cortisone.<\/li><li data-o=\"d\" tabindex=\"0\">d- They have azurophil granules only<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-047\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">47- The blood count of a patient suffering from acute tonsillitis shows increase in the percentage of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Eosinophils.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophils<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-048\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">48- A 21 years old patient suffering from abdominal pain. His serological tests are indicating typhoid fever &amp; CBC will show:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basophilia<\/li><li data-o=\"b\" tabindex=\"0\">b- Polycythemia<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutropenia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophilia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-049\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">49- One of the following is a cause of neutrophilia:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Typhoid fever<\/li><li data-o=\"b\" tabindex=\"0\">b- Chronic infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Parasitic disease<\/li><li data-o=\"d\" tabindex=\"0\">d- Acute pyogenic infection<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t03\"><h3>Eosinophils <small>— 12 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t03\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-050\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">50- Nucleus of eosinophils is<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- multilobed segmented<\/li><li data-o=\"b\" tabindex=\"0\">b- bilobed horse shoe<\/li><li data-o=\"c\" tabindex=\"0\">c- S shaped<\/li><li data-o=\"d\" tabindex=\"0\">d- large kidney shaped<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-051\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">51- More euchromatin is prominent in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- basophils<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-052\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">52- Eosinophils increase in number in case of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bacterial infection<\/li><li data-o=\"b\" tabindex=\"0\">b- Parasitic infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Allergy<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-053\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">53- Cells which release histaminase enzyme:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- plasma cells<\/li><li data-o=\"d\" tabindex=\"0\">d- basophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-054\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">54- Eosinophile, all true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- bilobed nucleus<\/li><li data-o=\"b\" tabindex=\"0\">b- have large acidophilic granules<\/li><li data-o=\"c\" tabindex=\"0\">c- specific granules contain histaminase<\/li><li data-o=\"d\" tabindex=\"0\">d- have the largest diameter in leucocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-055\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">55- Specific granules of eosinophils contain all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- histamine<\/li><li data-o=\"b\" tabindex=\"0\">b- histaminase<\/li><li data-o=\"c\" tabindex=\"0\">c- neurotoxins<\/li><li data-o=\"d\" tabindex=\"0\">d- sulfatase<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-056\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">56- Eosinophils are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Spherical Nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- S shaped Nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Coarse basophilic granules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Granules with dense core.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-057\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">57- Horse shoe nucleus is a feature of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Monocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-058\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">58- Eosinophils are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have horse-shoe shaped nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Increase in liver cirrhosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secrete histamine.<\/li><li data-o=\"d\" tabindex=\"0\">d- Have non-specific granules only.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-059\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">59- Role of eosinophils in termination of a case of allergy to a sting bite occurs through:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion of neurotoxin<\/li><li data-o=\"b\" tabindex=\"0\">b- Phagocytosis of antigen-antibody complex<\/li><li data-o=\"c\" tabindex=\"0\">c- Vasodilatation increasing capillary permeability<\/li><li data-o=\"d\" tabindex=\"0\">d- Direct cytotoxic effect.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-060\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">60- One of the following is true about eosinophils:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secrete eosinophil chemotactic factor<\/li><li data-o=\"b\" tabindex=\"0\">b- Have horse-shoe shaped nuclei<\/li><li data-o=\"c\" tabindex=\"0\">c- Represent about 60-70 % of circulating leucocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Secrete histamine and heparin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-061\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">61- The blood film of a patient suffering from bronchial asthma shows:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophilia and eosinophilia<\/li><li data-o=\"b\" tabindex=\"0\">b- Eosinophilia and basophilia<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophilia and monocytosis<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophilia and lymphocytosis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t04\"><h3>Basophils <small>— 15 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t04\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-062\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">62- Nucleus of basophils is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- multilobed segmented<\/li><li data-o=\"b\" tabindex=\"0\">b- bilobed horse show<\/li><li data-o=\"c\" tabindex=\"0\">c- S shaped<\/li><li data-o=\"d\" tabindex=\"0\">d- large kidney shaped<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-063\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">63- The cells which have the smallest percentage of WBCs are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- basophils<\/li><li data-o=\"d\" tabindex=\"0\">d- lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-064\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">64- Basophils increase in number in case of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bacterial infection<\/li><li data-o=\"b\" tabindex=\"0\">b- Parasitic infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Allergy<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-065\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">65- Cells which release histamine:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- plasma cells<\/li><li data-o=\"d\" tabindex=\"0\">d- basophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-066\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">66- The metachromatic granules are found in the following cells<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cells<\/li><li data-o=\"c\" tabindex=\"0\">c- eosinophils<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-067\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">67- Azurophilic granules contain mainly:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- collagenase<\/li><li data-o=\"b\" tabindex=\"0\">b- histaminase<\/li><li data-o=\"c\" tabindex=\"0\">c- sulfatase<\/li><li data-o=\"d\" tabindex=\"0\">d- hydrolytic enzymes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-068\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">68- Specific granules of basophils contain all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- histamine<\/li><li data-o=\"b\" tabindex=\"0\">b- histaminase<\/li><li data-o=\"c\" tabindex=\"0\">c- heparin<\/li><li data-o=\"d\" tabindex=\"0\">d- leukotrienes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-069\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">69- Cell membrane of basophils shows receptors for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- IgA<\/li><li data-o=\"b\" tabindex=\"0\">b- IgE<\/li><li data-o=\"c\" tabindex=\"0\">c- IgM<\/li><li data-o=\"d\" tabindex=\"0\">d- IgD<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-070\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">70- Basophils are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Smaller diameter than RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- Presence of azurophilic granules only<\/li><li data-o=\"c\" tabindex=\"0\">c- S-shaped nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Acidophilic coarse granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-071\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">71- ONE is a function of Basophils:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Release of trephone substance.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secretion of histamine and heparin<\/li><li data-o=\"c\" tabindex=\"0\">c- Production of histaminases<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-072\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">72- Cell membrane of basophils has receptors for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Immunoglobulin E<\/li><li data-o=\"b\" tabindex=\"0\">b- Immunoglobulin M<\/li><li data-o=\"c\" tabindex=\"0\">c- Immunoglobulin D<\/li><li data-o=\"d\" tabindex=\"0\">d- Immunoglobulin A<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-073\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">73- The white blood cells with histamine &amp; heparin containing granules are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-074\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">74- Regarding basophils, they:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Constitute 3-8% of circulating leucocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Increase in acute pyogenic infection.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have kidney shaped nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are rich in metachromatically stained granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-075\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">75- Basophils:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are the least common leucocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Increase in influenza<\/li><li data-o=\"c\" tabindex=\"0\">c- Have kidney-shaped nuclei<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain coarse shiny red granules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-076\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">76- Leukocytes promote the allergy are called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Monocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t05\"><h3>Lymphocytes <small>— 20 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t05\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-077\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">77- B Lymphocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mature in bone marrow<\/li><li data-o=\"b\" tabindex=\"0\">b- mature in thymus<\/li><li data-o=\"c\" tabindex=\"0\">c- responsible for humoral immunity<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-078\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">78- T Lymphocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mature in bone marrow<\/li><li data-o=\"b\" tabindex=\"0\">b- mature in thymus<\/li><li data-o=\"c\" tabindex=\"0\">c- responsible for Cellular immunity<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-079\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">79- Lymphocytosis occurs in case of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- acute infection<\/li><li data-o=\"b\" tabindex=\"0\">b- chronic infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Leukemia<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp;c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-080\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">80- The smallest nucleated blood cell is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophil.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small Lymphocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophile.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-081\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">81- Leucocytes with granules similar to that of mast cell:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Eosinophil.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophil.<\/li><li data-o=\"d\" tabindex=\"0\">d- Monocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-082\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">82- About T lymphocytes all true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mature in thymus glands<\/li><li data-o=\"b\" tabindex=\"0\">b- 80% of small lymphocytes in blood.<\/li><li data-o=\"c\" tabindex=\"0\">c- Responsible for cellular immunity<\/li><li data-o=\"d\" tabindex=\"0\">d- Responsible for humoral immunity.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-083\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">83- Which of the following leucocytes migrate to the connective tissue and differentiate into a cell that is positively stained for acid phosphatase enzyme?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- basophils<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- monocytes<\/li><li data-o=\"e\" tabindex=\"0\">e- platelets<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-084\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">84- Concerning B lymphocytes, all true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Develop from bone marrow<\/li><li data-o=\"b\" tabindex=\"0\">b- Constitute 80% of circulating small lymphocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Have immunoglobulin receptors<\/li><li data-o=\"d\" tabindex=\"0\">d- Responsible for humoral immunity<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-085\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">85- B lymphocytes can<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- ingest pathogenic organisms<\/li><li data-o=\"b\" tabindex=\"0\">b- Differentiate into plasma cells during immune responses<\/li><li data-o=\"c\" tabindex=\"0\">c- Differentiate into macrophage as a result of tissue damage<\/li><li data-o=\"d\" tabindex=\"0\">d- Secrete histamine<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-086\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">86- Which of these blood elements can differentiate into Plasma cells?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Monocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- B Lymphocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- T Lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-087\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">87- Only ONE statement is correct about small lymphocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Abundant cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Indented nucleus with nucleolus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed organelles.<\/li><li data-o=\"d\" tabindex=\"0\">d- The majority of circulating lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-088\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">88- Leucocytes promote the allergy are called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Lymphocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-089\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">89- Which of the following is a non-granular leukocyte:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-090\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">90- Regarding T-lymphocytes, the CD8 cells are ............... T-cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- helper<\/li><li data-o=\"b\" tabindex=\"0\">b- memory<\/li><li data-o=\"c\" tabindex=\"0\">c- cytotoxic<\/li><li data-o=\"d\" tabindex=\"0\">d- regulatory<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-091\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">91- The surface marker/ receptor that identifies NK cell is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- CD16.<\/li><li data-o=\"b\" tabindex=\"0\">b- CD4.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ig M.<\/li><li data-o=\"d\" tabindex=\"0\">d- Ig D.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-092\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">92- Which leucocyte is responsible for Cell mediated immunity?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- B- lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophils<\/li><li data-o=\"c\" tabindex=\"0\">c- T- lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Monocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-093\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">93- The nuclei of granular leucocytes are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Multiple oval<\/li><li data-o=\"b\" tabindex=\"0\">b- Single segmented<\/li><li data-o=\"c\" tabindex=\"0\">c- Single rounded<\/li><li data-o=\"d\" tabindex=\"0\">d- Multiple kidney shape<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-094\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">94- As regards B Lymphocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have a long life span<\/li><li data-o=\"b\" tabindex=\"0\">b- Secrete perforins<\/li><li data-o=\"c\" tabindex=\"0\">c- Responsible for humoral immunity<\/li><li data-o=\"d\" tabindex=\"0\">d- Migrate to thymus gland for differentiation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-095\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">95- HIV human immunodeficiency virus that causes AIDS destroys the following type of T lymphocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cytotoxic T-cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Helper T-cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Regulatory (Suppressor) T-cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Memory T-cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-096\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">96- Natural killer cells express the following surface markers (receptors):<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- CD4<\/li><li data-o=\"b\" tabindex=\"0\">b- IgM<\/li><li data-o=\"c\" tabindex=\"0\">c- CD16<\/li><li data-o=\"d\" tabindex=\"0\">d- CD8<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t06\"><h3>Monocytes <small>— 5 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t06\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-097\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">97- Nucleus of monocyte is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- multilobed segmented<\/li><li data-o=\"b\" tabindex=\"0\">b- bilobed horse show<\/li><li data-o=\"c\" tabindex=\"0\">c- S shaped<\/li><li data-o=\"d\" tabindex=\"0\">d- large kidney shaped<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-098\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">98- Frosted glass appearance is characteristic for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- WBCs<\/li><li data-o=\"c\" tabindex=\"0\">c- monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- none of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-099\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">99- Monocyte can give rise to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mast cells<\/li><li data-o=\"b\" tabindex=\"0\">b- plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- macrophage<\/li><li data-o=\"d\" tabindex=\"0\">d- lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-100\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">100- The most prominent cytoplasmic organelles in monocytes are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus and lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycogen granules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria.<\/li><li data-o=\"d\" tabindex=\"0\">d- sER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-101\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">101- Cytoplasm with frosted glass appearance is a feature of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Eosinophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Monocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophils<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t07\"><h3>Platelets <small>— 18 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t07\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-102\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">102- Blood platelets have the following characters except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- they are normally 150,000-400,000/mm?<\/li><li data-o=\"b\" tabindex=\"0\">b- have central granulomere and peripheral hyalomere<\/li><li data-o=\"c\" tabindex=\"0\">c- they initiate local coagulation<\/li><li data-o=\"d\" tabindex=\"0\">d- have small lobulated nuclei<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-103\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">103- In the platelets, the granulomere contains the followings EXCEPT<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Alpha granules which contain clotting factors<\/li><li data-o=\"b\" tabindex=\"0\">b- Beta granules which contain DNA &amp; RNA<\/li><li data-o=\"c\" tabindex=\"0\">c- Delta granules which contain calcium ions<\/li><li data-o=\"d\" tabindex=\"0\">d- Lambda granules which contain hydrolytic enzymes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-104\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">104- Hyalomere of blood platelets contain:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microtubule rings.<\/li><li data-o=\"b\" tabindex=\"0\">b- Actin and Myosin filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Dense and surface connected tubular system.<\/li><li data-o=\"d\" tabindex=\"0\">d- All the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-105\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">105- Origin of blood platelets:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mesenchymal cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Monocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-106\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">106- The following originate from megakaryocyte:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Platelets<\/li><li data-o=\"b\" tabindex=\"0\">b- Erythrocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Lymphocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-107\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">107- Platelets characterized by the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Presence of microtubules &amp; microfilaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Presence of different types of granules<\/li><li data-o=\"c\" tabindex=\"0\">c- Presence of large lobulated nuclei<\/li><li data-o=\"d\" tabindex=\"0\">d- Important in blood coagulation<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-108\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">108- Hyalomere is in<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- T lymphocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- B lymphocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- platelets<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-109\" data-k=\"e\"><p class=\"qt\" dir=\"ltr\">109- Granulomere is a central dark granular layer of<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- eosinophils<\/li><li data-o=\"c\" tabindex=\"0\">c- basophils<\/li><li data-o=\"d\" tabindex=\"0\">d- erythrocytes<\/li><li data-o=\"e\" tabindex=\"0\">e- none of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-110\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">110- Granulomere of blood platelets contains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Actin microfilaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Open canalicular system<\/li><li data-o=\"c\" tabindex=\"0\">c- Dense tubular system<\/li><li data-o=\"d\" tabindex=\"0\">d- Delta granules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-111\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">111- Serotonin in blood platelets presents in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cytoskeletal microtubules<\/li><li data-o=\"b\" tabindex=\"0\">b- Delta (dense) granules<\/li><li data-o=\"c\" tabindex=\"0\">c- Open canalicular system<\/li><li data-o=\"d\" tabindex=\"0\">d- Dense canalicular system<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-112\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">112- Large cell with single multilobed dark nucleus &amp; basophilic cytoplasm is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-113\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">113- Granulomere of blood platelets contains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lambda granules.<\/li><li data-o=\"b\" tabindex=\"0\">b- Actin microfilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Microtubules<\/li><li data-o=\"d\" tabindex=\"0\">d- Membranous channels.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-114\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">114- Lambda granules of blood platelets contain:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Growth factors.<\/li><li data-o=\"c\" tabindex=\"0\">c- ATP and ADP.<\/li><li data-o=\"d\" tabindex=\"0\">d- clotting factors.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-115\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">115- Megakaryocyte is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- found in peripheral blood<\/li><li data-o=\"b\" tabindex=\"0\">b- Form RBCs<\/li><li data-o=\"c\" tabindex=\"0\">c- Acidophilic cytoplasm<\/li><li data-o=\"d\" tabindex=\"0\">d- Nucleus is single and multilobed<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-116\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">116- Regarding blood platelets, the peripheral zone contains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Actin microfilaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Glycogen.<\/li><li data-o=\"d\" tabindex=\"0\">d- Serotonin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-117\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">117- Granulomere is a central dark granular layer of the following blood element:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophils<\/li><li data-o=\"c\" tabindex=\"0\">c- Erythrocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Platelets<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-118\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">118- The megakaryocyte is characterized by the following<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have single multilobed dark nucleus<\/li><li data-o=\"b\" tabindex=\"0\">b- Have acidophilic cytoplasm rich in lysosomes<\/li><li data-o=\"c\" tabindex=\"0\">c- Found on bony surface, in howship’s lacunae<\/li><li data-o=\"d\" tabindex=\"0\">d- Give origin to metamyelocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-119\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">119- Granulomere of blood platelets contains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Dense tubular system<\/li><li data-o=\"b\" tabindex=\"0\">b- Alpha granules that contain serotonin<\/li><li data-o=\"c\" tabindex=\"0\">c- Delta granules that contain ATP<\/li><li data-o=\"d\" tabindex=\"0\">d- Lambda granules that contain clotting factor<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t08\"><h3>Bone marrow <small>— 8 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t08\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-120\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">120- One statement is NOT correct<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- There are two type of bone marrow; red and yellow<\/li><li data-o=\"b\" tabindex=\"0\">b- Yellow marrow, under stress, can convert to red marrow<\/li><li data-o=\"c\" tabindex=\"0\">c- Yellow bone marrow is present in epiphysis of long bone of adults<\/li><li data-o=\"d\" tabindex=\"0\">d- After adulthood, red bone marrow is present in the spongy bone<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-121\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">121- Fixed cells of bone marrow include the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts<\/li><li data-o=\"b\" tabindex=\"0\">b- Fat cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Endothelium of blood sinusoids<\/li><li data-o=\"d\" tabindex=\"0\">d- Megakaryocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-122\" data-k=\"e\"><p class=\"qt\" dir=\"ltr\">122- In adults, Red (active) bone marrow is present in the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- epiphysis of the long bones<\/li><li data-o=\"b\" tabindex=\"0\">b- ribs<\/li><li data-o=\"c\" tabindex=\"0\">c- body of vertebrae<\/li><li data-o=\"d\" tabindex=\"0\">d- sternum.<\/li><li data-o=\"e\" tabindex=\"0\">e- Shaft (diaphysis of the long bones)<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-123\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">123- Red bone marrow<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- active found in cavities of bones of embryos<\/li><li data-o=\"b\" tabindex=\"0\">b- found in shaft of long bones in adults<\/li><li data-o=\"c\" tabindex=\"0\">c- has a high content of fat cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-124\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">124- The stroma of the red bone marrow contains all the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- reticular cells<\/li><li data-o=\"b\" tabindex=\"0\">b- fat cells<\/li><li data-o=\"c\" tabindex=\"0\">c- osteocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- macrophages<\/li><li data-o=\"e\" tabindex=\"0\">e- fibroblasts<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-125\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">125- In the red bone marrow, you can recognize<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cells, fibroblasts and endothelial cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages and reticular ells<\/li><li data-o=\"c\" tabindex=\"0\">c- Blood forming cells<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-126\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">126- The largest cell in the bone marrow is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Osteogenic cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblast<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Fat cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-127\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">127- Concerning the red bone marrow which statement is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular cells are among the free bone marrow cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ratio of immature WBCs to immature RBCs is 5:1<\/li><li data-o=\"c\" tabindex=\"0\">c- Blood sinusoid in its stroma has continuous basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in shaft of long bone in adult<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t09\"><h3>Reticulocytes <small>— 4 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t09\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-128\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">128- Concerning Reticulocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Number decreases in hemorrhage<\/li><li data-o=\"b\" tabindex=\"0\">b- Can be stained by supravital stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Percentage in normal blood is more than 7%<\/li><li data-o=\"d\" tabindex=\"0\">d- Smaller than RBCs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-129\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">129- Concerning Reticulocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Percentage increases in hemorrhage<\/li><li data-o=\"b\" tabindex=\"0\">b- Percentage in normal blood is more than 7%<\/li><li data-o=\"c\" tabindex=\"0\">c- Mature RBCs<\/li><li data-o=\"d\" tabindex=\"0\">d- Smaller than RBCs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-130\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">130- The..........can be stained by brilliant cresyl blue stain:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- monocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticulocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- basophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-131\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">131- Regarding the reticulocyte, the following statement is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Acidophilic cytoplasm with basophilic reticulum.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its size is 20 um<\/li><li data-o=\"c\" tabindex=\"0\">c- Their % increases in case of allergy<\/li><li data-o=\"d\" tabindex=\"0\">d- Its percentage is 60-70% of total leucocytic count.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_t10\"><h3>Hemopoiesis <small>— 19 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_t10\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2z-132\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">132- During erythropoiesis, the following changes occur except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- the nucleus becomes smaller and disappears<\/li><li data-o=\"b\" tabindex=\"0\">b- the size of the cells decrease<\/li><li data-o=\"c\" tabindex=\"0\">c- fine granules appear in the cytoplasm<\/li><li data-o=\"d\" tabindex=\"0\">d- cytoplasm change to acidophilic<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-133\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">133- During the process of erythropoiesis, the following are changes except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- the size of cells gradually decrease<\/li><li data-o=\"b\" tabindex=\"0\">b- finally, the nucleus disappears<\/li><li data-o=\"c\" tabindex=\"0\">c- finally, the nucleolus disappears<\/li><li data-o=\"d\" tabindex=\"0\">d- the cytoplasm change from acidophilic to basophilic<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-134\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">134- In adults, erythrocytes develop in<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- peripheral blood<\/li><li data-o=\"b\" tabindex=\"0\">b- red bone marrow<\/li><li data-o=\"c\" tabindex=\"0\">c- spleen<\/li><li data-o=\"d\" tabindex=\"0\">d- liver<\/li><li data-o=\"e\" tabindex=\"0\">e- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-135\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">135- The process by which the blood cells are formed is called<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hemopoiesis<\/li><li data-o=\"b\" tabindex=\"0\">b- Erythropoiesis<\/li><li data-o=\"c\" tabindex=\"0\">c- Osteogenesis<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-136\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">136- The process by which RBCs is formed is called<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Erythroblastosis<\/li><li data-o=\"b\" tabindex=\"0\">b- Erythropoiesis<\/li><li data-o=\"c\" tabindex=\"0\">c- Hemopoiesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Thrombopoiesis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-137\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">137- Concerning the erythropoiesis, the following cell has no nucleus<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Proerythroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophilic erythroblast<\/li><li data-o=\"c\" tabindex=\"0\">c- Normoblast<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticulocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-138\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">138- Regarding Erythropoiesis all are true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Occurs in red bone marrow in adult<\/li><li data-o=\"b\" tabindex=\"0\">b- Occurs in the liver in the second trimester of pregnancy<\/li><li data-o=\"c\" tabindex=\"0\">c- PHSC cells are the mother cells of all blood cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Precursor cells have the ability of self-renewal<\/li><li data-o=\"e\" tabindex=\"0\">e- The progenitor cells have no special features<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-139\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">139- During erythropoiesis hemoglobin begins to accumulate in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Normoblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- Proerythroblasts.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophil erythroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- Polychromatophilic erythroblasts.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-140\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">140- In the development of granulocytes, the first sign of differentiation between types occurs at...... Stage<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- metamyelocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- promyelocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- myelocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Band cell<\/li><li data-o=\"e\" tabindex=\"0\">e- Myeloblast<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-141\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">141- In the development of granulocytes, mitosis stops at.... stage<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- metamyelocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- promyelocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- myelocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Band cell<\/li><li data-o=\"e\" tabindex=\"0\">e- Myeloblast<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-142\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">142- In granulopoiesis, the non-specific granules start to appear at which stage:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- myeloblast<\/li><li data-o=\"b\" tabindex=\"0\">b- myelocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- promyelocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- metamyelocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-143\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">143- In granulopoiesis, the specific granules start to appear at which stage:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- myeloblast<\/li><li data-o=\"b\" tabindex=\"0\">b- myelocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- promyelocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- metamyelocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-144\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">144- Which is the correct sequence in erythropoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stem cell &gt; CFU &gt; erythroblasts &gt; reticulocytes &gt; RBCs<\/li><li data-o=\"b\" tabindex=\"0\">b- Stem cell &gt; megakaryoblast &gt; RBC &gt; reticulocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- CFU &gt; stem cell &gt; erythroblast &gt; RBC<\/li><li data-o=\"d\" tabindex=\"0\">d- Stem cell &gt; reticulocyte &gt; erythroblast &gt; RBC<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-145\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">145- Which is the correct sequence of thrombopoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stem cell &gt; CFU &gt; megakaryoblasts &gt; megakaryocytes &gt; platelets<\/li><li data-o=\"b\" tabindex=\"0\">b- Stem cell &gt; CFU &gt; platelets &gt; megakaryocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Stem cell &gt; erythroblast &gt; megakaryocyte &gt; platelets<\/li><li data-o=\"d\" tabindex=\"0\">d- Stem cell &gt; monoblast &gt; platelets<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-146\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">146- A high number of band neutrophils in blood indicates:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Viral infection<\/li><li data-o=\"b\" tabindex=\"0\">b- Ongoing bacterial infection<\/li><li data-o=\"c\" tabindex=\"0\">c- Increased platelet production<\/li><li data-o=\"d\" tabindex=\"0\">d- Normal erythropoiesis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-147\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">147- Which is the correct sequence of monocytopoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stem cell &gt; CFU &gt; monoblasts &gt; promonocytes &gt; monocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Stem cell &gt; CFU &gt; lymphoblasts &gt; monocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Stem cell &gt; megakaryoblasts &gt; monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Stem cell &gt; erythroblasts &gt; monocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-148\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">148- Which is the correct sequence of lymphopoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stem cell &gt; myeloblast &gt; lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Stem cell &gt; common lymphoid progenitor &gt; lymphoblasts &gt; pro-lymphocytes &gt; lymphocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Stem cell &gt; monoblast &gt; lymphocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Stem cell &gt; CFU &gt; megakaryocyte &gt; lymphocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-149\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">149- During which trimester does the liver become the main site of prenatal hemopoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 1st trimester<\/li><li data-o=\"b\" tabindex=\"0\">b- 2nd trimester<\/li><li data-o=\"c\" tabindex=\"0\">c- 3rd trimester<\/li><li data-o=\"d\" tabindex=\"0\">d- After birth<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2z-150\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">150- Which progenitor is involved in lymphopoiesis?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Common myeloid progenitor<\/li><li data-o=\"b\" tabindex=\"0\">b- Common lymphoid progenitor<\/li><li data-o=\"c\" tabindex=\"0\">c- Megakaryoblast<\/li><li data-o=\"d\" tabindex=\"0\">d- CFU only<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_d11\"><h3>Department MCQs <small>— أسئلة القسم · 36 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_d11\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2d-001\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">1- The RBCs in adults:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are flexible biconcave discs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have a life span of about 3 weeks.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are nucleated cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain myoglobin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-002\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">2- Light microscopic features of red blood corpuscles Include:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Variation in size.<\/li><li data-o=\"b\" tabindex=\"0\">b- Acidophilic appearance.<\/li><li data-o=\"c\" tabindex=\"0\">c- The presence of nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Dark central area.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-003\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">3- A characteristic ultrastructural feature of RBCs Includes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Well-developed rER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Heterochromatic nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cell membrane as the only organelle.<\/li><li data-o=\"d\" tabindex=\"0\">d- Euchromatic nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-004\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">4- At emergency unit of hospital, a patient was complaining of abdominal pain &amp; fever. The doctor was confused between acute appendicitis &amp; typhoid fever. What is the most helpful diagnostic test?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Total Leucocytic Count.<\/li><li data-o=\"b\" tabindex=\"0\">b- Differential Leucocytic count for Neutrophils.<\/li><li data-o=\"c\" tabindex=\"0\">c- Differential Leucocytic count for Lymphocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Measurement of bleeding time.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-005\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">5- Hereditary spherocytosis of RBCs is caused by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Abnormal type of hemoglobin (HbS).<\/li><li data-o=\"b\" tabindex=\"0\">b- Deficiency of HB reductase enzyme.<\/li><li data-o=\"c\" tabindex=\"0\">c- Deficiency of carbonic anhydrase enzyme.<\/li><li data-o=\"d\" tabindex=\"0\">d- Primary defect in spectrin gene expression.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- Changes in the osmotic pressure of RBCs might result in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cell ghost appearance in hypotonic solution.<\/li><li data-o=\"b\" tabindex=\"0\">b- Crenation in hypotonic solution.<\/li><li data-o=\"c\" tabindex=\"0\">c- Rouleaux appearance in hypertonic solution.<\/li><li data-o=\"d\" tabindex=\"0\">d- Spherocytes in hypertonic solution.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-007\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">7- In autoimmune diseases as AIDS, markedly destroyed blood cell is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- B lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- T helper.<\/li><li data-o=\"c\" tabindex=\"0\">c- T killer.<\/li><li data-o=\"d\" tabindex=\"0\">d- T memory.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- Aplastic anaemia is caused by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Deficiency of iron &amp; vitamin B12.<\/li><li data-o=\"b\" tabindex=\"0\">b- Bone marrow depression by x-ray.<\/li><li data-o=\"c\" tabindex=\"0\">c- Acute blood loss.<\/li><li data-o=\"d\" tabindex=\"0\">d- Spherocytosis or favism.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-009\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">9- General characters of WBCs Include:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Absence of nuclei and organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Origin is bone marrow &amp; lymphatic tissues.<\/li><li data-o=\"c\" tabindex=\"0\">c- Osmotically fragile.<\/li><li data-o=\"d\" tabindex=\"0\">d- Function only inside blood stream.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- Differential Leucocytic Count:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ranges from 400 - 1100/ mm?.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is the total number of 5 types of WBCs.<\/li><li data-o=\"c\" tabindex=\"0\">c- Is the % of each type of leucocyte to the total number.<\/li><li data-o=\"d\" tabindex=\"0\">d- Is performed using the haemocytometer.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-011\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">11- Cells are required for Initiation of cellular &amp; humoral immunity:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- T Helper &amp; Macrophage.<\/li><li data-o=\"b\" tabindex=\"0\">b- T suppressor &amp; Monocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- B lymphocyte &amp; Macrophage.<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasmablast &amp; Monocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- Eosinophils are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Spherical Nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Nucleus with Barr body.<\/li><li data-o=\"c\" tabindex=\"0\">c- Coarse basophilic granules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Granules with dense core.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-013\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">13- Neutrophilia is seen in blood picture of patients having:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Whooping cough.<\/li><li data-o=\"b\" tabindex=\"0\">b- Acute pyogenic infections.<\/li><li data-o=\"c\" tabindex=\"0\">c- Tuberculosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- Liver cirrhosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-014\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">14- A 7 year-old-school boy has a blood report with an eosinophil count 9%. He is not suffering from allergic problems. What would the doctor probably advise his parents to perform:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Urine analysis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stool analysis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Estimation of his bleeding time.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sensitivity tests to different allergens.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-015\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">15- Basophils are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Smaller diameter than RBCs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Presence of azurophilic granules only.<\/li><li data-o=\"c\" tabindex=\"0\">c- S-shaped nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Acidophilic coarse granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-016\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">16- ONE is a function of Basophils:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Release of trephone substance.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secretion of histamine and heparin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Production of neutrophil chemotactic factor<\/li><li data-o=\"d\" tabindex=\"0\">d- Production of histaminase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-017\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">17- Degranulation of Basophils in hyperallergic individuals results in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Generalized vasodilatation.<\/li><li data-o=\"b\" tabindex=\"0\">b- Marked increase in blood pressure.<\/li><li data-o=\"c\" tabindex=\"0\">c- Marked increase in blood volume.<\/li><li data-o=\"d\" tabindex=\"0\">d- Bronchial smooth muscle relaxation<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Which of the following cell types migrates first from blood into connective tissue, during the early stages of an inflammatory response?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophil.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-019\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">19- Which of the following white blood cell is most similar to a mast cell and is the least common of the circulating leucocytes?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Eosinophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophil.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-020\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">20- Which of these blood elements can differentiate into Plasma cells?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Monocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- B Lymphocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- T Lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-021\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">21- Only ONE statement is correct about small lymphocytes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Abundant cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Indented nucleus with nucleolus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed organelles.<\/li><li data-o=\"d\" tabindex=\"0\">d- The majority of circulating lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-022\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">22- The nucleus of large lymphocytes is characterized by being .........<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Kidney-shaped.<\/li><li data-o=\"b\" tabindex=\"0\">b- Large and indented.<\/li><li data-o=\"c\" tabindex=\"0\">c- With no obvious nucleolus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Heterochromatic.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-023\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">23- The regulatory T lymphocytes suppress:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- perforin production<\/li><li data-o=\"b\" tabindex=\"0\">b- antibody production.<\/li><li data-o=\"c\" tabindex=\"0\">c- excess immunity.<\/li><li data-o=\"d\" tabindex=\"0\">d- Cytotoxicity.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-024\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">24- Cytotoxic T Lymphocytes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have receptors of CD4 type.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are the main cells in humoral Immunity.<\/li><li data-o=\"c\" tabindex=\"0\">c- Memory cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Contribute to killing neoplastic cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-025\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">25- T and B lymphocytes could be differentiated based ON .........<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Morphological differences.<\/li><li data-o=\"b\" tabindex=\"0\">b- Surface receptors.<\/li><li data-o=\"c\" tabindex=\"0\">c- Electron microscopic appearance.<\/li><li data-o=\"d\" tabindex=\"0\">d- Light microscopic features.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-026\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">26- The most prominent cytoplasmic organelles in monocytes are:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus and lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glycogen granules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mitochondria.<\/li><li data-o=\"d\" tabindex=\"0\">d- sER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-027\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">27- E/M picture of blood platelets shows:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Open canalicular system in central zone.<\/li><li data-o=\"b\" tabindex=\"0\">b- Bundles of microfilaments in central zone.<\/li><li data-o=\"c\" tabindex=\"0\">c- Central granulomere of microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Hyalomere of microtubules in peripheral zone.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-028\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">28- Inactive yellow bone marrow in adults occupies ...<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Diaphysis of long bones.<\/li><li data-o=\"b\" tabindex=\"0\">b- Epiphysis of long bones.<\/li><li data-o=\"c\" tabindex=\"0\">c- Flat bones as sternum<\/li><li data-o=\"d\" tabindex=\"0\">d- Irregular bones as vertebrae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-029\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">29- The largest cell in bone marrow is the:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Erythroblast.<\/li><li data-o=\"c\" tabindex=\"0\">c- Myelocyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- Metamyelocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-030\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">30- The stroma of myeloid tissue is formed of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cells and blood platelets.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cells and lymphocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular cells, fat cells and fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblasts and developing blood cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-031\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">31- The bone marrow component which can be transplanted into patients suffering from leukemia is ..........:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Blood sinusoids.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Haemopoietic stem cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-032\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">32- At emergency unit of Kasr Al Aini hospital, a patient was complaining of abdominal pain and fever. Examination and investigations revealed he had acute appendicitis. The following blood cell migrates first, most rapidly from blood to C.T. during such inflammatory response:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Monocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-033\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">33- A 50-year-old patient suffered from generalized weight loss, repeated Infections and enlarged lymph nodes. Blood smear revealed very high leucocytic count, abnormal forms of leucocytes with many immature cells. This is diagnostic of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bronchial asthma<\/li><li data-o=\"b\" tabindex=\"0\">b- Typhoid fever<\/li><li data-o=\"c\" tabindex=\"0\">c- Leukemia<\/li><li data-o=\"d\" tabindex=\"0\">d- Drug hypersensitivity<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-034\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">34- Routine investigations done for a newly born baby girl revealed she had sickle cell disease with abnormal crescent-shaped RBCs. The underlying cause of this abnormality is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Abnormal type of hemoglobin (HbS)<\/li><li data-o=\"b\" tabindex=\"0\">b- Primary defect in actin gene expression<\/li><li data-o=\"c\" tabindex=\"0\">c- Deficiency. of carbonic anhydrase enzyme<\/li><li data-o=\"d\" tabindex=\"0\">d- Primary defect in spectrin gene expression<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-035\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">35- A 7-year-old girl received a penicillin Injection for treatment of an infectious disease. Fifteen minutes after the injection, she suffered from difficulty in breathing, edema and sudden drop in blood pressure (anaphylactic shock). The cell responsible for this condition is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblast<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2d-036\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">36- A patient was subjected to severe bleeding during a surgical operation, which blood cell is expected to have a high count in his blood report:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Erythrocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Platelets.<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticulocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h2_e12\"><h3>Exam MCQs <small>— أسئلة الامتحانات · 37 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h2_e12\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c2e-001\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">1- Macrophages can be stained with:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Trypan blue.<\/li><li data-o=\"b\" tabindex=\"0\">b- Toluidine blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Silver.<\/li><li data-o=\"d\" tabindex=\"0\">d- Orcein<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-002\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">2- Fibroblasts have:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Many sER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Many free ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Many lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Many rER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-003\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">3- Mast cells can be metachromatically stained with:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Indian ink.<\/li><li data-o=\"b\" tabindex=\"0\">b- Sudan III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Toluidine blue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Trypan blue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-004\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">4- Unilocular adipocytes:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have spherical mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Generate heat by thermogenin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have rounded central nucleus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Secrete leptin hormone.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- Plasma cells:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Originate from B-lymphocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have acidophilic cytoplasm.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have few rER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain many secretory granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- Regarding RBCs adaptation to perform their function, They are:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Containing carbonic anhydrase enzyme.<\/li><li data-o=\"b\" tabindex=\"0\">b- Rich in mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Having a central granular part.<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in Cat and serotonin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-007\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">7- Lambda granules of blood platelets contain:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- ATP and ADP.<\/li><li data-o=\"c\" tabindex=\"0\">c- Growth factors.<\/li><li data-o=\"d\" tabindex=\"0\">d- clotting factors.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-008\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">8- The blood count of a patient suffering from acute tonsillitis shows increase in the percentage of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophils.<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophils.<\/li><li data-o=\"d\" tabindex=\"0\">d- Neutrophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-009\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">9- Cytoplasm with frosted glass appearance is a feature of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Eosinophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophils.<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-010\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">10- Eosinophils are characterized by:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have horse-shoe shaped nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secrete histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Increase in liver cirrhosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- Have non- specific granules only.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-011\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">11- Regarding basophils, they:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Constitute 3-8% of circulating leucocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Increase in acute pyogenic infection.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have kidney shaped nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are rich in metachromatically stained granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-012\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">12- The surface marker/ receptor that identifies NK cell is:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- CD16.<\/li><li data-o=\"b\" tabindex=\"0\">b- CD4.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ig M.<\/li><li data-o=\"d\" tabindex=\"0\">d- Ig D.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-013\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">13- Megakaryocyte is characterized by:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Found in peripheral blood.<\/li><li data-o=\"b\" tabindex=\"0\">b- Acidophilic cytoplasm.<\/li><li data-o=\"c\" tabindex=\"0\">c- Form RBCs.<\/li><li data-o=\"d\" tabindex=\"0\">d- Nucleus is single and multilobed.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-014\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">14- Which leucocyte is responsible for Cell mediated immunity?<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- B- lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- T-lymphocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophils.<\/li><li data-o=\"d\" tabindex=\"0\">d- Monocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-015\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">15- The following cell stained metachromatically with toluidine blue is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophage.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pericyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-016\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">16- Large cell with single multilobed dark nucleus &amp; basophilic cytoplasm is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Megakaryocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-017\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">17- By E.M. RBCs are characterized by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Nucleated biconcave discs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Rich in ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Having many mitochondria.<\/li><li data-o=\"d\" tabindex=\"0\">d- Electron-dense homogenous hemoglobin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Horse shoe nucleus is a feature of:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Monocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophil.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-019\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">19- Which of the following is a non-granular leucocyte:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neutrophil.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-020\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">20- Neutrophils are characterized by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secrete bactericidal phagocytin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have non segmented nuclei.<\/li><li data-o=\"c\" tabindex=\"0\">c- Decrease in number during treatment with cortisone.<\/li><li data-o=\"d\" tabindex=\"0\">d- They have azurophil granules only.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-021\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">21- The white blood cells with histamine &amp; heparin containing granules are<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophils.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lymphocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Eosinophils.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophils.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-022\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">22- Granulomere of blood platelets contains:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lambda granules<\/li><li data-o=\"b\" tabindex=\"0\">b- Microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Actin microfilaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Membranous channels.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-023\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">23- Regarding T-lymphocytes, the CD8 T-cells are T-cells:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Helper.<\/li><li data-o=\"b\" tabindex=\"0\">b- Memory.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cytotoxic.<\/li><li data-o=\"d\" tabindex=\"0\">d- Regulatory.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-024\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">24- The can be stained by brilliant cresyl blue stain:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Monocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neutrophil.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticulocytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basophil.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-025\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">25- The normal shape of RBCs is kept by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycocalyx.<\/li><li data-o=\"b\" tabindex=\"0\">b- Actin and spectrin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lipoproteins of plasmalemma.<\/li><li data-o=\"d\" tabindex=\"0\">d- Haemoglobin S.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-026\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">26- Metachromatic stain is........:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Toluidine blue<\/li><li data-o=\"b\" tabindex=\"0\">b- Trypan blue<\/li><li data-o=\"c\" tabindex=\"0\">c- Indian ink<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-027\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">27- Reticulocytes are stained by.......... Stain:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver<\/li><li data-o=\"b\" tabindex=\"0\">b- Brilliant cresyl blue<\/li><li data-o=\"c\" tabindex=\"0\">c- Leishman<\/li><li data-o=\"d\" tabindex=\"0\">d- Janus green<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-028\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">28- Regarding the RBCs:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basophilic by L.M.<\/li><li data-o=\"b\" tabindex=\"0\">b- Show crenation in hypotonic solution<\/li><li data-o=\"c\" tabindex=\"0\">c- Contain carbonic anhydrase enzyme<\/li><li data-o=\"d\" tabindex=\"0\">d- single nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-029\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">29- Lysosomes in blood platelets are present in:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lambda granules<\/li><li data-o=\"b\" tabindex=\"0\">b- Alpha granule<\/li><li data-o=\"c\" tabindex=\"0\">c- Delta granule<\/li><li data-o=\"d\" tabindex=\"0\">d- canalicular system<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-030\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">30- The cell of origin of platelets is characterized by:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Multinucleated<\/li><li data-o=\"b\" tabindex=\"0\">b- Acidophilic<\/li><li data-o=\"c\" tabindex=\"0\">c- Seen in blood film<\/li><li data-o=\"d\" tabindex=\"0\">d- Size 50-70 µm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-031\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">31- The blood cells with receptor for IgE are:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basophils<\/li><li data-o=\"b\" tabindex=\"0\">b- RBCs<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophils<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-032\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">32- Oval specific granules with electron dense core is seen in:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neutrophil<\/li><li data-o=\"b\" tabindex=\"0\">b- Monocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Basophil<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosinophil<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-033\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">33- Neutrophils:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Decrease in parasitic disease<\/li><li data-o=\"b\" tabindex=\"0\">b- Terminate allergic reaction<\/li><li data-o=\"c\" tabindex=\"0\">c- Increase in pyogenic infections<\/li><li data-o=\"d\" tabindex=\"0\">d- Responsible for cell mediated immunity<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-034\" data-k=\"a\" data-bk=\"c\" data-fx=\"نسبة الخلايا غير الناضجة المكوّنة للكريات البيضاء إلى الخلايا غير الناضجة المكوّنة للكريات الحمراء في نخاع العظم هي 5:1، كما في الملزمة (السؤال 127 من أسئلة د. زهرة).\"><p class=\"qt\" dir=\"ltr\">34- The ratio between immature WBCs to immature RBCs in bone marrow is:<span class=\"gtag\" dir=\"ltr\">198<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- 5:1<\/li><li data-o=\"b\" tabindex=\"0\">b- 1:5<\/li><li data-o=\"c\" tabindex=\"0\">c- 3:1<\/li><li data-o=\"d\" tabindex=\"0\">d- 1:10<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-035\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">35- The perforins are secreted from the following type of T-lymphocyte:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Regulatory cell<\/li><li data-o=\"b\" tabindex=\"0\">b- CD8 T-cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Memory cell<\/li><li data-o=\"d\" tabindex=\"0\">d- CD4+ T-cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-036\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">36- Natural killer cells are characterized by:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mature in thymus<\/li><li data-o=\"b\" tabindex=\"0\">b- CD16 cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Humoral immunity<\/li><li data-o=\"d\" tabindex=\"0\">d- Memory ce<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c2e-037\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">37- A condition with decreased number of WBCs below 4000/mm3 is called:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Leukemia<\/li><li data-o=\"b\" tabindex=\"0\">b- Leukopenia<\/li><li data-o=\"c\" tabindex=\"0\">c- Anemia<\/li><li data-o=\"d\" tabindex=\"0\">d- Pancytopenia<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><\/div><div class=\"gpart\" data-part=\"3\" data-ch=\"c3\"><h2 dir=\"ltr\">Chapter 3 · Connective Tissue <small>— النسيج الضام · 274 سؤال · <bdi dir=\"ltr\">Dr. Zahra MCQs<\/bdi><\/small><\/h2><section class=\"tsec gsec\" data-g=\"h3_t01\"><h3>Connective tissue characters <small>— 9 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t01\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-001\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">1- Connective tissue is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mesodermal in origin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ectodermal in origin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endodermal in origin.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-002\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">2- The most correct statement:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- C.T is formed of free cells, fixed cells and different fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- C.T is formed of cells, fibers and ground substance.<\/li><li data-o=\"c\" tabindex=\"0\">c- C.T is formed of cells, and ground substance<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- The followings are characters of C.T EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is mesodermal in origin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of arranged one type of cells resting on basement membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of cells, fibers and ground substance.<\/li><li data-o=\"d\" tabindex=\"0\">d- It is classified into proper and specialized C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-004\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">4- C.T mesenchymal cells have the following characters EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are stem cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- They are small branched cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- They can differentiate into other types of C.T cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- They have numerous organelles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- C.T is classified into C.T proper and specific C.T according to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The matrix.<\/li><li data-o=\"b\" tabindex=\"0\">b- The fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- The cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-006\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">6- Ground substance of the C.T is composed of the followings EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Glycosaminoglycan.<\/li><li data-o=\"b\" tabindex=\"0\">b- Proteoglycan.<\/li><li data-o=\"c\" tabindex=\"0\">c- Glycoproteins.<\/li><li data-o=\"d\" tabindex=\"0\">d- Phospholipids.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-007\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">7- The connective tissue is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- vascular tissue<\/li><li data-o=\"b\" tabindex=\"0\">b- contains widely separated cells<\/li><li data-o=\"c\" tabindex=\"0\">c- contains abundant intercellular substance<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- The origin of connective tissue is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- ectoderm.<\/li><li data-o=\"b\" tabindex=\"0\">b- mesoderm.<\/li><li data-o=\"c\" tabindex=\"0\">c- endoderm.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-009\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">9- The following is a character of connective tissue:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of crowded cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Mesodermal in origin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Non-vascular.<\/li><li data-o=\"d\" tabindex=\"0\">d- Tightly joined cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t02\"><h3>UMCs &amp; Pericytes <small>— 8 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t02\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- Which one of the connective tissue cell can differentiate into endothelial cell?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Macrophage<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Mast cell<\/li><li data-o=\"e\" tabindex=\"0\">e- Fibroblast<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-011\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">11- Pericytes of the connective tissue arises from:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- reticular cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- fibroblasts.<\/li><li data-o=\"c\" tabindex=\"0\">c- undifferentiated mesenchymal cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- macrophages.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- Under certain conditions, Pericytes of the connective tissue can differentiate into:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- endothelial cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- fibroblasts.<\/li><li data-o=\"c\" tabindex=\"0\">c- smooth muscle cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-013\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">13- All of the following cells synthesize collagen EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- chondroblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- odontoblasts.<\/li><li data-o=\"c\" tabindex=\"0\">c- osteoblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- pericytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-014\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">14- Which cell is present around blood capillaries:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- pericytes.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-015\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">15- By EM, the pericytes contain a network of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- actin.<\/li><li data-o=\"b\" tabindex=\"0\">b- myosin.<\/li><li data-o=\"c\" tabindex=\"0\">c- microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a &amp; b.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-016\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">16- The C.T. cell that gives rise to fibroblast is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- pericyte<\/li><li data-o=\"b\" tabindex=\"0\">b- mast cell<\/li><li data-o=\"c\" tabindex=\"0\">c- fat cell<\/li><li data-o=\"d\" tabindex=\"0\">d- reticular cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-017\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">17- After injury of adult C.T., the following cells differentiate for C.T. repair:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells &amp; Fibroblasts<\/li><li data-o=\"b\" tabindex=\"0\">b- Pericytes &amp; Fibroblasts<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular cells &amp; Histiocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular cells &amp; plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t03\"><h3>Fibroblasts <small>— 15 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t03\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-018\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">18- Fibroblast in the histology is a good example for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Active cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Free C.T. cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Steroid secreting cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Undifferentiated stem cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-019\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">19- Fibroblast has:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Acidophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pale nucleus, prominent nucleolus and basophilic cytoplasm.<\/li><li data-o=\"c\" tabindex=\"0\">c- Dark nucleus and basophilic cytoplasm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-020\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">20- Fibroblast has the following functions EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Synthesis of C.T fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Synthesis of ground substances.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretion of collagen.<\/li><li data-o=\"d\" tabindex=\"0\">d- Secretion of heparin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-021\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">21- Which statement is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibrocyte is much large in size than fibroblast.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibrocyte has more basophilic cytoplasm than fibroblast.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibrocyte is quiescent state of fibroblast.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibrocyte has more abundant RER than fibroblast.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-022\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">22- All the followings are concerned to the function of the fibroblast EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion of elastin and fibrillin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secretion of collagen.<\/li><li data-o=\"c\" tabindex=\"0\">c- Repair of injuries.<\/li><li data-o=\"d\" tabindex=\"0\">d- Growth of epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-023\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">23- Collagen fibers are mainly synthesized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-024\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">24- The ground substance of connective tissue is synthesized mainly by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-025\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">25- Fibrocytes are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- having deeply basophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- being spindle shaped with few processes.<\/li><li data-o=\"c\" tabindex=\"0\">c- having well developed golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- being active cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-026\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">26- Most common cell in Connective tissue is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-027\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">27- Fibroblasts have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Few organelles<\/li><li data-o=\"b\" tabindex=\"0\">b- Dark nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed Golgi apparatus<\/li><li data-o=\"d\" tabindex=\"0\">d- Pale basophilic cytoplasm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-028\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">28- Active fibroblasts have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- few organelles<\/li><li data-o=\"b\" tabindex=\"0\">b- Numerous rER<\/li><li data-o=\"c\" tabindex=\"0\">c- Dark nucleus:<\/li><li data-o=\"d\" tabindex=\"0\">d- Acidophilic cytoplasm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-029\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">29- Regarding fibroblast, the following is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Deeply acidophilic cytoplasm<\/li><li data-o=\"b\" tabindex=\"0\">b- Forms C.T. fibers &amp; matrix<\/li><li data-o=\"c\" tabindex=\"0\">c- Rich in sER<\/li><li data-o=\"d\" tabindex=\"0\">d- Has dark nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-030\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">30- Fibroblasts have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Many sER.<\/li><li data-o=\"b\" tabindex=\"0\">b- Many lysosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Many peroxisomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Many rER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-031\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">31- The following C.T. cells are a protein secreting cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat and macrophage cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fat and fibroblast cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Macrophage and plasma cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblast and plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-032\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">32- The type III collagen fibers are secreted by the following cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts, macrophage cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblasts &amp; reticular cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts &amp; mast cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblasts &amp; plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t04\"><h3>Adipose cells <small>— 18 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t04\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-033\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">33- Concerning unilocular adipocytes, they have all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cytochrome pigments.<\/li><li data-o=\"b\" tabindex=\"0\">b- signet ring appearance.<\/li><li data-o=\"c\" tabindex=\"0\">c- single large fat droplet.<\/li><li data-o=\"d\" tabindex=\"0\">d- flat peripheral nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-034\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">34- Adipocytes are of two types:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Free and fixed.<\/li><li data-o=\"b\" tabindex=\"0\">b- Unilocular and multilocular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Primary and secondary.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-035\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">35- Concerning the unilocular adipocyte:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contain large number of lipid droplets.<\/li><li data-o=\"b\" tabindex=\"0\">b- They form brown connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are cells with single large lipid droplet.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are cells with prominent Golgi complex and RER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-036\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">36- Concerning the multilocular adipocyte:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contain large number of lipid droplets.<\/li><li data-o=\"b\" tabindex=\"0\">b- They form white connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are cells with single large lipid droplet.<\/li><li data-o=\"d\" tabindex=\"0\">d- Are cells with prominent Golgi complex and RER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-037\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">37- (Signet ring appearance) Is a descriptive term for the:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cells stained with Sudan III.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fat cells stained with Sudan black.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cells stained with H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fat cells stained with toluidine blue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-038\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">38- Concerning brown fat, the followings are correct EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It shows an extensive vascularity.<\/li><li data-o=\"b\" tabindex=\"0\">b- Contain large single lipid droplet.<\/li><li data-o=\"c\" tabindex=\"0\">c- The cells contain abundant mitochondria<\/li><li data-o=\"d\" tabindex=\"0\">d- It is more extensive in newborns.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-039\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">39- Which types of adipose cells is a characteristic for newborns:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- white.<\/li><li data-o=\"b\" tabindex=\"0\">b- yellow.<\/li><li data-o=\"c\" tabindex=\"0\">c- grey.<\/li><li data-o=\"d\" tabindex=\"0\">d- brown.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-040\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">40- Unilocular fat cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- have peripheral flat nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- have single large fat droplet.<\/li><li data-o=\"c\" tabindex=\"0\">c- have thin rim of cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-041\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">41- Concerning multilocular adipocytes, they have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cytochrome pigments.<\/li><li data-o=\"b\" tabindex=\"0\">b- signet ring appearance.<\/li><li data-o=\"c\" tabindex=\"0\">c- single large fat droplets.<\/li><li data-o=\"d\" tabindex=\"0\">d- flat peripheral nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-042\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">42- ALL those connective tissue cells are branched Except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pericytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- UMCs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-043\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">43- Multilocular fat cell all true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its accumulation form brown fat.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its mitochondria is rich in thermogenin &amp; cytochrome enzymes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its mitochondria is rich in ATP synthetase enzyme.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its nucleus is spherical &amp; central or eccentric in position.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-044\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">44- Fat cells can be stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Metachromatic stain<\/li><li data-o=\"b\" tabindex=\"0\">b- Histochemical stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Trypan blue stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-045\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">45- The pigment which is responsible for the brown color of brown adipose tissue is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- melanin<\/li><li data-o=\"b\" tabindex=\"0\">b- cytochrome<\/li><li data-o=\"c\" tabindex=\"0\">c- hemosiderin<\/li><li data-o=\"d\" tabindex=\"0\">d- hemoglobin:<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-046\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">46- Connective tissue cell that shows a signet ring appearance with H&amp;E stain is<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Multilocular fat cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Unilocular fat cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Lymphocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblast<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-047\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">47- Thermogenesis is a function of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibrocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histiocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Multilocular fat cell<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-048\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">48- A characteristic feature of multilocular adipocyte is::<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Has flattened peripheral nucleus<\/li><li data-o=\"b\" tabindex=\"0\">b- Surrounded by high vascularity<\/li><li data-o=\"c\" tabindex=\"0\">c- Most abundant in white adipose C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Function is heat insulation<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-049\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">49- Unilocular adipocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have spherical mitochondria<\/li><li data-o=\"b\" tabindex=\"0\">b- Have rounded central nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Generate heat by thermogenin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Secrete leptin hormone.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-050\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">50- The following is a character of multilocular adipocyte:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Has membrane-bound granule filling the cytoplasm<\/li><li data-o=\"b\" tabindex=\"0\">b- Has flattened peripheral nucleus<\/li><li data-o=\"c\" tabindex=\"0\">c- Function is heat generation<\/li><li data-o=\"d\" tabindex=\"0\">d- Most abundant in white adipose C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t05\"><h3>Macrophages <small>— 21 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t05\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-051\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">51- Which of the following cells can be stained with vital stains:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Macrophage.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibrocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-052\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">52- EM picture of macrophage shows the followings EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Prominent Golgi complex.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pseudopodia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Many lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- prominent rER.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-053\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">53- EM picture of macrophage shows the followings EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Prominent Golgi complex.<\/li><li data-o=\"b\" tabindex=\"0\">b- Few RER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Many lysosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- No pseudopodia<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-054\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">54- The followings are the functions of phagocytic cells EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Phagocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Antigen presenting cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen secretion.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-055\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">55- Macrophages originate from...?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Chondroblast.<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Blood monocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-056\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">56- Which one of the following originates from the blood monocytes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-057\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">57- This cell can be vitally stained:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-058\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">58- Which one of the following C.T cells is typically an antigen presenting cell:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-059\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">59- The main ultrastructure of macrophage is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- lysosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-060\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">60- Histiocytes (Macrophages) have:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- darkly basophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- euchromatic nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- pseudopodia.<\/li><li data-o=\"d\" tabindex=\"0\">d- few lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-061\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">61- The main function of histiocyte (macrophage) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- secretion of antibodies.<\/li><li data-o=\"b\" tabindex=\"0\">b- secretion of histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- phagocytosis.<\/li><li data-o=\"d\" tabindex=\"0\">d- exocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-062\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">62- Staining of the macrophage with trypan blue is an example of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Vital stain.<\/li><li data-o=\"b\" tabindex=\"0\">b- Supravital stain.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fluorescent stain.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histochemical stain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-063\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">63- About macrophages all are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are antigen presenting cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- It originates from B lymphocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stained with vital staining using trypan blue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stained histochemically using acid phosphatase technique.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-064\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">64- Macrophages can be stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Metachromatic stain<\/li><li data-o=\"b\" tabindex=\"0\">b- Histochemical stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Trypan blue stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-065\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">65- The origin of macrophages is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibrocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Pericytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- B lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-066\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">66- Kidney shaped nucleus is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-067\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">67- Connective tissue cell that can be stained vitally with the India ink stain is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Macrophage<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-068\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">68- Histiocytes (macrophage) originate from<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- B-lymphocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Monocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericytes<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-069\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">69- Vital stain is used to demonstrate:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblast<\/li><li data-o=\"c\" tabindex=\"0\">c- Multilocular fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histiocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-070\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">70- The cytoplasm of macrophage is rich in the following organelles:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Golgi apparatus &amp; sER<\/li><li data-o=\"b\" tabindex=\"0\">b- Free ribosome &amp; lysosome<\/li><li data-o=\"c\" tabindex=\"0\">c- Golgi apparatus &amp; lysosome<\/li><li data-o=\"d\" tabindex=\"0\">d- Mitochondria &amp; sER<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-071\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">71- Macrophages can be stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Trypan blue<\/li><li data-o=\"b\" tabindex=\"0\">b- Toluidine blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Silver<\/li><li data-o=\"d\" tabindex=\"0\">d- Orcein<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t06\"><h3>Reticular cells <small>— 4 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t06\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-072\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">72- Concerning the reticular cells, the followings are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present mainly in the stroma of the organs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secrete collagen type III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secrete collagen type II.<\/li><li data-o=\"d\" tabindex=\"0\">d- Has a supportive function.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-073\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">73- Concerning reticular cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- they are rounded cells with no processes.<\/li><li data-o=\"b\" tabindex=\"0\">b- they are antibody forming cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- they have pale basophilic cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- they have dark heterochromatic nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-074\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">74- All of the following concerning reticular cells is true except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Produce collagen type III<\/li><li data-o=\"b\" tabindex=\"0\">b- Produce collagen type II<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in stroma of organs<\/li><li data-o=\"d\" tabindex=\"0\">d- Have supporting function<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-075\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">75- One of the following C.T. cells is an antigen presenting cell:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- adipose cell<\/li><li data-o=\"d\" tabindex=\"0\">d- fibrocyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t07\"><h3>Mast cells <small>— 18 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t07\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-076\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">76- Mast cells synthesize and secrete:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histamine<\/li><li data-o=\"c\" tabindex=\"0\">c- Serotonin.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-077\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">77- After staining the C.T with toluidine blue the cells which have magenta granules are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Phagocytic cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Endothelial cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-078\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">78- Mast cells are abundant in the C.T of the:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Skeletal muscle.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cardiac muscle.<\/li><li data-o=\"c\" tabindex=\"0\">c- Respiratory and digestive system.<\/li><li data-o=\"d\" tabindex=\"0\">d- Eye.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-079\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">79- The cell membrane of the mast cells have specific receptors for:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- IgM.<\/li><li data-o=\"b\" tabindex=\"0\">b- IgG.<\/li><li data-o=\"c\" tabindex=\"0\">c- IgA.<\/li><li data-o=\"d\" tabindex=\"0\">d- IgE.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-080\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">80- Which of the following cells is the precursor of histamine &amp; heparin.?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-081\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">81- Which one of the following can be stained metachromatically by toluidine blue:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-082\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">82- Mast cells secrete:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin<\/li><li data-o=\"b\" tabindex=\"0\">b- Histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Antibodies.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-083\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">83- Which one of the following C.T cells has receptors for immunoglobulin E (IgE ):<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-084\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">84- Metachromatic granules are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- plasma cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- fat cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- pigment cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-085\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">85- About mast cell all are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its granules are stained basophilic with H&amp; E.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its surface has receptors for IgE.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its surface has receptors for IgA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its granules are stained metachromatically with toluidine blue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-086\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">86- Mast cells synthesize and secrete all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Serotonin.<\/li><li data-o=\"d\" tabindex=\"0\">d- histaminase.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-087\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">87- Mast cells can be stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Metachromatic stain<\/li><li data-o=\"b\" tabindex=\"0\">b- Histochemical stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Trypan blue stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-088\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">88- Basophilic granules are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-089\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">89- Connective tissue cell that can be metachromatically stained is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Macrophage<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-090\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">90- After receiving Penicillin injection, a patient suffered from circulatory shock, the allergic reaction is probably due to secretion of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin by plasma cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Antibodies by plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Histamine by mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Growth factors by fibroblasts<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-091\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">91- Mast cells can be metachromatically stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Indian ink.<\/li><li data-o=\"b\" tabindex=\"0\">b- Toluidine blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Trypan blue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-092\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">92- The following C.T. cell can be stained with metachromatic stain:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophage cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Mast cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-093\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">93- After receiving Penicillin injection, a patient suffered from allergic reaction which is probably due to secretion of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Growth factors by fibroblasts<\/li><li data-o=\"b\" tabindex=\"0\">b- Lipid by adipocytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Antibodies by plasma cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Histamine by mast cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t08\"><h3>Plasma cells <small>— 20 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t08\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-094\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">94- Plasma cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are branched cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have cart wheel nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have electron dense granules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Can be stained by toluidine blue.<\/li><li data-o=\"e\" tabindex=\"0\">e- Have receptors for immunoglobulin E.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-095\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">95- Russell bodies are spherical inclusion present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fat cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Phagocytic cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Endothelial cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-096\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">96- Negative Golgi image is a microscopic future of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Pancreatic cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-097\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">97- Plasma cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Differentiate from UMC.<\/li><li data-o=\"b\" tabindex=\"0\">b- Differentiate from B-lymphocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Differentiate from T-lymphocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-098\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">98- Intense basophilic cytoplasm in the plasma cell is referred to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Well-developed RER and abundance ribosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Few mitochondria.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretory granules.<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrioles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-099\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">99- Clock face nucleus is discretion for the nucleus of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- T Lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- B Lymphocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-100\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">100- Function of plasma cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Differentiate to B-lymphocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Secretion of the antibodies.<\/li><li data-o=\"c\" tabindex=\"0\">c- Phagocytosis of antigens.<\/li><li data-o=\"d\" tabindex=\"0\">d- Secretion of histamine for vasodilatation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-101\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">101- All of the following is branched Connective tissue cells EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblasts.<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pigment cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-102\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">102- Plasma cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have a cartwheel nucleus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed by B lymphocytes activated by antigen.<\/li><li data-o=\"c\" tabindex=\"0\">c- Found in C.T &amp; lymphatic organs.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-103\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">103- The cell derived from B lymphocytes is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblast.<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-104\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">104- Negative Golgi image is seen in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-105\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">105- Plasma cells secrete:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Antibodies.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-106\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">106- Which one of the following C.T cells, its nucleus has a clock face appearance:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mast cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- plasma cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-107\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">107- The cell responsible for production of antibodies is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-108\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">108- About plasma cell all are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It&#x27;s the antibody forming cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- It can divide.<\/li><li data-o=\"c\" tabindex=\"0\">c- Develops from activated B lymphocyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- Characterized by cart wheel shaped nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-109\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">109- The origin of plasma cells is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibrocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Pericytes<\/li><li data-o=\"c\" tabindex=\"0\">c- Monocytes<\/li><li data-o=\"d\" tabindex=\"0\">d- B lymphocytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-110\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">110- Cartwheel nucleus is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-111\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">111- The plasma cell is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Surface IgE receptors<\/li><li data-o=\"b\" tabindex=\"0\">b- Deep acidophilic cytoplasm.<\/li><li data-o=\"c\" tabindex=\"0\">c- Eccentric clock face nucleus<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in sER &amp; lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-112\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">112- The plasma cell is responsible for the following function:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Antibody production<\/li><li data-o=\"b\" tabindex=\"0\">b- secretion of heparin<\/li><li data-o=\"c\" tabindex=\"0\">c- Phagocytosis<\/li><li data-o=\"d\" tabindex=\"0\">d- Heat generation<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-113\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">113- Plasma cells:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Originate from B-lymphocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have few rER.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have acidophilic cytoplasm<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain many secretory granules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t09\"><h3>Collagen fibers <small>— 25 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t09\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-114\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">114- By Mallory stain, Collagen fibers are stained:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pink<\/li><li data-o=\"b\" tabindex=\"0\">b- blue<\/li><li data-o=\"c\" tabindex=\"0\">c- brown<\/li><li data-o=\"d\" tabindex=\"0\">d- red<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-115\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">115- Collagen fibers have the following characters EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Thick, unbranched and aggregate to form bundles<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Rigid to provide strength<\/li><li data-o=\"d\" tabindex=\"0\">d- Colorless in unstained preparation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-116\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">116- Collagen fibers have the following characters EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White in unstained preparation (when present in great number).<\/li><li data-o=\"b\" tabindex=\"0\">b- Acidophilic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stain pink with H/E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Branched fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-117\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">117- After staining of collagen fibers:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- With H/E it appears pink.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stained green with Van Gieson<\/li><li data-o=\"c\" tabindex=\"0\">c- All of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-118\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">118- The most common type of collagen is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type V.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type VI.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-119\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">119- Reticular fibers are formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type V.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type IV.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-120\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">120- Type II collagen protein is abundant in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hyaline cartilage.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tendons.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-121\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">121- In the basal lamina of the epithelia:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I collagen protein is abundant.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type IV collagen protein is abundant.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type II collagen protein is abundant.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type VII collagen protein is abundant.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-122\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">122- Anchoring fibers which bind dermis to the epidermis is of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type VII.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type IV.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-123\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">123- The following CT fibers can branch EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen fibers type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular fibers<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen fibers type III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-124\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">124- Type I collagen fiber is found abundant in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Hyaline cartilage.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Tendon.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal lamina of the epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-125\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">125- Collagen is secreted by all of the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast.<\/li><li data-o=\"b\" tabindex=\"0\">b- Osteoblast.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Chondroblast.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-126\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">126- The most common type of collagen in the body is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type II.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type IV.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-127\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">127- Reticular fibers are composed of type.........collagen fibrils.<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- II.<\/li><li data-o=\"b\" tabindex=\"0\">b- III.<\/li><li data-o=\"c\" tabindex=\"0\">c- IV.<\/li><li data-o=\"d\" tabindex=\"0\">d- V.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-128\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">128- Type I collagen is present mainly in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- reticular connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- dense collagenous connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- mucoid connective tissue.<\/li><li data-o=\"d\" tabindex=\"0\">d- yellow elastic connective tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-129\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">129- Collagen fibers are formed by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- macrophage.<\/li><li data-o=\"b\" tabindex=\"0\">b- histiocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- chondroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- adipocytes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-130\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">130- Concerning collagen fibers:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- they are wavy branching bundles formed of non-branching fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- they are basophilic.<\/li><li data-o=\"c\" tabindex=\"0\">c- they stain with van Gieson stain.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp;c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-131\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">131- Collagen type III forms:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White fibrous connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stroma of parenchymatous organs.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Placental connective tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-132\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">132- Collagen type 1 is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Capsule of organs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fetal connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Vascular connective tissue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Placenta.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-133\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">133- The following are found in basal lamina EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Laminin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen type II.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen type IV.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-134\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">134- Collagen fibers can be stained with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Best&#x27;s carmine<\/li><li data-o=\"b\" tabindex=\"0\">b- Sudan III<\/li><li data-o=\"c\" tabindex=\"0\">c- Silver<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-135\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">135- Vitamin C deficiency (scurvy) is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Strongly healed wound<\/li><li data-o=\"b\" tabindex=\"0\">b- Keloid formation<\/li><li data-o=\"c\" tabindex=\"0\">c- Defective collagen synthesis<\/li><li data-o=\"d\" tabindex=\"0\">d- Anaphylactic shock<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-136\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">136- Type III collagen fibers are secreted by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericytes &amp; mast cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cells &amp; mast cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblast &amp; reticular cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cells &amp; Fibroblasts<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-137\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">137- Mallory trichrome stain can be used for demonstration of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular fibers<\/li><li data-o=\"b\" tabindex=\"0\">b- actin microfibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen fibers<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophages.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-138\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">138- A young child was suffering from bleeding gums and non-healing wounds. This disease may be due to the defective synthesis of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Extracellular matrix<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular fibers<\/li><li data-o=\"d\" tabindex=\"0\">d- Elastic fibers<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t10\"><h3>Elastic fibers <small>— 10 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t10\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-139\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">139- What are stretchable/flexible CT fibers?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen fibers type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen fibers type III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-140\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">140- What are C.T fibers yellow in fresh state?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen fibers type I.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen fibers type VII.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-141\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">141- Elastic fibers are NOT abundant in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The wall of the large arteries.<\/li><li data-o=\"b\" tabindex=\"0\">b- The lung.<\/li><li data-o=\"c\" tabindex=\"0\">c- Elastic ligaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Tendons<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-142\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">142- Yellow elastic fibers are stained:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- brown by Orcein.<\/li><li data-o=\"b\" tabindex=\"0\">b- yellow by Van Gieson.<\/li><li data-o=\"c\" tabindex=\"0\">c- magenta red by PAS.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-143\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">143- Elastic fibers are formed by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- fibroblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- fat cells<\/li><li data-o=\"d\" tabindex=\"0\">d- mast cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-144\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">144- Elastic fibers are formed by the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts in connective tissue proper.<\/li><li data-o=\"b\" tabindex=\"0\">b- Chondroblasts in elastic cartilage.<\/li><li data-o=\"c\" tabindex=\"0\">c- Smooth muscle cells in arterial blood vessels.<\/li><li data-o=\"d\" tabindex=\"0\">d- Osteoblasts in growing bone.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-145\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">145- The C.T. fibers stained brown with orcein are.............fibers<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen d, B&amp;C<\/li><li data-o=\"d\" tabindex=\"0\">d- B &amp; C<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-146\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">146- Elastic fibers are characterized by being:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Non branching fibers<\/li><li data-o=\"b\" tabindex=\"0\">b- Arranged into bundles<\/li><li data-o=\"c\" tabindex=\"0\">c- Stained brown black with Orcein stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Not demonstrated with H&amp;E<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-147\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">147- Elastic fibers are characterized by being:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Arranged into bundles<\/li><li data-o=\"b\" tabindex=\"0\">b- Stained brown with orcein<\/li><li data-o=\"c\" tabindex=\"0\">c- Found in the stroma of organs<\/li><li data-o=\"d\" tabindex=\"0\">d- Strong and resist stretching<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-148\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">148- Elastic fibers are characterized by being:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Arranged into bundles<\/li><li data-o=\"b\" tabindex=\"0\">b- Stained brown with orcein stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Not demonstrated with H&amp;E<\/li><li data-o=\"d\" tabindex=\"0\">d- Show transverse striations<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t11\"><h3>Reticular fibers <small>— 6 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t11\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-149\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">149- Reticular fibers are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Forming bundles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Thick, non-branching fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of collagen type III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lacking axial periodicity.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-150\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">150- Reticular fibers have the following characters EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stained black with silver (argyrophilic).<\/li><li data-o=\"b\" tabindex=\"0\">b- Positive for PAS.<\/li><li data-o=\"c\" tabindex=\"0\">c- From the stroma of various organs.<\/li><li data-o=\"d\" tabindex=\"0\">d- They are unbranched fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-151\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">151- Regarding the staining, the following are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Elastic fiber stain brown with Orcein.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular fibers stain pink with H&amp;E.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen fibers stain pink with H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mast cells stain purple with toluidine blue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-152\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">152- The stroma of the organs is formed by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- collagen fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- elastic fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- reticular fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- muscle fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-153\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">153- Which type of CT fibers is stained by silver:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- collagen fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- reticular fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- elastic fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-154\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">154- Reticular fibers can be stained brown with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Silver<\/li><li data-o=\"b\" tabindex=\"0\">b- Orcein<\/li><li data-o=\"c\" tabindex=\"0\">c- H&amp;E<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t12\"><h3>Loose areolar CT <small>— 9 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t12\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-155\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">155- Loose areolar C.T is abundant in all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Dermis of the skin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Around blood vessels.<\/li><li data-o=\"c\" tabindex=\"0\">c- Submucosa &amp; mucous membranes<\/li><li data-o=\"d\" tabindex=\"0\">d- brain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-156\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">156- The most widespread C.T is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Loose areolar C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucous C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipose C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-157\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">157- Loose Areolar C.T is abundant in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Dermis of the skin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Wharton&#x27;s jelly.<\/li><li data-o=\"c\" tabindex=\"0\">c- Wall of the elastic arteries.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-158\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">158- Dermis of skin is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- loose areolar connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- dense Irregular connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- dense regular connective tissue.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; b are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-159\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">159- Choose the correct answer about function of loose areolar connective tissue:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Forms stroma of the glands<\/li><li data-o=\"b\" tabindex=\"0\">b- Withstands stress in one direction<\/li><li data-o=\"c\" tabindex=\"0\">c- Heat generation<\/li><li data-o=\"d\" tabindex=\"0\">d- Binds structures together<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-160\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">160- Loose areolar connective tissue is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Poor in blood supply<\/li><li data-o=\"b\" tabindex=\"0\">b- Can accommodate excess fluid<\/li><li data-o=\"c\" tabindex=\"0\">c- Widely distributed in the brain<\/li><li data-o=\"d\" tabindex=\"0\">d- Facilitate spread of infection<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-161\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">161- The following type of connective tissue (C.T.) is widely distributed in body:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Irregular white fibrous CT.<\/li><li data-o=\"b\" tabindex=\"0\">b- Loose areolar C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Yellow elastic C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Regular white fibrous C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-162\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">162- Regarding loose areolar connective tissue, it is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Giving the skin Its shape<\/li><li data-o=\"b\" tabindex=\"0\">b- The commonest type of CT proper.<\/li><li data-o=\"c\" tabindex=\"0\">c- Forming stroma of glands<\/li><li data-o=\"d\" tabindex=\"0\">d- Abundant in brain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-163\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">163- The Type of C.T. contains all types of C.T. cells &amp; fibers is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Loose areolar C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adipose C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- White fibrous C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mucoid C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t13\"><h3>Reticular CT <small>— 5 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t13\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-164\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">164- It forms the stroma of liver, lymph node and spleen:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mucous C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Loose areolar C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Dense regular elastic C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-165\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">165- Reticular connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- capsule of organs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ligamentum nuchae.<\/li><li data-o=\"c\" tabindex=\"0\">c- umbilical cord.<\/li><li data-o=\"d\" tabindex=\"0\">d- stroma of organs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-166\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">166- Reticular fibers can be stained by the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- silver.<\/li><li data-o=\"b\" tabindex=\"0\">b- H&amp;E.<\/li><li data-o=\"c\" tabindex=\"0\">c- PAS.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-167\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">167- The type of connective tissue proper (C.T.) forming stroma of organs is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White adipose C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Loose areolar C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Regular white fibrous C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-168\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">168- The reticular connective tissue can be demonstrated with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Toluidine blue<\/li><li data-o=\"b\" tabindex=\"0\">b- H&amp;E.<\/li><li data-o=\"c\" tabindex=\"0\">c- Silver<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t14\"><h3>Adipose CT <small>— 8 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t14\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-169\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">169- The followings are functions for white adipose C.T EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Act as thermal insulator against heat loss.<\/li><li data-o=\"b\" tabindex=\"0\">b- Act as thermal generator(thermogenesis).<\/li><li data-o=\"c\" tabindex=\"0\">c- Keep some organs (like kidney) in position.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fill the spaces between the tissues.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-170\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">170- White adipose connective tissue:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed mainly of multilocular adipocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed mainly of unilocular adipocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- All of the above.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-171\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">171- In the white adipose tissue, the adipocytes have the following characters EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are unilocular.<\/li><li data-o=\"b\" tabindex=\"0\">b- Contain small multiple lipid droplets.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have abundant sER.<\/li><li data-o=\"d\" tabindex=\"0\">d- Have Few filamentous mitochondria.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-172\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">172- The followings are functions for adipose C.T EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Act as thermal insulator against heat loss.<\/li><li data-o=\"b\" tabindex=\"0\">b- Antibody secretion.<\/li><li data-o=\"c\" tabindex=\"0\">c- Keep some organs (like kidney) in position.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fill the spaces between the tissues.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-173\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">173- Brown adipose connective tissue is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- responsible for fat storage.<\/li><li data-o=\"b\" tabindex=\"0\">b- responsible for heat production.<\/li><li data-o=\"c\" tabindex=\"0\">c- formed of multilocular fat cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-174\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">174- Protects newborn infants by heat production:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White fat. (adipose tissue)<\/li><li data-o=\"b\" tabindex=\"0\">b- Mucoid C.T<\/li><li data-o=\"c\" tabindex=\"0\">c- Brown fat. (adipose tissue).<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-175\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">175- Choose the correct answer about brown adipose connective tissue:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heat generation<\/li><li data-o=\"b\" tabindex=\"0\">b- Not affected by hormones<\/li><li data-o=\"c\" tabindex=\"0\">c- Forms stroma of the glands<\/li><li data-o=\"d\" tabindex=\"0\">d- Withstands stress in one direction<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-176\" data-k=\"d\" data-bk=\"a\" data-fx=\"النسيج الضام الرخو (loose areolar) هو أكثر أنواع النسيج الضام انتشارًا في جسم البالغ.\"><p class=\"qt\" dir=\"ltr\">176- The most common type of C.T. in adult body is<span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Brown adipose.<\/li><li data-o=\"b\" tabindex=\"0\">b- reticular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid.<\/li><li data-o=\"d\" tabindex=\"0\">d- Loose areolar<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t15\"><h3>Mucoid CT <small>— 9 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t15\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-177\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">177- The Pulp of teeth is formed from which type of connective tissue?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mesenchymal.<\/li><li data-o=\"b\" tabindex=\"0\">b- Loose areolar.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipose<\/li><li data-o=\"e\" tabindex=\"0\">e- Elastic.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-178\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">178- Mucoid connective tissue is present in all of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mucous membranes.<\/li><li data-o=\"b\" tabindex=\"0\">b- pulp of teeth.<\/li><li data-o=\"c\" tabindex=\"0\">c- umbilical cord.<\/li><li data-o=\"d\" tabindex=\"0\">d- vitreous of the eye<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-179\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">179- Mucoid connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon<\/li><li data-o=\"b\" tabindex=\"0\">b- Umbilical cord<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Capsule of organs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-180\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">180- Concerning to the mucous CT, the followings are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is jelly like.<\/li><li data-o=\"b\" tabindex=\"0\">b- It is rich in hyaluronic acid.<\/li><li data-o=\"c\" tabindex=\"0\">c- It has a abundant amount of collagen fibers type I.<\/li><li data-o=\"d\" tabindex=\"0\">d- It is the main component of umbilical cord.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-181\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">181- Mucoid connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mucous membranes<\/li><li data-o=\"b\" tabindex=\"0\">b- pulp of teeth.<\/li><li data-o=\"c\" tabindex=\"0\">c- umbilical cord<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-182\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">182- Ground substance is jelly like and formed mainly of hyaluronic acids in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- mucoid connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- yellow elastic connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- loose areolar connective tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-183\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">183- Mucoid connective tissue is found in one of the following sites:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cornea<\/li><li data-o=\"b\" tabindex=\"0\">b- Stroma of organs<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Umbilical cord<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-184\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">184- The mucoid CT. is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Jelly-like excess ground substance<\/li><li data-o=\"b\" tabindex=\"0\">b- High vascularity.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cells predominate.<\/li><li data-o=\"d\" tabindex=\"0\">d- Predominating collagen fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-185\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">185- Mucoid connective tissue (C.T.) is found in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stroma of organs<\/li><li data-o=\"b\" tabindex=\"0\">b- vitreous humour of eye<\/li><li data-o=\"c\" tabindex=\"0\">c- Sclera of the eye<\/li><li data-o=\"d\" tabindex=\"0\">d- Muscle tendon<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t16\"><h3>Dense collagenous CT <small>— 3 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t16\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-186\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">186- Dense irregular collagenous connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon<\/li><li data-o=\"b\" tabindex=\"0\">b- Umbilical cord<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Capsule of organs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-187\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">187- Dense regular collagenous connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon<\/li><li data-o=\"b\" tabindex=\"0\">b- Umbilical cord<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Capsule of organs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-188\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">188- Dense CT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Has more cells and few fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Has more fibers and few cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Has few cells and huge amount of matrix.<\/li><li data-o=\"d\" tabindex=\"0\">d- Has few fibers and huge amount of matrix.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t17\"><h3>Elastic CT <small>— 6 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t17\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-189\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">189- Elastic connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon<\/li><li data-o=\"b\" tabindex=\"0\">b- Umbilical cord<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Capsule of organs<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-190\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">190- Dense Regular C.T is of two types:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen and elastic.<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen and reticular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Elastic and reticular.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-191\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">191- Dense regular elastic C.T is abundant in the following tissues EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Large blood vessels.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ligamentum nuchae.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cornea.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lung C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-192\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">192- Yellow elastic connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- capsule of organs.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ligamentum nuchae.<\/li><li data-o=\"c\" tabindex=\"0\">c- umbilical cord.<\/li><li data-o=\"d\" tabindex=\"0\">d- stroma of organs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-193\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">193- Elastic fibers can be stained brown by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Orcein<\/li><li data-o=\"b\" tabindex=\"0\">b- Van Gieson<\/li><li data-o=\"c\" tabindex=\"0\">c- Mallory<\/li><li data-o=\"d\" tabindex=\"0\">d- Eosin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-194\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">194- Yellow elastic connective tissue is found in one of the following sites:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cornea<\/li><li data-o=\"b\" tabindex=\"0\">b- Capsules of organs<\/li><li data-o=\"c\" tabindex=\"0\">c- Aorta<\/li><li data-o=\"d\" tabindex=\"0\">d- Umbilical cord<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_t18\"><h3>White fibrous CT <small>— 7 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_t18\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3z-195\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">195- Irregular white fibrous connective tissue is seen in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- umbilical cord.<\/li><li data-o=\"b\" tabindex=\"0\">b- capsules of organs.<\/li><li data-o=\"c\" tabindex=\"0\">c- Tendon<\/li><li data-o=\"d\" tabindex=\"0\">d- Ligamentum nuchae.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-196\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">196- Tendon is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- regular white fibrous connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- Irregular white fibrous connective tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- regular yellow elastic connective tissue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Irregular yellow elastic connective tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-197\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">197- The following are forms of embryonic connective tissue EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Wharton&#x27;s jelly.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mesenchymal tissue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid connective tissue.<\/li><li data-o=\"d\" tabindex=\"0\">d- Regular white fibrous connective tissue.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-198\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">198- The type of connective tissue proper (C.T.) forming the tendons is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Regular white fibrous C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- White adipose C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Loose areolar C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-199\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">199- The type of CT. in tendons is<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White fibrous.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipose.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-200\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">200- Regular white fibrous connective tissue is found in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Capsule of organs<\/li><li data-o=\"b\" tabindex=\"0\">b- Cornea of the eye<\/li><li data-o=\"c\" tabindex=\"0\">c- Vitreous humor of the eye<\/li><li data-o=\"d\" tabindex=\"0\">d- Large arteries<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3z-201\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">201- Irregular type of white fibrous connective tissue is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon<\/li><li data-o=\"b\" tabindex=\"0\">b- Sclera.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ligaments<\/li><li data-o=\"d\" tabindex=\"0\">d- Umbilical cord.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_d19\"><h3>Department MCQs <small>— أسئلة القسم · 50 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_d19\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3d-001\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">1- The following is a short-lived connective tissue cell:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-002\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">2- Undifferentiated mesenchymal cell is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Being a large oval cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Having well- developed Golgi apparatus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Having central dark nucleus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Possessing many free ribosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- One of the functions of undifferentiated mesenchymal cells is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formation of collagen fibers<\/li><li data-o=\"b\" tabindex=\"0\">b- Formation of blood cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretion of intercellular matrix.<\/li><li data-o=\"d\" tabindex=\"0\">d- Formation of elastic fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-004\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">4- In case of Injury, pericytes can differentiate into:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Chondrocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histiocyte<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibroblast.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lymphocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- Among the characteristics of pericytes:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Having a network of actin and myosin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Being differentiated cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Possessing darkly stained nuclei<\/li><li data-o=\"d\" tabindex=\"0\">d- Having many organelles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-006\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">6- Concerning fibroblasts:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They have few organelles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have many free ribosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have pale basophilic cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- The most common C.T. cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-007\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">7- Fibrocytes are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Deeply basophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Spindle-shaped with few processes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Well-developed Golgi apparatus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Being active cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-008\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">8- Concerning unilocular adipocytes, they:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are stained by Sudan III.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are concerned with heat generation.<\/li><li data-o=\"c\" tabindex=\"0\">c- They possess small fat droplets.<\/li><li data-o=\"d\" tabindex=\"0\">d- They can divide.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-009\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">9- Concerning multilocular adipocytes, they have:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cytochrome pigments.<\/li><li data-o=\"b\" tabindex=\"0\">b- Signet ring appearance.<\/li><li data-o=\"c\" tabindex=\"0\">c- Single large fat droplet.<\/li><li data-o=\"d\" tabindex=\"0\">d- Flat peripheral nucleus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- Histiocytes have:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Darkly basophilic cytoplasm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Euchromatic nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Pseudopodia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Few lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-011\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">11- Concerning reticular cell:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Rounded cells with no processes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are antibody forming cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Has pale basophilic cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- Has dark heterochromatic nucleus<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- Leptin hormone is secreted by the following cell:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histiocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-013\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">13- Plasma cells:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Originate from T-lymphocytes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Have clock-face nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Are long lived C.T. cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Are phagocytic cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-014\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">14- Concerning mast cells:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are antibody forming cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- They secrete histaminase enzyme.<\/li><li data-o=\"c\" tabindex=\"0\">c- Their granules are metachromatically stained.<\/li><li data-o=\"d\" tabindex=\"0\">d- They can be demonstrated with trypan blue stain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-015\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">15- Collagen fibers are formed by the following cell:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Macrophage<\/li><li data-o=\"b\" tabindex=\"0\">b- Histiocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Chondroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-016\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">16- Concerning collagen fibers:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Wavy branching bundles formed of non-branching fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophilic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Elastic<\/li><li data-o=\"d\" tabindex=\"0\">d- Stained yellow with Van Gieson stain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-017\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">17- Scurvy is due to defective synthesis of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ground substance.<\/li><li data-o=\"d\" tabindex=\"0\">d- Matrix.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-018\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">18- Elastic fibers are characterized by being:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Single, thin &amp; non- branching<\/li><li data-o=\"b\" tabindex=\"0\">b- Basophilic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Flexible but inelastic.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stained brown by orcein stain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-019\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">19- Concerning the reticular fibers:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They form bundles.<\/li><li data-o=\"b\" tabindex=\"0\">b- They are formed by chondroblasts &amp; smooth muscle cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- They are formed mainly of type III collagen fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- They are visible by H&amp;E.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-020\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">20- Elastic fibers are formed by the following cell:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts.<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mast cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-021\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">21- The most common type of connective tissue (C.T.) is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adipose C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Loose areolar C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- White fibrous C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-022\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">22- Among the functions of the loose areolar connective tissue:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Gives the skin its shape.<\/li><li data-o=\"b\" tabindex=\"0\">b- Withstands stretch.<\/li><li data-o=\"c\" tabindex=\"0\">c- Binds structures together.<\/li><li data-o=\"d\" tabindex=\"0\">d- Forms the stroma of the organs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-023\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">23- The functions of white adipose connective tissue include:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Withstands stress.<\/li><li data-o=\"b\" tabindex=\"0\">b- Heart generation.<\/li><li data-o=\"c\" tabindex=\"0\">c- Binds structures together.<\/li><li data-o=\"d\" tabindex=\"0\">d- Heat insulation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-024\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">24- Brown adipose C.T. is present in the following site in adults:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Interscapular space.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mammary gland.<\/li><li data-o=\"c\" tabindex=\"0\">c- Abdominal wall.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mesentery.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-025\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">25- Concerning the reticular connective tissue:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular fibers form branching bundles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its fibres are demonstrated by silver stain.<\/li><li data-o=\"c\" tabindex=\"0\">c- Binds structures together.<\/li><li data-o=\"d\" tabindex=\"0\">d- Is visible by H&amp;E.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-026\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">26- Mucoid connective tissue:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Is present in the vitreous humor of the eye.<\/li><li data-o=\"b\" tabindex=\"0\">b- Contains all types of connective tissue cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Is rich in connective tissue fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its matrix is firm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-027\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">27- White fibrous connective tissue:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Has abundant matrix.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is rich in blood supply.<\/li><li data-o=\"c\" tabindex=\"0\">c- Contains the three types of connective tissue fibers.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its cells are fibroblasts.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-028\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">28- Regular type of white fibrous C.T. Is present in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cornea.<\/li><li data-o=\"b\" tabindex=\"0\">b- Dermis of skin.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ligaments.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sclera of eye.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-029\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">29- Irregular type of white fibrous C.T, is present in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ligamentum nuchae.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tendons of the muscles.<\/li><li data-o=\"c\" tabindex=\"0\">c- Sclera of the eye.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stroma of the organs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-030\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">30- Concerning the yellow elastic connective tissue:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A loose type of C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Contain all types of C.T. cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Present in wall of aorta.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present in perichondrium &amp; periosteum.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-031\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">31- A 2-year-old girl with itchy skin&amp; respiratory distress is brought to the emergency room by her parents 30 minutes after eating peanut butter cookies. On physical examination the patient showed flushing &amp;swelling of the lips &amp;eye lids. Blood pressure [90/40mm Hg] &amp; pulse 100/minute. Which of the following is responsible for increased vascular permeability in this patient with a severe peanut allergy:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Eosinophils<\/li><li data-o=\"b\" tabindex=\"0\">b- Macrophages<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-032\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">32- A 68-year-old man presented with a two-week history of abdominal discomfort. A CT. scan revealed a dilated &amp; calcified segment of abdominal aorta. After surgery the examination of this dilated part demonstrated loss of which of the following components that contributed in development of this aneurysm:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic fibers<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular fibers<\/li><li data-o=\"d\" tabindex=\"0\">d- Smooth muscle<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-033\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">33- A 43-year-old woman presented with a breast mass, examination of the biopsy revealed a normal lobule of mammary gland surrounded by densely packed collagen fibers oriented in different directions with few cells in between. This area is primarily composed of which of the following types of C.T.:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Dense irregular white fibrous C.T.<\/li><li data-o=\"b\" tabindex=\"0\">b- Dense regular white fibrous C.T.<\/li><li data-o=\"c\" tabindex=\"0\">c- Yellow elastic C.T.<\/li><li data-o=\"d\" tabindex=\"0\">d- Loose areolar C.T.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-034\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">34- Concerning the previous biopsy, which of the following cells are responsible for synthesis of collagen &amp; ground substance production:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Adipocytes<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblasts<\/li><li data-o=\"c\" tabindex=\"0\">c- Glandular epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Macrophage<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-035\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">35- Silver-stained section from a biopsy of an enlarged lymph node revealed thin delicate irregular black fibers that represent which of the following components:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Elastic fibers<\/li><li data-o=\"b\" tabindex=\"0\">b- Proteoglycans<\/li><li data-o=\"c\" tabindex=\"0\">c- Fibrillin<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular fibers<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-036\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">36- This delicate stromal fibers described above are composed primarily of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen I<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen II<\/li><li data-o=\"c\" tabindex=\"0\">c- Elastin<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen III<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-037\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">37- An obese 40-year-old female suffered from delayed healing of abdominal surgical incision. The cause of this condition could be attributed to:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Increased unilocular fat cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Increased multilocular fat cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Increased fibroblasts.<\/li><li data-o=\"d\" tabindex=\"0\">d- Decreased fibroblasts<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-038\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">38- An 18-year-old lady is complaining of recurrent attacks of urticaria, hives &amp; itching. This condition may result from:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Eosinophilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lymphocytosis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Increased skin mast cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Increased respiratory mast cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-039\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">39- A 24-year-old woman is suffering from severe obesity not responding to any routine line of treatment, the physician asked her to assess the following hormone:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Histamine<\/li><li data-o=\"b\" tabindex=\"0\">b- Heparin<\/li><li data-o=\"c\" tabindex=\"0\">c- Leptin<\/li><li data-o=\"d\" tabindex=\"0\">d- Thermogenin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-040\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">40- A 46-year-old woman was suffering from repeated bleeding gums, loss of teeth and unhealed wounds. It is diagnosed as scurvy which may be due to defective synthesis of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen molecules<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastin molecules<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticulin molecules<\/li><li data-o=\"d\" tabindex=\"0\">d- Glycoprotein molecules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-041\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">41- A young boy with unhealed leg wound was diagnosed as vitamin C deficiency which could be attributed to defective collagen synthesis. The best stain to differentiate collagen fibers from other fibers is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E<\/li><li data-o=\"b\" tabindex=\"0\">b- Mallory’s trichrome stain<\/li><li data-o=\"c\" tabindex=\"0\">c- Sudan stain<\/li><li data-o=\"d\" tabindex=\"0\">d- Silver stain<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-042\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">42- A patient was brought to emergency department with a severe attack of bronchial asthma. This asthma is attributed to which secretion from the mast:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Heparin<\/li><li data-o=\"b\" tabindex=\"0\">b- IgE<\/li><li data-o=\"c\" tabindex=\"0\">c- Histamine.<\/li><li data-o=\"d\" tabindex=\"0\">d- Leukotriene<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-043\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">43- A Female was exposed to car accident while driving, resulting in many wounds in her body. The wounds healed within few days. The main C.T. cell contributing for this healing is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblasts<\/li><li data-o=\"b\" tabindex=\"0\">b- Fat cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-044\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">44- A child arrived at the pediatric outpatient clinic complaining of bleeding gums, falling of teeth and persistent non-healing wounds. The attending resident suspected a disease related to connective tissue. The disease causing such symptoms could be:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Osteoporosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Purpura.<\/li><li data-o=\"c\" tabindex=\"0\">c- Anemia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Scurvy.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-045\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">45- The etiology of the disease in the previous case could be:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Deficiency in calcium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Deficiency in vitamin C.<\/li><li data-o=\"c\" tabindex=\"0\">c- Decreased number of platelets.<\/li><li data-o=\"d\" tabindex=\"0\">d- Decreased number of RBCs.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-046\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">46- Concerning the previous disease the following occurs:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Rupture of RBCs due to their abnormal shapes.<\/li><li data-o=\"b\" tabindex=\"0\">b- Defective collagen synthesis.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mutation in mitochondrial DNA.<\/li><li data-o=\"d\" tabindex=\"0\">d- Increased bone resorption over bone formation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-047\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">47- A skin biopsy from an individual suffering from severe itching will demonstrate excessive increase in the number of certain connective tissue cell. This cell is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblast<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-048\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">48- The cell involved in the previous condition produces:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Antibodies.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histamine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen.<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-049\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">49- The stain characteristic for the cell detected in the previous case is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Trypan blue.<\/li><li data-o=\"b\" tabindex=\"0\">b- Toluidine blue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Silver.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3d-050\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">50- The origin of this cell is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- UMC.<\/li><li data-o=\"b\" tabindex=\"0\">b- Blood monocytes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- B lymphocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h3_e20\"><h3>Exam MCQs <small>— أسئلة الامتحانات · 23 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h3_e20\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c3e-001\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">1- Mallory trichrome stain can be used for demonstration of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen fibers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular fibers.<\/li><li data-o=\"c\" tabindex=\"0\">c- Macrophages.<\/li><li data-o=\"d\" tabindex=\"0\">d- actin microfibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-002\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">2- Regarding loose areolar connective tissue, it is:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Giving the skin its shape.<\/li><li data-o=\"b\" tabindex=\"0\">b- Forming stroma of glands.<\/li><li data-o=\"c\" tabindex=\"0\">c- The commonest type of CT proper.<\/li><li data-o=\"d\" tabindex=\"0\">d- Abundant in brain.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- The reticular connective tissue can be demonstrated with:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Toluidine blue.<\/li><li data-o=\"b\" tabindex=\"0\">b- silver.<\/li><li data-o=\"c\" tabindex=\"0\">c- H&amp;E.<\/li><li data-o=\"d\" tabindex=\"0\">d- Sudan III.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-004\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">4- Histiocytes originate from:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- B-lymphocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Adipocyte.<\/li><li data-o=\"d\" tabindex=\"0\">d- Monocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-005\" data-k=\"b\" data-alt=\"\"><p class=\"qt\" dir=\"ltr\">5- Irregular type of white fibrous connective tissue is present in:<span class=\"gtag\" dir=\"ltr\">195<\/span><span class=\"gtag warn\" dir=\"rtl\">مفتاح الملزمة مشكوك فيه<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tendon.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ligaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cornea.<\/li><li data-o=\"d\" tabindex=\"0\">d- Umbilical cord.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- The CT. cell that gives rise to fibroblast is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Reticular cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-007\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">7- Thermogenesis is a function of:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibrocyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Histiocyte.<\/li><li data-o=\"c\" tabindex=\"0\">c- Multilocular fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- One of the following C.T. cells is an antigen presenting cell:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Adipose cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibrocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-009\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">9- The plasma cell is characterized by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Surface IgE receptors.<\/li><li data-o=\"b\" tabindex=\"0\">b- Eccentric clock face nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Deep acidophilic cytoplasm.<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in sER &amp; lysosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-010\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">10- Vital stain is used to demonstrate:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pericyte.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fibroblast.<\/li><li data-o=\"c\" tabindex=\"0\">c- Multilocular fat cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- Histiocyte.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-011\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">11- The C.T. fibers stained brown with orcein are fibers:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen.<\/li><li data-o=\"d\" tabindex=\"0\">d- b&amp;c.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-012\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">12- The mucoid CT. is characterized by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Jelly-like excess ground substance.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fat cells predominate.<\/li><li data-o=\"c\" tabindex=\"0\">c- High vascularity.<\/li><li data-o=\"d\" tabindex=\"0\">d- Predominating collagen fibers.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-013\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">13- The type of C.T. in tendons is .............. C.T.:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- White fibrous.<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid.<\/li><li data-o=\"d\" tabindex=\"0\">d- Adipose.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-014\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">14- The most common type of C.T. in the adult body is .............. C.T.:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Brown adipose.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Mucoid.<\/li><li data-o=\"d\" tabindex=\"0\">d- Loose areolar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-015\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">15- The CT. cell with mitochondria rich in cytochrome oxidase is cell:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular<\/li><li data-o=\"b\" tabindex=\"0\">b- Multilocular fat<\/li><li data-o=\"c\" tabindex=\"0\">c- Unilocular fat<\/li><li data-o=\"d\" tabindex=\"0\">d- Plasma<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-016\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">16- Type of connective tissue proper forming stroma of organs is C.T.:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Reticular<\/li><li data-o=\"b\" tabindex=\"0\">b- white fibrous<\/li><li data-o=\"c\" tabindex=\"0\">c- Loose areolar<\/li><li data-o=\"d\" tabindex=\"0\">d- Brown adipose<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-017\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">17- The following cell can give rise to endothelial cell:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Histiocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Pericyte<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Monocytes are the origin of cells:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Plasma<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast<\/li><li data-o=\"c\" tabindex=\"0\">c- Macrophages<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblasts<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-019\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">19- Reticular fibers can be specially stained with:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- H&amp;E<\/li><li data-o=\"b\" tabindex=\"0\">b- Van Gieson<\/li><li data-o=\"c\" tabindex=\"0\">c- PAS<\/li><li data-o=\"d\" tabindex=\"0\">d- Orcein<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- Endocrine secretion of leptin is a function of:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fibroblast<\/li><li data-o=\"b\" tabindex=\"0\">b- Unilocular fat cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticulocyte<\/li><li data-o=\"d\" tabindex=\"0\">d- Pericytes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-021\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">21- The antigen presenting CT. cell is:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Histiocyte<\/li><li data-o=\"b\" tabindex=\"0\">b- Plasma cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Mast cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblast.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-022\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">22- Mast cell show:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Deep acidophilic cytoplasm<\/li><li data-o=\"b\" tabindex=\"0\">b- Clock face nucleus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Surface receptor for IgE.<\/li><li data-o=\"d\" tabindex=\"0\">d- Non granular cytoplasm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c3e-023\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">23- The synthesize CT. fibers and ground substance:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Macrophage<\/li><li data-o=\"b\" tabindex=\"0\">b- Mast cell<\/li><li data-o=\"c\" tabindex=\"0\">c- Plasma cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Fibroblast<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><\/div><div class=\"gpart\" data-part=\"4\" data-ch=\"c4\"><h2 dir=\"ltr\">Chapter 4 · Epithelium <small>— النسيج الطلائي · 237 سؤال · <bdi dir=\"ltr\">Dr. Zahra MCQs<\/bdi><\/small><\/h2><section class=\"tsec gsec\" data-g=\"h4_t01\"><h3>Surface epithelium <small>— 87 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t01\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-001\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">1- Which of the followings is NOT a character of the epithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Closely arranged cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Very little intercellular substances.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cells are strongly adherent.<\/li><li data-o=\"d\" tabindex=\"0\">d- Rich in lymphatic.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-002\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">2- What of the following facts about the epithelial tissue is true?:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Epithelium is considered to be (vascular tissue).<\/li><li data-o=\"b\" tabindex=\"0\">b- It’s one of the C.T. fibers types.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its cells lie on a basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its transitional type is considered to be simple.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-003\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">3- The origin of the epithelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- the ectoderm.<\/li><li data-o=\"b\" tabindex=\"0\">b- the mesoderm.<\/li><li data-o=\"c\" tabindex=\"0\">c- the endoderm.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-004\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">4- The epithelium is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Avascular tissue<\/li><li data-o=\"b\" tabindex=\"0\">b- Highly vascular tissue<\/li><li data-o=\"c\" tabindex=\"0\">c- contains abundant intercellular substance<\/li><li data-o=\"d\" tabindex=\"0\">d- lacks the basement membrane<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-005\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">5- The epithelium that lines the blood vessels is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Mesothelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Endothelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Transitional.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- The lining epithelium of pleura is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cubical Stratified epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified squamous epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-007\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">7- The surface of simple squamous epithelium is thin to allow:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- exchange of materials.<\/li><li data-o=\"b\" tabindex=\"0\">b- easy movement of organs.<\/li><li data-o=\"c\" tabindex=\"0\">c- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- The surface of simple squamous epithelium is smooth to allow:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- exchange of materials.<\/li><li data-o=\"b\" tabindex=\"0\">b- passage of blood &amp; easy movement of organs.<\/li><li data-o=\"c\" tabindex=\"0\">c- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-009\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">9- Pseudostratified columnar epithelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Transitional epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified columnar epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- A simple epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- It is a false appearance of epithelium, it is CT.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-010\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">10- One statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium has flat nuclei.<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple columnar epithelium presents in the nasal surface of the soft palate.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple cuboidal epithelium forms the skin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Simple squamous epithelium of two types; keratinized or non-keratinized.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-011\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">11- One statement is NOT true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Squamous cells have flat nuclei.<\/li><li data-o=\"b\" tabindex=\"0\">b- Columnar cells have oval nuclei.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cuboidal cells have rounded nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar epithelium cells have no nuclei.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-012\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">12- The simple columnar epithelium is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The lining of thyroid follicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small intestine.<\/li><li data-o=\"c\" tabindex=\"0\">c- The lining of the vagina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-013\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">13- The simple cuboidal epithelium is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The lining of thyroid follicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small intestine.<\/li><li data-o=\"c\" tabindex=\"0\">c- The lining of the vagina.<\/li><li data-o=\"d\" tabindex=\"0\">d- Epidermis of skin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-014\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">14- The trachea (upper respiratory tract) is lined by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- non keratinized stratified squamous epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Keratinized stratified squamous epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- pseudostratified columnar ciliated epithelium with goblet cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-015\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">15- The epithelium type that line most of the gastrointestinal tracts:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-016\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">16- The alveoli in the lung (gas exchange) are line by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- pseudostratified epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-017\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">17- The epithelium that lines the abdominal cavity(peritoneum) (serous sacs) is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Endothelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mesothelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Transitional.<\/li><li data-o=\"d\" tabindex=\"0\">d- Epithelioid.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- The epithelium which is composed of cells resting on the same basement membrane, but not all reaching the lumen is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stratified squamous.<\/li><li data-o=\"b\" tabindex=\"0\">b- stratified cuboidal.<\/li><li data-o=\"c\" tabindex=\"0\">c- pseudostratified epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-019\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">19- The kidney tubules are lined by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-020\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">20- Function of simple columnar epithelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- secretion (stomach).<\/li><li data-o=\"b\" tabindex=\"0\">b- protection.<\/li><li data-o=\"c\" tabindex=\"0\">c- absorption (intestine)<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-021\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">21- The lining epithelium of thyroid follicles is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar ciliated epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-022\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">22- The lining epithelium of the uterus is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar ciliated epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-023\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">23- Nuclei of simple columnar epithelium are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- central rounded.<\/li><li data-o=\"b\" tabindex=\"0\">b- basal &amp; oval.<\/li><li data-o=\"c\" tabindex=\"0\">c- flat.<\/li><li data-o=\"d\" tabindex=\"0\">d- Binucleated.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-024\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">24- Nuclei of simple cuboidal epithelium are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- central rounded.<\/li><li data-o=\"b\" tabindex=\"0\">b- basal &amp; oval.<\/li><li data-o=\"c\" tabindex=\"0\">c- flat.<\/li><li data-o=\"d\" tabindex=\"0\">d- May be bi-nucleated.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-025\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">25- Simple columnar epithelium of the intestine is provided with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Microvilli.<\/li><li data-o=\"c\" tabindex=\"0\">c- stereocilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Flagella.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-026\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">26- Pseudostratified columnar ciliated epithelium is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Presence of several layers of cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- The nuclei of cells are lying at the same height.<\/li><li data-o=\"c\" tabindex=\"0\">c- All cells are lying on the basement membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-027\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">27- Goblet cells are present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pseudostratified columnar non-ciliated epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified squamous non-keratinized epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Pseudostratified columnar ciliated epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-028\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">28- Function of stratified epithelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- secretion.<\/li><li data-o=\"b\" tabindex=\"0\">b- protection.<\/li><li data-o=\"c\" tabindex=\"0\">c- absorption.<\/li><li data-o=\"d\" tabindex=\"0\">d- both a &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-029\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">29- Transitional epithelium is stretchable as it has:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Thick basement membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- wide intracellular substance containing mucous like substance.<\/li><li data-o=\"c\" tabindex=\"0\">c- thin layer of keratin on top layer.<\/li><li data-o=\"d\" tabindex=\"0\">d- flat cells in the top layer and columnar cells in the top layer.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-030\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">30- Concerning Nuclei of Transitional epithelium, all are true Except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- central rounded.<\/li><li data-o=\"b\" tabindex=\"0\">b- basal &amp; oval.<\/li><li data-o=\"c\" tabindex=\"0\">c- flat.<\/li><li data-o=\"d\" tabindex=\"0\">d- May be binucleated.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-031\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">31- The type of epithelium that can accommodate stretch is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- stratified squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Transitional epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified columnar epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-032\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">32- Which type of the epithelium has dome shaped cells?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Transitional epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified cubical epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified squamous epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-033\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">33- Stratified epithelium formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Several types of cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Several layers of cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Several types of simple epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Several layers of simple epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-034\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">34- In the stratified squamous epithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The basal layer is squamous cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- The basal layer is columnar cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- The basal layer is polyhedral cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-035\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">35- Stratified squamous keratinized epithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Covered by thick layer of keratin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Present in the moist surfaces (mouth, pharynx and esophagus).<\/li><li data-o=\"c\" tabindex=\"0\">c- Lines the digestive tract.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lines the uterus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-036\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">36- All the statements concerning the transitional epithelium is true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Exclusively in the urinary system.<\/li><li data-o=\"b\" tabindex=\"0\">b- Superficial cells occasionally binucleated.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basal layer is squamous cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- The number of cell layers is changeable.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-037\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">37- All of the followings are examples of stratified epithelium EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stratified columnar epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pseudostratified epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Transitional epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both answers (b &amp; c) are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-038\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">38- The epithelium type that has the ability to decrease its layers’ number in full viscus is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-039\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">39- The stratified squamous non-keratinized epithelium is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The lining of thyroid follicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small intestine.<\/li><li data-o=\"c\" tabindex=\"0\">c- The lining of the vagina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-040\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">40- The stratified squamous keratinized epithelium is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The lining of thyroid follicles.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small intestine.<\/li><li data-o=\"c\" tabindex=\"0\">c- The lining of the vagina.<\/li><li data-o=\"d\" tabindex=\"0\">d- Epidermis of skin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-041\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">41- The epithelium lines the urinary bladder is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- stratified squamous epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Glandular epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-042\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">42- The epithelium which is formed of more than one layer is called:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple.<\/li><li data-o=\"b\" tabindex=\"0\">b- stratified.<\/li><li data-o=\"c\" tabindex=\"0\">c- pseudostratified.<\/li><li data-o=\"d\" tabindex=\"0\">d- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-043\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">43- The epidermis is formed by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous non keratinized epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- stratified squamous non keratinized epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- stratified squamous keratinized epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- simple columnar ciliated epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-044\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">44- The esophagus is lined by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous non keratinized epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- stratified squamous non keratinized epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- stratified squamous keratinized epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- simple columnar ciliated epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-045\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">45- The lining epithelium of the ureter is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- simple cuboidal epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple columnar ciliated epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-046\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">46- Stratified squamous non keratinized epithelium is found in all EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Gum.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tongue.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cornea.<\/li><li data-o=\"d\" tabindex=\"0\">d- Skin.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-047\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">47- The epithelium that resist friction is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pseudostratified columnar.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified squamous.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-048\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">48- Stratified squamous non keratinized epithelium is present in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Oral cavity.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trachea.<\/li><li data-o=\"c\" tabindex=\"0\">c- Skin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Uterus.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-049\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">49- The function of transitional epithelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- stretchability.<\/li><li data-o=\"b\" tabindex=\"0\">b- Distensibility.<\/li><li data-o=\"c\" tabindex=\"0\">c- Protection from toxins.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-050\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">50- Simple cubical epithelium is concerned with<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion<\/li><li data-o=\"b\" tabindex=\"0\">b- Contraction<\/li><li data-o=\"c\" tabindex=\"0\">c- Gas exchange<\/li><li data-o=\"d\" tabindex=\"0\">d- Protection<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-051\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">51- The epithelial tissue is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- High regenerative power<\/li><li data-o=\"b\" tabindex=\"0\">b- Penetrated by blood vessels<\/li><li data-o=\"c\" tabindex=\"0\">c- Very wide intercellular space<\/li><li data-o=\"d\" tabindex=\"0\">d- No basement membrane<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-052\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">52- Simple cubical epithelium is formed of one layer of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tall cells with flat nuclei<\/li><li data-o=\"b\" tabindex=\"0\">b- Flat cells with flat nuclei<\/li><li data-o=\"c\" tabindex=\"0\">c- Multiple cell layers with rounded nuclei<\/li><li data-o=\"d\" tabindex=\"0\">d- Cube-like cells with rounded nuclei<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-053\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">53- Simple squamous epithelium is concerned with:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion<\/li><li data-o=\"b\" tabindex=\"0\">b- Contraction<\/li><li data-o=\"c\" tabindex=\"0\">c- Gas exchange<\/li><li data-o=\"d\" tabindex=\"0\">d- Protection<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-054\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">54- Endothelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium in blood vessels<\/li><li data-o=\"b\" tabindex=\"0\">b- simple squamous epithelium in serous membranes<\/li><li data-o=\"c\" tabindex=\"0\">c- simple cuboidal epithelium in blood vessels<\/li><li data-o=\"d\" tabindex=\"0\">d- simple cuboidal epithelium in serous membranes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-055\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">55- Mesothelium is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- simple squamous epithelium in blood vessels<\/li><li data-o=\"b\" tabindex=\"0\">b- simple squamous epithelium in serous membranes<\/li><li data-o=\"c\" tabindex=\"0\">c- simple cuboidal epithelium in blood vessels<\/li><li data-o=\"d\" tabindex=\"0\">d- simple cuboidal epithelium in serous membranes<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-056\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">56- Type of epithelium in trachea is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cuboidal<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated with goblet cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-057\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">57- Type of epithelium in bronchioles is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cuboidal<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated with goblet cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-058\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">58- Type of epithelium in urinary bladder is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Keratinized stratified squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Non keratinized stratified squamous<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified cuboidal<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-059\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">59- Type of epithelium in ureter is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Keratinized stratified squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Non keratinized stratified squamous<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified cuboidal<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-060\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">60- Type of epithelium in thyroid follicles is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cuboidal<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated with goblet cell<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-061\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">61- Type of epithelium in cornea is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Keratinized stratified squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Non keratinized stratified squamous<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified cuboidal<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-062\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">62- Type of epithelium in skin is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Keratinized stratified squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Non keratinized stratified squamous<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified cuboidal<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-063\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">63- Type of epithelium in ducts of sweat glands is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Keratinized stratified squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Non keratinized stratified squamous<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified cuboidal<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-064\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">64- Type of epithelium in convoluted tubules of kidney is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cuboidal<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated with goblet cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-065\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">65- Type of epithelium in Bowman’s capsule of kidney is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cuboidal<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated with goblet cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-066\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">66- Function of stratified squamous epithelium is<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Absorption<\/li><li data-o=\"b\" tabindex=\"0\">b- Reabsorption<\/li><li data-o=\"c\" tabindex=\"0\">c- Protection<\/li><li data-o=\"d\" tabindex=\"0\">d- Gas exchange<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-067\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">67- The following is a characteristic feature of uroepithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Highly vascular<\/li><li data-o=\"b\" tabindex=\"0\">b- Clear wavy basement membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- High columnar cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial cells are dome shaped<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-068\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">68- Epithelium is characterized by the following:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cells are widely separated<\/li><li data-o=\"b\" tabindex=\"0\">b- cells are fixed to ground substances<\/li><li data-o=\"c\" tabindex=\"0\">c- cells rest on a basement membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- cells are penetrated by blood vessels<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-069\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">69- The feature characterizes pseudostratified columnar epithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- All nuclei at the same depth from surface<\/li><li data-o=\"b\" tabindex=\"0\">b- All cells border on the lumen<\/li><li data-o=\"c\" tabindex=\"0\">c- All cells touch the basement membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- All cells are ciliated<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-070\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">70- Epithelium is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cells are widely separated<\/li><li data-o=\"b\" tabindex=\"0\">b- Never regenerate<\/li><li data-o=\"c\" tabindex=\"0\">c- Cells rest on a basement membrane<\/li><li data-o=\"d\" tabindex=\"0\">d- Blood vessels penetrate between cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-071\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">71- The type of epithelium providing thin membrane and smooth surface is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cubical epithelium<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified squamous epithelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-072\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">72- Transitional epithelium is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- keratinized or non-keratinized types<\/li><li data-o=\"b\" tabindex=\"0\">b- Cells rest on clear wavy basement membrane<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of 5-30 layers of cells<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial cells are covered by plaques<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-073\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">73- The epithelial tissue is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of widely separated cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Great amount of intercellular matrix.<\/li><li data-o=\"c\" tabindex=\"0\">c- Avascular.<\/li><li data-o=\"d\" tabindex=\"0\">d- Arise only from mesoderm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-074\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">74- Respiratory epithelium refers to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple cubical epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified cubical epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar non ciliated epithelium with goblet cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated epithelium with goblet cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-075\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">75- Junctional complex is demonstrated in the cells of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Superficial layer of transitional epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basal layer of urothelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Intermediate layers of transitional epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal layer of stratified cubical epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-076\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">76- Regarding the endothelium, it is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lining the blood vessels and heart<\/li><li data-o=\"b\" tabindex=\"0\">b- Covered by cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of columnar cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- A type of stratified epithelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-077\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">77- Follicles of thyroid gland are lined by<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple columnar ciliated<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple cubical.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple squamous<\/li><li data-o=\"d\" tabindex=\"0\">d- Simple columnar non-ciliated.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-078\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">78- Concerning pseudostratified columnar epithelium:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A type of stratified epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Cells are widely separated.<\/li><li data-o=\"c\" tabindex=\"0\">c- All cells reach the surface.<\/li><li data-o=\"d\" tabindex=\"0\">d- All cells rest on basement membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-079\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">79- Simple columnar ciliated epithelium is lining:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Trachea.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fallopian tube.<\/li><li data-o=\"c\" tabindex=\"0\">c- Vas deferens.<\/li><li data-o=\"d\" tabindex=\"0\">d- Vagina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-080\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">80- Transitional epithelium is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of 5-30 layers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basement membrane is clear and wavy.<\/li><li data-o=\"c\" tabindex=\"0\">c- Intermediate cells are Joined by only desmosome<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial layer of cells covered by rigid plaques.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-081\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">81- One of the epithelial tissue characters is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Low power of regeneration<\/li><li data-o=\"b\" tabindex=\"0\">b- Consists of cells &amp; excess intercellular space<\/li><li data-o=\"c\" tabindex=\"0\">c- Penetrated by blood vessels<\/li><li data-o=\"d\" tabindex=\"0\">d- Clear or non-clear basement membrane<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-082\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">82- Simple squamous epithelium is formed of one layer of<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cube-like cells with flat nuclei<\/li><li data-o=\"b\" tabindex=\"0\">b- Flat cells with rounded nuclei<\/li><li data-o=\"c\" tabindex=\"0\">c- Flat cells with flat nuclei<\/li><li data-o=\"d\" tabindex=\"0\">d- Cube-like cells with rounded nuclei<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-083\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">83- The stomach is lined by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple cubical epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Pseudostratified columnar ciliated epithelium with goblet cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified columnar epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-084\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">84- Pseudostratified columnar non ciliated epithelium lines:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Skin.<\/li><li data-o=\"b\" tabindex=\"0\">b- Trachea.<\/li><li data-o=\"c\" tabindex=\"0\">c- Ureter.<\/li><li data-o=\"d\" tabindex=\"0\">d- Vas deferens.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-085\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">85- Ducts of sweat glands are lined by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified cubical epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Simple cubical epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-086\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">86- Regarding transitional epithelium, the following statement is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of 5-30 layers of cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cells rest on thick basement membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Superficial cells are connected by junctional complex.<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial cells are covered by cilia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-087\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">87- The epithelial tissue is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of widely separated cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Avascular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Great amount of intercellular matrix.<\/li><li data-o=\"d\" tabindex=\"0\">d- Arise only from mesoderm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t02\"><h3>Glandular epithelium <small>— 16 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t02\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-088\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">88- According to the mode of secretion the exocrine glands classified into:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Apocrine, holocrine and merocrine glands<\/li><li data-o=\"b\" tabindex=\"0\">b- Mucous, serous and mucoserous glands<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple, branched, and compound glands<\/li><li data-o=\"d\" tabindex=\"0\">d- Alveolar, tubular, tubuloalveolar glands<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-089\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">89- Concerning the classification of exocrine glands the term”simple” refers that:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its duct is not branching.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its secretory part is one unit.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its secretory part is tubular.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its secretory part is alveolar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-090\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">90- Concerning the exocrine glands the term “tubular” refers to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its duct is not branching.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its secretory part is one unit.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its secretory part is tubular.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its secretory part is alveolar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-091\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">91- Concerning the exocrine glands the term “compound” refers to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Its duct is branching.<\/li><li data-o=\"b\" tabindex=\"0\">b- Its secretory part is branching.<\/li><li data-o=\"c\" tabindex=\"0\">c- A and B.<\/li><li data-o=\"d\" tabindex=\"0\">d- Its secretory part is alveolar.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-092\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">92- Mixed gland is a mixture of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Endocrine and exocrine glands.<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple and compound glands.<\/li><li data-o=\"c\" tabindex=\"0\">c- Unicellular and multicellular glands.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stroma and parenchyma.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-093\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">93- Glands are classified according to the presence or absence of ducts into:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- exocrine, endocrine or mixed glands.<\/li><li data-o=\"b\" tabindex=\"0\">b- serous and mucous glands.<\/li><li data-o=\"c\" tabindex=\"0\">c- unicellular and multi-cellular glands.<\/li><li data-o=\"d\" tabindex=\"0\">d- none of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-094\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">94- Regarding the exocrine gland:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is only unicellular<\/li><li data-o=\"b\" tabindex=\"0\">b- Its secretion is carried by blood<\/li><li data-o=\"c\" tabindex=\"0\">c- It is only merocrine<\/li><li data-o=\"d\" tabindex=\"0\">d- Its secretion is carried by duct system<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-095\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">95- Exocrine glands:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Release their secretion in blood<\/li><li data-o=\"b\" tabindex=\"0\">b- Are unicellular or multicellular<\/li><li data-o=\"c\" tabindex=\"0\">c- Have no connection with their site of origin<\/li><li data-o=\"d\" tabindex=\"0\">d- Their cells have basal granules<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-096\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">96- Glands that lose their upper portion of cytoplasm during secretion:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- apocrine.<\/li><li data-o=\"b\" tabindex=\"0\">b- merocrine.<\/li><li data-o=\"c\" tabindex=\"0\">c- holocrine.<\/li><li data-o=\"d\" tabindex=\"0\">d- autocrine.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-097\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">97- Glands that release their secretion by exocytosis is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- apocrine.<\/li><li data-o=\"b\" tabindex=\"0\">b- merocrine.<\/li><li data-o=\"c\" tabindex=\"0\">c- holocrine.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-098\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">98- When a whole cell is expelled as a secretory product, the term applies:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Merocrine<\/li><li data-o=\"b\" tabindex=\"0\">b- Apocrine<\/li><li data-o=\"c\" tabindex=\"0\">c- Holocrine<\/li><li data-o=\"d\" tabindex=\"0\">d- Paracrine<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-099\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">99- A non- branched duct with branched rounded secretory unit forms the ... gland:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple branched alveolar<\/li><li data-o=\"b\" tabindex=\"0\">b- Compound branched alveolar<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple alveolar<\/li><li data-o=\"d\" tabindex=\"0\">d- Compound tubuloalveolar<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-100\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">100- Apocrine secretion refers to:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The most common mode of secretion<\/li><li data-o=\"b\" tabindex=\"0\">b- No changes occur in secretory cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretion comes out with apex of the cell<\/li><li data-o=\"d\" tabindex=\"0\">d- The whole cell is lost with secretion<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-101\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">101- Simple branched gland explains that the:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Duct is branched and secretory part is not branched.<\/li><li data-o=\"b\" tabindex=\"0\">b- Duct is not branched but secretory part is branched.<\/li><li data-o=\"c\" tabindex=\"0\">c- Duct and secretory part are not branched.<\/li><li data-o=\"d\" tabindex=\"0\">d- Duct and secretory part are branched.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-102\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">102- Regarding merocrine secretion:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The whole cell come out with secretion.<\/li><li data-o=\"b\" tabindex=\"0\">b- The least common mode of secretion.<\/li><li data-o=\"c\" tabindex=\"0\">c- The apical part of the cell come out with the secretion.<\/li><li data-o=\"d\" tabindex=\"0\">d- No change occurs in the secretory cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-103\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">103- Regarding holocrine mode of glandular secretion<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is exocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Apex of the cell comes out with secretion<\/li><li data-o=\"c\" tabindex=\"0\">c- The whole cell is lost with secretion.<\/li><li data-o=\"d\" tabindex=\"0\">d- No change in secretory cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t03\"><h3>Neuroepithelium <small>— 3 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t03\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-104\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">104- Which type of the epithelium has supporting cells?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Myoepithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neuroepithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Uroepithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Glandular epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-105\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">105- One statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neuroepithelium is a special type of nerve cells modified to epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Neuroepithelium is a special type of epithelium modified to sensory function.<\/li><li data-o=\"c\" tabindex=\"0\">c- Neuroepithelium means that nerve and epithelium are of the same origin.<\/li><li data-o=\"d\" tabindex=\"0\">d- Neuroepithelium means that epithelium develop from the nerve.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-106\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">106- The epithelium forming the taste buds is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Neuroepithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Glandular epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- simple epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- stratified epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t04\"><h3>Myoepithelium <small>— 5 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t04\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-107\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">107- Concerning the myoepithelial cells all the statements are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are spindle shaped cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- They contain actin and myosin.<\/li><li data-o=\"c\" tabindex=\"0\">c- They can contract.<\/li><li data-o=\"d\" tabindex=\"0\">d- They are related to the endocrine glands.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-108\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">108- Myoepithelial cells are characterized by the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- are contractile cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- present between base of cells &amp; their basement membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- present between apex of cells &amp; their basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-109\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">109- Which of the following epithelial cells has the ability to contract?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Goblet cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Endothelial cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basket cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Mesothelial cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-110\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">110- The type of epithelium with contractile function is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Surface epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Neuro-epithelium<\/li><li data-o=\"c\" tabindex=\"0\">c- Myo-epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Urothelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-111\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">111- Regarding myo-epithelium, one of the following statements is correct:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present in thyroid gland.<\/li><li data-o=\"b\" tabindex=\"0\">b- The cells act as a receptor.<\/li><li data-o=\"c\" tabindex=\"0\">c- Present between the secretory cells and the duct lumen.<\/li><li data-o=\"d\" tabindex=\"0\">d- The cells can contract.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t05\"><h3>Apical specialization <small>— 10 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t05\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-112\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">112- Microvilli are composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Intermediate filaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- Microfilaments<\/li><li data-o=\"d\" tabindex=\"0\">d- Keratin filaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-113\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">113- The followings are free surface specialization EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microvilli<\/li><li data-o=\"b\" tabindex=\"0\">b- Cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stereocilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Phagocytosis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-114\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">114- Microvilli:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- formed of microtubules.<\/li><li data-o=\"b\" tabindex=\"0\">b- formed of actin filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- present in small intestine &amp; kidney.<\/li><li data-o=\"d\" tabindex=\"0\">d- both b &amp; c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-115\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">115- The actin filaments form the core of the microvilli, it is embedded in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basal body.<\/li><li data-o=\"b\" tabindex=\"0\">b- Kinetochore.<\/li><li data-o=\"c\" tabindex=\"0\">c- Terminal web.<\/li><li data-o=\"d\" tabindex=\"0\">d- Centrosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-116\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">116- Microvilli under light microscope are described as:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Brush border.<\/li><li data-o=\"b\" tabindex=\"0\">b- Striated border.<\/li><li data-o=\"c\" tabindex=\"0\">c- A or B.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-117\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">117- One statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stereocilia is long microvilli.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stereocilia is long cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stereocilia is short flagella.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stereocilia consists of 9 triplets of microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-118\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">118- Concerning stereocilia, which of the following is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Increase the surface area.<\/li><li data-o=\"b\" tabindex=\"0\">b- Present in epididymis.<\/li><li data-o=\"c\" tabindex=\"0\">c- A and B.<\/li><li data-o=\"d\" tabindex=\"0\">d- Movement of the mucous.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-119\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">119- Stereocilia is characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- short and motile.<\/li><li data-o=\"b\" tabindex=\"0\">b- long and motile.<\/li><li data-o=\"c\" tabindex=\"0\">c- formed of microtubules.<\/li><li data-o=\"d\" tabindex=\"0\">d- formed of actin filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-120\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">120- Long motile structures on the surface of some epithelial cells are known as:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Microvilli.<\/li><li data-o=\"b\" tabindex=\"0\">b- Cilia.<\/li><li data-o=\"c\" tabindex=\"0\">c- Flagella.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stereocilia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-121\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">121- Regarding the cilia, choose the correct statement:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The core is rich in actin filaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- The axoneme is formed of 20 microtubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its main function is increasing the surface area of cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- The basal body is formed of 9 doublets of microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t06\"><h3>Lateral specialization <small>— 28 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t06\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-122\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">122- One character for gap junction is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Encircles the apex of the cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Permitting ions exchange<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of attachment plaque anchoring intermediate filaments<\/li><li data-o=\"d\" tabindex=\"0\">d- Formed of condensed protein anchoring microfilaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-123\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">123- Fusion of the two cell membranes at certain points occur in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Desmosomes<\/li><li data-o=\"b\" tabindex=\"0\">b- Adherens junctions<\/li><li data-o=\"c\" tabindex=\"0\">c- Gap junctions<\/li><li data-o=\"d\" tabindex=\"0\">d- Tight junctions<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-124\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">124- Cell junction that restrict passage of substances in between cells is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- gap junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- zonula occludens.<\/li><li data-o=\"c\" tabindex=\"0\">c- zonula adherens.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-125\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">125- Zonula adherence:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- They are belt like junction with a space of 15-20 nm.<\/li><li data-o=\"b\" tabindex=\"0\">b- The most apically located junction.<\/li><li data-o=\"c\" tabindex=\"0\">c- Prevents water soluble substances from passing between the cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Present between heart muscle cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-126\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">126- Desmosome (macula adherence):<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Disk shaped plaque of electron dense materials.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- Dense vertical line.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-127\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">127- Junctional complex is formed of three types of junctions:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Zonula occludens, zonula adherence and macula adherence.<\/li><li data-o=\"b\" tabindex=\"0\">b- Zonula occludens, zonula adherence and gap junction.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-128\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">128- Gap junction (nexus) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Occluding junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adhering junction<\/li><li data-o=\"c\" tabindex=\"0\">c- Communicating junction.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-129\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">129- All the following statements concerning gap junction (nexus) are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Leaves an intercellular cleft 2-3 nm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Minute structure bridging the gap called connexons.<\/li><li data-o=\"c\" tabindex=\"0\">c- Each connexon consists of six subunits.<\/li><li data-o=\"d\" tabindex=\"0\">d- Provides an actual fusion of adjacent two cell membranes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-130\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">130- The following statements concerning gap junction (nexus) are true EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It links the interior of adjacent cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- It permits ions and small molecule to pass from one cell to another.<\/li><li data-o=\"c\" tabindex=\"0\">c- They transmit impulses at certain synapse.<\/li><li data-o=\"d\" tabindex=\"0\">d- Provides an actual fusion of adjacent two cell membranes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-131\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">131- Cell junction that prevent leakage (passage of fluids) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- gap junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- zonula occludens.<\/li><li data-o=\"c\" tabindex=\"0\">c- zonula adherens.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-132\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">132- The type of filaments present in zonula adherens (adhering jun.) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- actin filaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- intermediate filaments.<\/li><li data-o=\"c\" tabindex=\"0\">c- myosin filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-133\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">133- The type of filaments present in macula adherens (desmosome) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- actin filaments.<\/li><li data-o=\"b\" tabindex=\"0\">b- intermediate filaments (tonofilament).<\/li><li data-o=\"c\" tabindex=\"0\">c- myosin filaments.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-134\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">134- Intercellular space is zero in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- zonula adherens.<\/li><li data-o=\"b\" tabindex=\"0\">b- zonula occludens (tight junction).<\/li><li data-o=\"c\" tabindex=\"0\">c- macula adherens.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-135\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">135- Connexin protein is found in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- desmosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- gap junction.<\/li><li data-o=\"c\" tabindex=\"0\">c- adherent junction.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-136\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">136- The strongest type of junctions is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- zonula occludens.<\/li><li data-o=\"b\" tabindex=\"0\">b- zonula adherens.<\/li><li data-o=\"c\" tabindex=\"0\">c- macula adherens.<\/li><li data-o=\"d\" tabindex=\"0\">d- gap junction.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-137\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">137- Junctional complex are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- zonula occludens, zonula adherens, desmosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- present in between small intestine epithelial cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- all of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-138\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">138- Gap junction (nexus) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- present in cardiac muscle.<\/li><li data-o=\"b\" tabindex=\"0\">b- allow passage of ions.<\/li><li data-o=\"c\" tabindex=\"0\">c- Communicating junction.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-139\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">139- Gap junction is present in the following EXCEPT:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- cardiac and smooth muscle.<\/li><li data-o=\"b\" tabindex=\"0\">b- nerve cells<\/li><li data-o=\"c\" tabindex=\"0\">c- bone cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- blood cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-140\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">140- Which of the following is involved in cell to cell communication?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Gap junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Desmosomes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Demilunes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal lamina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-141\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">141- The junction which prevents entrance of extracellular substance:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Gap junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adherent junction.<\/li><li data-o=\"c\" tabindex=\"0\">c- Occluding junction.<\/li><li data-o=\"d\" tabindex=\"0\">d- Desmosome.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-142\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">142- Junctional complex is composed of the following except:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Zonula occludens<\/li><li data-o=\"b\" tabindex=\"0\">b- Zonula adherens<\/li><li data-o=\"c\" tabindex=\"0\">c- Fascia adherens<\/li><li data-o=\"d\" tabindex=\"0\">d- Macula adherens<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-143\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">143- Stereocilia are composed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Intermediate filaments<\/li><li data-o=\"b\" tabindex=\"0\">b- Microtubules<\/li><li data-o=\"c\" tabindex=\"0\">c- Long microvilli<\/li><li data-o=\"d\" tabindex=\"0\">d- Short microvilli<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-144\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">144- Two adjacent cell membranes fuse at certain points and encircle the cell in:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Zonula adherens<\/li><li data-o=\"b\" tabindex=\"0\">b- Zonula occludens<\/li><li data-o=\"c\" tabindex=\"0\">c- Desmosomes<\/li><li data-o=\"d\" tabindex=\"0\">d- Gap junction<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-145\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">145- The communicating type of junction is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tight junction<\/li><li data-o=\"b\" tabindex=\"0\">b- Gap junction.<\/li><li data-o=\"c\" tabindex=\"0\">c- Adherent junction<\/li><li data-o=\"d\" tabindex=\"0\">d- Desmosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-146\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">146- The intercellular space in macula adherens measures:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Zero.<\/li><li data-o=\"b\" tabindex=\"0\">b- 3 nm<\/li><li data-o=\"c\" tabindex=\"0\">c- 15-20 nm<\/li><li data-o=\"d\" tabindex=\"0\">d- 30 nm<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-147\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">147- Concerning Zonula occludens (occluding junction)<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is a type of apical epithelial specializations<\/li><li data-o=\"b\" tabindex=\"0\">b- Two adjacent cell membranes fuse at certain points<\/li><li data-o=\"c\" tabindex=\"0\">c- The adjacent cell membranes are widely separated<\/li><li data-o=\"d\" tabindex=\"0\">d- It occurs as scattered spots.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-148\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">148- Choose the following correct statement:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Desmosomes are maximum at areas of minimal friction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Tight junction restricts the movement of substance between cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Zonula adherens allow the passage of ions between the cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- The adjacent cell membranes in desmosomes are tightly connected.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-149\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">149- Regarding nexus, choose the correct statement:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is found in cardiac muscle.<\/li><li data-o=\"b\" tabindex=\"0\">b- It prevents the passage of substances between cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- The intercellular space is wide.<\/li><li data-o=\"d\" tabindex=\"0\">d- It holds the cells together and prevent their separation.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_t07\"><h3>Basal specialization <small>— 16 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_t07\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4z-150\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">150- Anchoring fibrils attaching the basement membrane to underlying C.T. is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen type IV<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen type VII<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen type III<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen type II<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-151\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">151- One character for macula adherens (desmosome) is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Encircles the apex of the cell<\/li><li data-o=\"b\" tabindex=\"0\">b- Permitting exchange of ions<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of attachment plaque anchoring intermediate filaments<\/li><li data-o=\"d\" tabindex=\"0\">d- Formed of condensed protein anchoring microfilaments<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-152\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">152- Anchoring fibrils attaching the basement membrane to underlying C.T. is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen type IV<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen type VII<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen type III<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen type II<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-153\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">153- Regarding the hemidesmosomes:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Like gap junctions<\/li><li data-o=\"b\" tabindex=\"0\">b- Include membrane infoldings and mitochondria<\/li><li data-o=\"c\" tabindex=\"0\">c- Located at apex of the cell<\/li><li data-o=\"d\" tabindex=\"0\">d- Present at basal parts of the basal cells<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-154\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">154- Concerning the basement membrane ONE statement is true:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is supporting layer between the epithelium and connective tissue.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basal lamina synthesized by epithelial cells<\/li><li data-o=\"c\" tabindex=\"0\">c- Lamina reticularis manufactured by connective tissue cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- All of the above.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-155\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">155- Basal lamina by EM is formed of 2 layers:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basement membrane and lamina lucida.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lamina lucida and lamina densa.<\/li><li data-o=\"c\" tabindex=\"0\">c- Lamina lucida and lamina reticularis.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lamina densa and basal lamina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-156\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">156- Ion transporting cells need large surface area, so they are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- numerous microvilli.<\/li><li data-o=\"b\" tabindex=\"0\">b- numerous lateral interdigitations.<\/li><li data-o=\"c\" tabindex=\"0\">c- numerous basal infoldings.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-157\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">157- The basal lamina is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- type IV collagen.<\/li><li data-o=\"b\" tabindex=\"0\">b- type III collagen.<\/li><li data-o=\"c\" tabindex=\"0\">c- type VII collagen.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-158\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">158- The reticular lamina is formed of:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- type IV collagen.<\/li><li data-o=\"b\" tabindex=\"0\">b- type III collagen.<\/li><li data-o=\"c\" tabindex=\"0\">c- type VII collagen.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-159\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">159- The basement membrane can be stained by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- trypan blue.<\/li><li data-o=\"b\" tabindex=\"0\">b- silver.<\/li><li data-o=\"c\" tabindex=\"0\">c- PAS.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both b and c are correct.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-160\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">160- Basement membrane by EM is formed of two layers:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basal lamina and lamina lucida.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basal lamina and lamina densa.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basal lamina and lamina reticularis.<\/li><li data-o=\"d\" tabindex=\"0\">d- None of the above<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-161\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">161- Ion transporting cells need large surface area, so they are characterized by:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- numerous mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- numerous lateral interdigitations.<\/li><li data-o=\"c\" tabindex=\"0\">c- numerous basal infoldings.<\/li><li data-o=\"d\" tabindex=\"0\">d- Both a &amp; c<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-162\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">162- Types of collagen fibers in the basement membranes are:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen II, III &amp; IV<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen I, II &amp; III<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen III, IV &amp; VII<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen IV, V &amp; VI.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-163\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">163- In basement membrane, a major component of basal lamina is:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen type IV.<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen type I<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen type III.<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen type VII.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-164\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">164- Which is true for basement membrane?<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It represents half a desmosome.<\/li><li data-o=\"b\" tabindex=\"0\">b- The basal lamina contains type III collagen.<\/li><li data-o=\"c\" tabindex=\"0\">c- The reticular lamina is the epithelial component.<\/li><li data-o=\"d\" tabindex=\"0\">d- Anchoring fibrils are collagen VII<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4z-165\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">165- Regarding the basement membrane, choose the correct statement:<\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basal lamina has no collagen.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reticular lamina is formed of reticular fibers and ground substance.<\/li><li data-o=\"c\" tabindex=\"0\">c- It is best seen by Janus green.<\/li><li data-o=\"d\" tabindex=\"0\">d- The anchoring fibers are represented by collagen type<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_d08\"><h3>Department MCQs <small>— أسئلة القسم · 49 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_d08\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4d-001\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">1- The epithelium is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It has low power of regeneration.<\/li><li data-o=\"b\" tabindex=\"0\">b- It consists of cells with wide intercellular spaces.<\/li><li data-o=\"c\" tabindex=\"0\">c- It is penetrated by blood vessels.<\/li><li data-o=\"d\" tabindex=\"0\">d- It has clear or non clear basement membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-002\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">2- The surface epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Is modified to give secretion.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is modified to contract.<\/li><li data-o=\"c\" tabindex=\"0\">c- Is modified to receive sensation.<\/li><li data-o=\"d\" tabindex=\"0\">d- Covers surfaces or lines cavities.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-003\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">3- One of the following characteristics is true about epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Contains large amounts of intercellular substance.<\/li><li data-o=\"b\" tabindex=\"0\">b- Penetrated by blood &amp; lymph vessels.<\/li><li data-o=\"c\" tabindex=\"0\">c- Separated from C.T by basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Has a low power of regeneration.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-004\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">4- Simple squamous epithelium is formed of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- One layer of cube-like cells with flat nuclei.<\/li><li data-o=\"b\" tabindex=\"0\">b- One layer of flat cells with rounded nuclei.<\/li><li data-o=\"c\" tabindex=\"0\">c- One layer of flat cells with flat nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Two layers of flat cells with flat nuclei.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- Simple squamous epithelium can be found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lung alveoli.<\/li><li data-o=\"b\" tabindex=\"0\">b- Small intestine.<\/li><li data-o=\"c\" tabindex=\"0\">c- Trachea.<\/li><li data-o=\"d\" tabindex=\"0\">d- Gall bladder.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-006\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">6- Endothelium is the lining epithelium of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pleura.<\/li><li data-o=\"b\" tabindex=\"0\">b- Alveoli.<\/li><li data-o=\"c\" tabindex=\"0\">c- Bowman’s capsule.<\/li><li data-o=\"d\" tabindex=\"0\">d- Blood vessels.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-007\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">7- Mesothelium is the lining epithelium of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lung alveoli.<\/li><li data-o=\"b\" tabindex=\"0\">b- Blood vessels.<\/li><li data-o=\"c\" tabindex=\"0\">c- Thyroid follicle.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pleura.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-008\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">8- The following is true regarding simple squamous epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It’s formed of many layers of cells<\/li><li data-o=\"b\" tabindex=\"0\">b- It forms the mesothelium of serous membranes.<\/li><li data-o=\"c\" tabindex=\"0\">c- It lines the intestinal mucosa.<\/li><li data-o=\"d\" tabindex=\"0\">d- It lines thyroid follicles.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-009\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">9- The following is lined by simple cubical epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Convoluted tubules of kidney.<\/li><li data-o=\"b\" tabindex=\"0\">b- Bowman’s capsule of kidney.<\/li><li data-o=\"c\" tabindex=\"0\">c- The alveoli of the lungs.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lymphatic capillaries.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-010\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">10- Simple squamous epithelium is suitable for<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion.<\/li><li data-o=\"b\" tabindex=\"0\">b- Reabsorption.<\/li><li data-o=\"c\" tabindex=\"0\">c- Gas exchange.<\/li><li data-o=\"d\" tabindex=\"0\">d- Protection.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-011\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">11- The following is lined by simple cubical epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Aorta.<\/li><li data-o=\"b\" tabindex=\"0\">b- Thyroid gland.<\/li><li data-o=\"c\" tabindex=\"0\">c- Pericardium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Lung alveoli.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-012\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">12- One statement is true about simple squamous epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lines the convoluted tubules of kidney.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lines blood vessels.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of many layers of cells resting on basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Penetrated by blood vessels.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-013\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">13- In absorbing columnar cell, the brush border seen by L/M is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cilia.<\/li><li data-o=\"b\" tabindex=\"0\">b- Flagella.<\/li><li data-o=\"c\" tabindex=\"0\">c- Microvilli.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stereocilia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-014\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">14- Simple cubical epithelium is found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Thyroid follicles<\/li><li data-o=\"b\" tabindex=\"0\">b- Gallbladder<\/li><li data-o=\"c\" tabindex=\"0\">c- Lung alveoli<\/li><li data-o=\"d\" tabindex=\"0\">d- Ureter<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-015\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">15- The epithelium lining the digestive tract (GIT) is derived from:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ectoderm.<\/li><li data-o=\"b\" tabindex=\"0\">b- Mesoderm.<\/li><li data-o=\"c\" tabindex=\"0\">c- Endoderm<\/li><li data-o=\"d\" tabindex=\"0\">d- Epidermis.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-016\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">16- The function of simple columnar epithelium Is:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Secretion only.<\/li><li data-o=\"b\" tabindex=\"0\">b- Absorption only.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretion and absorption.<\/li><li data-o=\"d\" tabindex=\"0\">d- Protection.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-017\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">17- Pseudo-stratified columnar ciliated epithelium can be found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Ovary.<\/li><li data-o=\"b\" tabindex=\"0\">b- Blood vessels.<\/li><li data-o=\"c\" tabindex=\"0\">c- Upper respiratory passages.<\/li><li data-o=\"d\" tabindex=\"0\">d- Urinary passage.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Pseudo-stratified columnar ciliated epithelium is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- May be keratinized.<\/li><li data-o=\"b\" tabindex=\"0\">b- Is highly vascular.<\/li><li data-o=\"c\" tabindex=\"0\">c- All cells resting on a basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- It is a type of stratified epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-019\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">19- Simple columnar ciliated epithelium is found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Intestinal absorptive cell.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fallopian tube.<\/li><li data-o=\"c\" tabindex=\"0\">c- Gastric secretory cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Trachea.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- The following is true regarding stratified squamous epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The superficial layer of cells always keratinized<\/li><li data-o=\"b\" tabindex=\"0\">b- It lines the wall of the esophagus.<\/li><li data-o=\"c\" tabindex=\"0\">c- Its most superficial layer of cells is cuboidal cells<\/li><li data-o=\"d\" tabindex=\"0\">d- The intercellular spaces contain mucoid-like substance.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-021\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">21- The stratified squamous epithelium is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Cells connected by desmosomes.<\/li><li data-o=\"b\" tabindex=\"0\">b- It is always keratinized.<\/li><li data-o=\"c\" tabindex=\"0\">c- Found in trachea.<\/li><li data-o=\"d\" tabindex=\"0\">d- All its cells rest on the basement membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-022\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">22- Transitional epithelium is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Well-defined basement membrane.<\/li><li data-o=\"b\" tabindex=\"0\">b- Luminal surface is covered by rigid plaques.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cells connected together by desmosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- May reach up to 30 layers in empty urinary bladder.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-023\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">23- One of the following organs is lined with transitional epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Uterus.<\/li><li data-o=\"b\" tabindex=\"0\">b- Urinary bladder.<\/li><li data-o=\"c\" tabindex=\"0\">c- Vas deferens<\/li><li data-o=\"d\" tabindex=\"0\">d- Gall bladder.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-024\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">24- The following statement is true about transitional epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basement membrane is clear.<\/li><li data-o=\"b\" tabindex=\"0\">b- Superficial cells are columnar.<\/li><li data-o=\"c\" tabindex=\"0\">c- Formed of one layer of cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial cells are dome shaped.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-025\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">25- One statement about transitional epithelium is true:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The superficial cells are flat.<\/li><li data-o=\"b\" tabindex=\"0\">b- Present only in pathological condition.<\/li><li data-o=\"c\" tabindex=\"0\">c- Clear basement membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Associated with the urinary tract.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-026\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">26- Urinary bladder is lined with ........... epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Pseudostratified columnar.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified columnar.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stratified squamous.<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-027\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">27- The following is lined with simple columnar ciliated epithelium<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Renal pelvis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Ureter<\/li><li data-o=\"c\" tabindex=\"0\">c- Uterus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Urinary bladder.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-028\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">28- Transitional epithelium is found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Urinary bladder.<\/li><li data-o=\"b\" tabindex=\"0\">b- Gall bladder.<\/li><li data-o=\"c\" tabindex=\"0\">c- Uterus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Intestine.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-029\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">29- One statement about transitional epithelium is true:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It lines the gall bladder.<\/li><li data-o=\"b\" tabindex=\"0\">b- Has no basement membrane.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basal cells are cuboidal with rounded nuclei.<\/li><li data-o=\"d\" tabindex=\"0\">d- Keratinized epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-030\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">30- Stratified columnar ciliated epithelium can be found in:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Uterus<\/li><li data-o=\"b\" tabindex=\"0\">b- Fallopian tubes.<\/li><li data-o=\"c\" tabindex=\"0\">c- Fetal esophagus.<\/li><li data-o=\"d\" tabindex=\"0\">d- Trachea.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-031\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">31- One statement is true about stratified columnar epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- May be keratinized or non-keratinized<\/li><li data-o=\"b\" tabindex=\"0\">b- Superficial cells are flat.<\/li><li data-o=\"c\" tabindex=\"0\">c- Basal cells are flat.<\/li><li data-o=\"d\" tabindex=\"0\">d- Surface cells are columnar in shape.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-032\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">32- Exocrine glands:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Are only unicellular glands.<\/li><li data-o=\"b\" tabindex=\"0\">b- Discharge secretory product by diffusion into the blood.<\/li><li data-o=\"c\" tabindex=\"0\">c- Discharge their secretion via ducts.<\/li><li data-o=\"d\" tabindex=\"0\">d- Secretes hormones.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-033\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">33- In heavy smokers, pseudo-stratified columnar ciliated epithelium of bronchi may be transformed Into .... epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple columnar.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified columnar ciliated.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple cubical.<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified squamous epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-034\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">34- Glandular epithelium is classified according to mode of secretion into:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Apocrine where no change occurs in the secretory cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Merocrine where the apex of the cell is destroyed during secretion.<\/li><li data-o=\"c\" tabindex=\"0\">c- Merocrine where all the cell is destroyed during secretion.<\/li><li data-o=\"d\" tabindex=\"0\">d- Holocrine where all the cell is destroyed during secretion.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-035\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">35- Holocrine secretion:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Occurs in endocrine gland.<\/li><li data-o=\"b\" tabindex=\"0\">b- Destruction of the whole cell.<\/li><li data-o=\"c\" tabindex=\"0\">c- Destruction of apical parts of cell.<\/li><li data-o=\"d\" tabindex=\"0\">d- No change in secretory cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-036\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">36- Simple branched tubular glands:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Have branched ducts.<\/li><li data-o=\"b\" tabindex=\"0\">b- Are endocrine gland.<\/li><li data-o=\"c\" tabindex=\"0\">c- Have alveolar secretory unit.<\/li><li data-o=\"d\" tabindex=\"0\">d- Have branched secretory part.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-037\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">37- Taste bud is an example of<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Myo-epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Surface epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Secretory epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Neuro-epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-038\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">38- One of the following is correct concerning neuro-epithelium:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Modified type of epithelium to contract.<\/li><li data-o=\"b\" tabindex=\"0\">b- Can be keratinized.<\/li><li data-o=\"c\" tabindex=\"0\">c- Covers skin &amp; forms glands.<\/li><li data-o=\"d\" tabindex=\"0\">d- Is present in the taste buds.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-039\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">39- Myo-epithelial cells are:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present around acini of salivary glands.<\/li><li data-o=\"b\" tabindex=\"0\">b- Found in thyroid gland.<\/li><li data-o=\"c\" tabindex=\"0\">c- Found in pancreas.<\/li><li data-o=\"d\" tabindex=\"0\">d- Modified epithelium which act as a receptor.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-040\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">40- Stereocilia are:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Short microvilli<\/li><li data-o=\"b\" tabindex=\"0\">b- Long microvilli.<\/li><li data-o=\"c\" tabindex=\"0\">c- Motile cilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Short cilia<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-041\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">41- One of the following is a character of the shaft of cilia:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Increase the surface area for absorption.<\/li><li data-o=\"b\" tabindex=\"0\">b- Form the brush border in cells lining the renal tubules.<\/li><li data-o=\"c\" tabindex=\"0\">c- Form the brush border in cells lining the intestine.<\/li><li data-o=\"d\" tabindex=\"0\">d- Contain doublets of microtubules.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-042\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">42- Gap junction is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Present at site of mechanical stress e.g. friction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Intercellular space filled with adhesive material.<\/li><li data-o=\"c\" tabindex=\"0\">c- Condensation of actin at the cytoplasmic side of plasma membrane.<\/li><li data-o=\"d\" tabindex=\"0\">d- Permits the passage of ions.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-043\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">43- Macula adherens (desmosome) is characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Encircles the cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Permits the passage of ions.<\/li><li data-o=\"c\" tabindex=\"0\">c- Important in intercellular communication.<\/li><li data-o=\"d\" tabindex=\"0\">d- Bundles of intermediate filaments are anchored to the plaques.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-044\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">44- Concerning the zonula adherens, one statement is true:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Intermediate filaments are inserted into the attachment plaques.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adjacent cells are separated by a wide gap, crossed by channels.<\/li><li data-o=\"c\" tabindex=\"0\">c- It is a disk-shaped junction between epithelial cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- It encircles the cell like a belt.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-045\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">45- Which type of collagen is a component of the basement membrane?<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type II.<\/li><li data-o=\"b\" tabindex=\"0\">b- Type IV.<\/li><li data-o=\"c\" tabindex=\"0\">c- Type V.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type I.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-046\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">46- Anchoring fibers that fix basement membrane to C.T. are formed of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Type I collagen<\/li><li data-o=\"b\" tabindex=\"0\">b- Elastic.<\/li><li data-o=\"c\" tabindex=\"0\">c- Reticular.<\/li><li data-o=\"d\" tabindex=\"0\">d- Type VII collagen.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-047\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">47- Lon transporting cells are characterized by:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Basal infoldings alternating with mitochondria.<\/li><li data-o=\"b\" tabindex=\"0\">b- Lateral infoldings.<\/li><li data-o=\"c\" tabindex=\"0\">c- Stereocilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- Apical cilia.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-048\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">48- A male old patient, aged 50, has been a heavy smoker for 25 years. He complains of persistent cough and respiratory tract infections. Lining of his major air passages could be found similar to that of:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Intestine<\/li><li data-o=\"b\" tabindex=\"0\">b- Esophagus<\/li><li data-o=\"c\" tabindex=\"0\">c- Thyroid follicles<\/li><li data-o=\"d\" tabindex=\"0\">d- Urinary bladder<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4d-049\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">49- An Egyptian farmer suffers from blood in urine as a complication of bilharziasis. Bladder biopsy could show change of epithelium into:<span class=\"gtag\" dir=\"ltr\">DEP BOOK<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Stratified cuboidal epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple squamous epithelium<\/li><li data-o=\"c\" tabindex=\"0\">c- Ciliated epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified squamous epithelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><section class=\"tsec gsec\" data-g=\"h4_e09\"><h3>Exam MCQs <small>— أسئلة الامتحانات · 23 سؤال<\/small><\/h3><div class=\"tbar\"><button class=\"btn clear sm gclear\" type=\"button\" data-g=\"h4_e09\">Clear<\/button><\/div><div class=\"gq\" data-id=\"c4e-001\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">1- The epithelial tissue is characterized by:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of widely separated cells.<\/li><li data-o=\"b\" tabindex=\"0\">b- Avascular.<\/li><li data-o=\"c\" tabindex=\"0\">c- Great amount of intercellular matrix.<\/li><li data-o=\"d\" tabindex=\"0\">d- Arise only from mesoderm.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-002\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">2- Respiratory epithelium refers to:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple cubical epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified cubical epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar non ciliated epithelium with goblet cells.<\/li><li data-o=\"d\" tabindex=\"0\">d- Pseudostratified columnar ciliated epithelium with goblet cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-003\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">3- Simple branched gland explains that the:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Duct is branched and secretory part is not branched.<\/li><li data-o=\"b\" tabindex=\"0\">b- Duct is not branched but secretory part is branched.<\/li><li data-o=\"c\" tabindex=\"0\">c- Duct and secretory part are not branched.<\/li><li data-o=\"d\" tabindex=\"0\">d- Duct and secretory part are branched.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-004\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">4- Regarding merocrine secretion:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- The whole cell come out with secretion.<\/li><li data-o=\"b\" tabindex=\"0\">b- The least common mode of secretion.<\/li><li data-o=\"c\" tabindex=\"0\">c- The apical part of the cell come out with the secretion.<\/li><li data-o=\"d\" tabindex=\"0\">d- No change occurs in the secretory cell.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-005\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">5- In basement membrane, a major component of basal lamina is:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Collagen type IV.<\/li><li data-o=\"b\" tabindex=\"0\">b- Collagen type III.<\/li><li data-o=\"c\" tabindex=\"0\">c- Collagen type I.<\/li><li data-o=\"d\" tabindex=\"0\">d- Collagen type VII.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-006\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">6- Junctional complex is demonstrated in the cells of:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Superficial layer of transitional epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basal layer of urothelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Intermediate layers of transitional epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Basal layer of stratified cubical epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-007\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">7- The communicating type of junction is:<span class=\"gtag\" dir=\"ltr\">195<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Tight junction.<\/li><li data-o=\"b\" tabindex=\"0\">b- Adherent junction.<\/li><li data-o=\"c\" tabindex=\"0\">c- Gap junction.<\/li><li data-o=\"d\" tabindex=\"0\">d- Desmosomes.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-008\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">8- Regarding the endothelium, it is:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Lining the blood vessels and heart.<\/li><li data-o=\"b\" tabindex=\"0\">b- Formed of columnar cells.<\/li><li data-o=\"c\" tabindex=\"0\">c- Covered by cilia.<\/li><li data-o=\"d\" tabindex=\"0\">d- A type of stratified epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-009\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">9- Follicles of thyroid gland are lined by<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple columnar ciliated epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple squamous epithelium.<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple cubical epithelium.<\/li><li data-o=\"d\" tabindex=\"0\">d- Simple columnar non-ciliated epithelium.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-010\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">10- Concerning pseudostratified columnar epithelium:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- A type of stratified epithelium.<\/li><li data-o=\"b\" tabindex=\"0\">b- All cells reach the surface.<\/li><li data-o=\"c\" tabindex=\"0\">c- Cells are widely separated.<\/li><li data-o=\"d\" tabindex=\"0\">d- All cells rest on basement membrane.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-011\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">11- Simple columnar ciliated epithelium is lining:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Trachea.<\/li><li data-o=\"b\" tabindex=\"0\">b- Fallopian tube.<\/li><li data-o=\"c\" tabindex=\"0\">c- Vas deferens.<\/li><li data-o=\"d\" tabindex=\"0\">d- Vagina.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-012\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">12- Transitional epithelium is characterized by:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Formed of 5-30 layers.<\/li><li data-o=\"b\" tabindex=\"0\">b- Basement membrane is clear and wavy.<\/li><li data-o=\"c\" tabindex=\"0\">c- Intermediate cells are joined by only desmosomes.<\/li><li data-o=\"d\" tabindex=\"0\">d- Superficial layer of cells covered by rigid plaques.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-013\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">13- Regarding holocrine mode of glandular secretion:<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is exocytosis.<\/li><li data-o=\"b\" tabindex=\"0\">b- Apex of the cell comes out with secretion.<\/li><li data-o=\"c\" tabindex=\"0\">c- The whole cell is lost with secretion.<\/li><li data-o=\"d\" tabindex=\"0\">d- No change in secretory cells.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-014\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">14- Concerning Zonula occludens (occluding junction):<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It is a type of apical epithelial specializations.<\/li><li data-o=\"b\" tabindex=\"0\">b- Two adjacent cell membranes fuse at certain points.<\/li><li data-o=\"c\" tabindex=\"0\">c- The adjacent cell membranes are widely separated.<\/li><li data-o=\"d\" tabindex=\"0\">d- It occurs as scattered spots.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-015\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">15- Which is true for basement membrane?<span class=\"gtag\" dir=\"ltr\">196<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- It represents half a desmosome<\/li><li data-o=\"b\" tabindex=\"0\">b- The basal lamina contains type III collagen.<\/li><li data-o=\"c\" tabindex=\"0\">c- The reticular lamina is the epithelial component.<\/li><li data-o=\"d\" tabindex=\"0\">d- Anchoring fibrils are collagen VII.<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-016\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">16- Regarding the holocrine mode of glandular secretion:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- No change in secretory cells<\/li><li data-o=\"b\" tabindex=\"0\">b- Apex of cell come out with secretion<\/li><li data-o=\"c\" tabindex=\"0\">c- The whole cell is lost with secretion<\/li><li data-o=\"d\" tabindex=\"0\">d- The most common type<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-017\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">17- Simple cubical epithelium is found in the following site:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Bowman’s capsule of kidney<\/li><li data-o=\"b\" tabindex=\"0\">b- Convoluted tubules of kidney<\/li><li data-o=\"c\" tabindex=\"0\">c- Endothelium of blood vessels<\/li><li data-o=\"d\" tabindex=\"0\">d- Epidermis of the skin<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-018\" data-k=\"c\"><p class=\"qt\" dir=\"ltr\">18- Lung bronchioles are lined with:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Simple columnar epithelium<\/li><li data-o=\"c\" tabindex=\"0\">c- Simple columnar ciliated epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Stratified squamous epithelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-019\" data-k=\"a\" data-bk=\"c\" data-fx=\"الغشاء القاعدي فيه الكولاجين من النوع IV (الصفيحة القاعدية) والنوع VII (ألياف التثبيت) والنوع III (الألياف الشبكية في الصفيحة الشبكية).\"><p class=\"qt\" dir=\"ltr\">19- Basement membrane shows the following types of collagen:<span class=\"gtag\" dir=\"ltr\">198<\/span><span class=\"gtag fix\" dir=\"rtl\">مفتاح مُصحَّح<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- III, IV &amp; VII<\/li><li data-o=\"b\" tabindex=\"0\">b- I, III &amp; IV<\/li><li data-o=\"c\" tabindex=\"0\">c- IV, V &amp; VII<\/li><li data-o=\"d\" tabindex=\"0\">d- II, III &amp; IV<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-020\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">20- The strongest type of junctions is<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Adherent junction<\/li><li data-o=\"b\" tabindex=\"0\">b- Desmosome<\/li><li data-o=\"c\" tabindex=\"0\">c- Gap junction<\/li><li data-o=\"d\" tabindex=\"0\">d- Tight junction<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-021\" data-k=\"d\"><p class=\"qt\" dir=\"ltr\">21- Pseudostratified columnar ciliated epithelium with stereocilia lines:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Fallopian tube<\/li><li data-o=\"b\" tabindex=\"0\">b- Esophagus<\/li><li data-o=\"c\" tabindex=\"0\">c- Ureter<\/li><li data-o=\"d\" tabindex=\"0\">d- Epididymis<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-022\" data-k=\"a\"><p class=\"qt\" dir=\"ltr\">22- Lung alveoli are lined by:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Simple squamous epithelium<\/li><li data-o=\"b\" tabindex=\"0\">b- Stratified columnar epithelium<\/li><li data-o=\"c\" tabindex=\"0\">c- Respiratory epithelium<\/li><li data-o=\"d\" tabindex=\"0\">d- Transitional epithelium<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><div class=\"gq\" data-id=\"c4e-023\" data-k=\"b\"><p class=\"qt\" dir=\"ltr\">23- Passage of impulses between muscle cells is helped by:<span class=\"gtag\" dir=\"ltr\">198<\/span><\/p><ul class=\"opts\" dir=\"ltr\"><li data-o=\"a\" tabindex=\"0\">a- Zonula adherens<\/li><li data-o=\"b\" tabindex=\"0\">b- Nexus<\/li><li data-o=\"c\" tabindex=\"0\">c- Macula adherens<\/li><li data-o=\"d\" tabindex=\"0\">d- Occluding junction<\/li><\/ul><p class=\"res\" hidden><\/p><\/div><\/section><\/div><\/section>\n<section id=\"tab-exam\" class=\"tabpane\" role=\"tabpanel\" hidden>\n<div id=\"xResume\" class=\"xcard xresume\" hidden><\/div>\n<div id=\"xSetup\">\n<h2 class=\"xh\">منشئ الاختبارات<\/h2>\n<p class=\"note\">كوّن اختبارًا من بنك الأسئلة (<bdi dir=\"ltr\" id=\"xTotal\">0<\/bdi> سؤال له مفتاح مطبوع): اختر الفصول والأقسام وعدد الأسئلة، وفعّل المؤقت أو أوقفه. في آخر الاختبار تحصل على تقرير بنقاط القوة والضعف، ويُحفظ في «مستواك».<\/p>\n<div class=\"xcard\"><h3>١) الأقسام<\/h3>\n<div id=\"xSrc\" class=\"xsrc\" hidden><\/div>\n<div class=\"xrow\"><button type=\"button\" class=\"xchip\" data-act=\"all\">كل الأقسام<\/button><button type=\"button\" class=\"xchip\" data-act=\"none\">إلغاء الكل<\/button><button type=\"button\" class=\"xchip\" id=\"xWeakBtn\" data-act=\"weak\" disabled>أضعف أقسامي<\/button><button type=\"button\" class=\"xchip\" data-act=\"openall\">فتح كل الأجزاء<\/button><button type=\"button\" class=\"xchip\" data-act=\"closeall\">طيّ كل الأجزاء<\/button><\/div>\n<input type=\"search\" id=\"xFind\" class=\"xnum xfind\" placeholder=\"ابحث عن قسم (مثل: mast أو golgi)\" aria-label=\"ابحث عن قسم\" dir=\"ltr\">\n<div id=\"xParts\"><\/div>\n<p class=\"xsum\" id=\"xSum\"><\/p><\/div>\n<div class=\"xcard\"><h3>٢) عدد الأسئلة<\/h3>\n<div class=\"xrow\"><input class=\"xnum\" id=\"xCount\" type=\"number\" min=\"1\" step=\"1\" inputmode=\"numeric\" aria-label=\"عدد الأسئلة\"><span id=\"xPresets\" class=\"xrow\"><\/span><\/div>\n<p class=\"note\" id=\"xAvail\"><\/p><\/div>\n<div class=\"xcard\"><h3>٣) المؤقت<\/h3>\n<div class=\"xrow\"><label><input type=\"checkbox\" id=\"xTimer\"> تفعيل المؤقت<\/label><span id=\"xMinWrap\" class=\"xrow\" hidden>الوقت الكلي <input class=\"xnum\" id=\"xMin\" type=\"number\" min=\"1\" step=\"1\" inputmode=\"numeric\" aria-label=\"الوقت بالدقائق\"> دقيقة<\/span><\/div>\n<p class=\"note\">عند انتهاء الوقت يُسلَّم الاختبار تلقائيًا بما أجبت عنه. بدون مؤقت يُحسب لك الوقت المستغرق فقط.<\/p><\/div>\n<div class=\"xcard\"><h3>٤) خيارات<\/h3>\n<div class=\"xrow\" style=\"flex-direction:column;align-items:flex-start\">\n<label><input type=\"checkbox\" id=\"xShuffle\"> ترتيب عشوائي للأسئلة<\/label>\n<label><input type=\"checkbox\" id=\"xPractice\"> وضع التدريب: إظهار الإجابة الصحيحة بعد كل سؤال<\/label>\n<label><input type=\"checkbox\" id=\"xWrong\"> من الأسئلة التي أخطأت فيها سابقًا فقط (<bdi dir=\"ltr\" id=\"xWrongN\">0<\/bdi>)<\/label><\/div><\/div>\n<button type=\"button\" class=\"btn ok big xstart\" data-act=\"start\">ابدأ الاختبار<\/button>\n<p class=\"xmsg\" id=\"xMsg\" role=\"alert\"><\/p>\n<\/div>\n<div id=\"xRun\" hidden><\/div>\n<div id=\"xRes\" hidden><\/div>\n<div id=\"xTrack\"><\/div>\n<\/section>\n<section id=\"tab-map\" class=\"tabpane\" role=\"tabpanel\" hidden><div class=\"hs-soon\" dir=\"rtl\" lang=\"ar\"><span class=\"hs-ic\" aria-hidden=\"true\">🔗<\/span><h2>الروابط والأرقام<\/h2><p>خريطة الربط بين الفصول وورقة الأرقام المهمة، وتُبنى من معلومات مكتوبة في الكتاب نفسه، فتأتي مع نصه.<\/p><button type=\"button\" class=\"btn\" data-goto=\"galal\">افتح أسئلة د. زهرة<\/button><\/div><\/section>\n<section id=\"tab-prog\" class=\"tabpane\" role=\"tabpanel\" hidden>\n <div class=\"bar\"><div id=\"allbar\"><\/div><\/div><p id=\"allpct\" class=\"note\"><\/p>\n <div class=\"card-bar\"><button id=\"progClear\" class=\"btn clear\" type=\"button\">Clear<\/button><\/div>\n <div id=\"progList\"><\/div>\n <p class=\"note\">التقدم محفوظ على هذا الجهاز/المتصفح فقط. يُحسب هنا من إجاباتك في أسئلة د. زهرة؛ وسيشمل البطاقات واختبارات الكتاب عند إضافتها.<\/p>\n<\/section>\n<section id=\"tab-guide\" class=\"tabpane guide\" role=\"tabpanel\" hidden>\n<h2 dir=\"rtl\">دليل الاستخدام<\/h2>\n<p class=\"note\" dir=\"rtl\">مادة علم الأنسجة تعمل بنفس نظام التشريح تمامًا. المحتوى المتاح الآن: أسئلة الدكتورة زهرة. باقي التبويبات (الدراسة، البطاقات، اختبارات الكتاب، الروابط) جاهزة المكان وتُملأ عند إضافة الكتاب.<\/p>\n<article class=\"gstep\" dir=\"rtl\"><h3><span class=\"gnum\">1<\/span> أسئلة د. زهرة (<bdi dir=\"ltr\">Dr.Zahra MCQs<\/bdi>)<\/h3>\n<p>الأسئلة مرتّبة بالفصول الأربعة: <bdi dir=\"ltr\">Cytology<\/bdi> ثم <bdi dir=\"ltr\">Blood<\/bdi> ثم <bdi dir=\"ltr\">Connective Tissue<\/bdi> ثم <bdi dir=\"ltr\">Epithelium<\/bdi>. كل فصل فيه أقسام المحاضرات بترتيبها، وبعدها «أسئلة القسم» و«أسئلة الامتحانات». اختر قسمًا من القائمة أو اتركها على «كل الأقسام».<\/p>\n<ol class=\"gleg\"><li>اضغط الإجابة التي تراها صحيحة، فيظهر المفتاح المطبوع في الملزمة: الصحيح بالأخضر وإجابتك الخاطئة بالأحمر.<\/li>\n<li>زر <bdi dir=\"ltr\">Clear<\/bdi> أعلى الصفحة يمسح كل إجاباتك، والزر داخل كل قسم يمسح ذلك القسم فقط (اضغط مرتين للتأكيد).<\/li>\n<li>الوسم الصغير بجانب السؤال يبيّن مصدره: <bdi dir=\"ltr\">DEP BOOK<\/bdi> لأسئلة القسم، ورقم الدفعة (مثل <bdi dir=\"ltr\">195<\/bdi>) لأسئلة الامتحانات السابقة. الوسم الأصفر «مفتاح الملزمة مشكوك فيه» يعني أن المفتاح المطبوع يخالف المحتوى العلمي؛ نعرضه كما هو ونذكر لك الإجابة الأرجح عند الإجابة.<\/li><\/ol><\/article>\n<article class=\"gstep\" dir=\"rtl\"><h3><span class=\"gnum\">2<\/span> الاختبار المخصّص ومستواي<\/h3>\n<p>كوّن اختبارًا من أي أقسام تختارها (فصل كامل أو أقسام متفرقة)، وحدّد عدد الأسئلة والمؤقت. في النهاية تحصل على تقرير بنقاط قوتك وضعفك، ويُحفظ مستواك مع الوقت. إذا أُضيف مصدر أسئلة آخر مستقبلًا فستجد خيارًا لدمج المصادر في اختبار واحد أو أخذ كل مصدر وحده.<\/p><\/article>\n<article class=\"gstep\" dir=\"rtl\"><h3><span class=\"gnum\">3<\/span> الألعاب<\/h3>\n<p>«سباق الزمن»: دقيقة واحدة لأكبر عدد من الإجابات الصحيحة. «صح ولا غلط»: سؤال معه إجابة مقترحة وعليك الحكم عليها. ألعاب الكتاب (المطابقة وملء الفراغ) تأتي مع نص الكتاب.<\/p><\/article>\n<article class=\"gstep\" dir=\"rtl\"><h3><span class=\"gnum\">4<\/span> تقدّمي، التصدير، والليلي<\/h3>\n<p>«تقدّمي» يعرض لكل فصل نسبة ما أجبت عنه ودقتك. زرّا التصدير والاستيراد في الشريط العلوي يحفظان كل تقدّمك (التشريح والأنسجة معًا) في ملف ويعيدانه على أي جهاز. زرّا النهاري والليلي يغيّران المظهر، وزر «العمل بدون إنترنت» يحفظ الأداة في المتصفح.<\/p><\/article>\n<\/section>\n<section id=\"tab-games\" class=\"tabpane gm\" role=\"tabpanel\" hidden>\n <div id=\"gmHub\" dir=\"rtl\" lang=\"ar\">\n  <h2>ألعاب من أسئلة الملزمة<\/h2>\n  <p class=\"note\">الألعاب المتاحة الآن مبنية من أسئلة د. زهرة فقط وتعمل بدون إنترنت. ألعاب «مطابقة الأزواج» و«املأ الفراغ» تحتاج نص الكتاب وبطاقاته فتُفتح عند إضافتهما. أرقامك القياسية تتحفظ على جهازك وتدخل في ملف التصدير.<\/p>\n  <div class=\"gm-cards\" id=\"gmCards\"><\/div>\n <\/div>\n <div id=\"gmPlay\" dir=\"rtl\" lang=\"ar\" hidden><\/div>\n <div id=\"gmLive\" class=\"gm-sr\" role=\"status\" aria-live=\"polite\"><\/div>\n<\/section>\n<\/main>"}})(window.MG=window.MG||{});
